button.source:
/**
 * <Button> — six variants, four sizes, and the two states everyone forgets.
 *
 * There is no shortage of button components. What is short is buttons that
 * handle the states a real form puts them in:
 *
 *   loading   the label stays, the spinner replaces the icon slot, and the
 *             width does not change. A button that shrinks to a spinner
 *             moves everything after it, and a button that grows makes the
 *             row reflow at the exact moment the user is watching it.
 *   icon-only  has no text, so it has no accessible name. `aria-label` is
 *             required by the type when `size="icon"` — TypeScript refuses
 *             the unlabelled version rather than an audit finding it later.
 *
 * `loading` also implies `disabled`, but they are not the same prop: a
 * disabled button is one the user may not press, a loading button is one
 * they already pressed. Keeping them separate is what lets the loading one
 * announce itself with `aria-busy` while a disabled one stays silent.
 */

import * as React from 'react'
import { Loader2 } from 'lucide-react'

type Variant = 'primary' | 'secondary' | 'outline' | 'ghost' | 'destructive' | 'link'
type Size = 'sm' | 'md' | 'lg' | 'icon'

const VARIANTS: Record<Variant, string> = {
  primary: 'bg-primary text-primary-foreground hover:bg-primary/90 shadow-sm',
  secondary: 'bg-secondary text-secondary-foreground hover:bg-secondary/80',
  outline: 'border border-border bg-background hover:bg-muted/60 text-foreground',
  ghost: 'text-foreground hover:bg-muted/70',
  destructive: 'bg-destructive text-white hover:bg-destructive/90 shadow-sm',
  link: 'text-primary underline-offset-4 hover:underline',
}

const SIZES: Record<Size, string> = {
  sm: 'h-8 px-3 text-xs gap-1.5',
  md: 'h-9 px-4 text-sm gap-2',
  lg: 'h-11 px-6 text-base gap-2',
  icon: 'h-9 w-9 p-0',
}

type BaseProps = Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'className'> & {
  variant?: Variant
  /** Shown before the label. Replaced by the spinner while loading. */
  icon?: React.ReactNode
  /** Shown after the label — a chevron, a count, an external-link mark. */
  trailingIcon?: React.ReactNode
  /** The user has pressed it and something is happening. Implies disabled. */
  loading?: boolean
  /** Fills its container. Use in a form footer, never in a toolbar. */
  block?: boolean
  className?: string
}

/**
 * An icon button must be labelled; a text button must not be, because its
 * own text is the label and a second one overrides it for screen readers.
 */
export type ButtonProps = BaseProps &
  ({ size: 'icon'; 'aria-label': string } | { size?: Exclude<Size, 'icon'> })

export function Button({
  variant = 'primary',
  size = 'md',
  icon,
  trailingIcon,
  loading = false,
  block = false,
  disabled,
  children,
  className = '',
  ...rest
}: ButtonProps) {
  return (
    <button
      type="button"
      // A loading button is not a disabled one, but it must not be pressed
      // twice — so it is disabled in fact and announced as busy, which is
      // what a screen reader needs to say "working" rather than "dimmed".
      disabled={disabled || loading}
      aria-busy={loading || undefined}
      className={[
        'inline-flex shrink-0 select-none items-center justify-center rounded-lg font-medium',
        'transition-colors focus-visible:outline-none focus-visible:ring-2',
        'focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background',
        'disabled:pointer-events-none disabled:opacity-50',
        VARIANTS[variant],
        SIZES[size],
        block ? 'w-full' : '',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...rest}
    >
      {loading ? (
        <Loader2 className="h-4 w-4 animate-spin motion-reduce:animate-none" aria-hidden />
      ) : (
        icon
      )}
      {/*
        At `size="icon"` the glyph may arrive either way — as `icon`, or as
        the only child. Dropping children outright, which is the obvious
        way to write "no text on an icon button", renders an empty circle
        for every caller who wrote `<Button size="icon"><X /></Button>`;
        that is the shape the JSX invites, so it has to work.
      */}
      {size === 'icon' && icon ? null : children}
      {loading ? null : trailingIcon}
    </button>
  )
}

button-group.source:
/**
 * <ButtonGroup> — buttons joined into one control.
 *
 * Three details decide whether this looks built or bodged, and all three
 * are why people get it wrong by hand:
 *
 *   1. The rounding is on the ENDS, not on each button, and it has to be
 *      logical — `rounded-s-lg` / `rounded-e-lg`. Physical `rounded-l`
 *      puts the flat edge on the outside of the group in Arabic.
 *   2. Adjacent borders must collapse. Two 1px borders meeting make a 2px
 *      seam that is visibly heavier than the outer edge; the fix is a
 *      negative inline-start margin on every button after the first.
 *   3. The pressed button has to paint ABOVE its neighbours, or its focus
 *      ring is clipped by the button next to it. `z-10` on hover/focus.
 *
 * This is a group of independent actions — `role="group"`, each child a
 * plain button. If exactly one child can be active at a time, that is a
 * different control with different semantics, and it is `SegmentedControl`.
 * Using this one for that case means a screen reader announces three
 * buttons and never says which is chosen.
 */

import * as React from 'react'

export interface ButtonGroupItem {
  /** Stable key and the value reported to `onAction`. */
  value: string
  label?: React.ReactNode
  icon?: React.ReactNode
  /** Required when the item has no visible label. */
  'aria-label'?: string
  disabled?: boolean
}

export interface ButtonGroupProps {
  items: ButtonGroupItem[]
  onAction?: (value: string) => void
  orientation?: 'horizontal' | 'vertical'
  size?: 'sm' | 'md'
  /** Names the group for assistive tech, e.g. "Text alignment". */
  label: string
  className?: string
}

export function ButtonGroup({
  items,
  onAction,
  orientation = 'horizontal',
  size = 'md',
  label,
  className = '',
}: ButtonGroupProps) {
  const vertical = orientation === 'vertical'

  return (
    <div
      role="group"
      aria-label={label}
      className={[
        'inline-flex',
        vertical ? 'flex-col' : 'flex-row',
        'isolate',
        className,
      ].join(' ')}
    >
      {items.map((item, i) => {
        const first = i === 0
        const last = i === items.length - 1

        return (
          <button
            key={item.value}
            type="button"
            disabled={item.disabled}
            aria-label={item['aria-label']}
            onClick={() => onAction?.(item.value)}
            className={[
              'relative inline-flex items-center justify-center gap-1.5 border border-border',
              'bg-background font-medium text-foreground transition-colors',
              'hover:bg-muted/70 focus-visible:z-10 focus-visible:outline-none',
              'focus-visible:ring-2 focus-visible:ring-ring',
              'disabled:pointer-events-none disabled:opacity-50',
              size === 'sm' ? 'h-8 px-2.5 text-xs' : 'h-9 px-3 text-sm',
              // Logical radii: the ends of the group, whichever way the
              // document reads.
              vertical
                ? [first ? 'rounded-t-lg' : '', last ? 'rounded-b-lg' : ''].join(' ')
                : [first ? 'rounded-s-lg' : '', last ? 'rounded-e-lg' : ''].join(' '),
              // Collapse the shared border. `-ms-px` is the inline-start
              // margin, so it stays the *shared* edge under RTL.
              first ? '' : vertical ? '-mt-px' : '-ms-px',
            ]
              .filter(Boolean)
              .join(' ')}
          >
            {item.icon}
            {item.label}
          </button>
        )
      })}
    </div>
  )
}

social-buttons.source:
'use client'

/**
 * <SocialButtons> — the row above every sign-in form.
 *
 * The brand marks are inline SVG rather than an icon package, and that is
 * the substance of this component rather than an optimisation. Lucide does
 * not carry brand logos, `react-icons` is 1.2 MB to draw four glyphs, and
 * every provider's brand guidelines require their own mark drawn their own
 * way — Google's is four-colour and may not be recoloured, Apple's is
 * monochrome and must invert with the theme. A `<Chrome />` icon standing
 * in for Google, which is what most catalogs ship, is both wrong and
 * against the terms.
 *
 * The wording is a rule, not a preference: "Continue with Google", never
 * "Sign in with Google". The same button has to serve a new user and a
 * returning one — you do not know which until the OAuth round-trip
 * finishes — and "Sign up" in front of an existing account reads as an
 * error the user is about to make.
 */

import * as React from 'react'
import { Loader2, Mail } from 'lucide-react'

export type SocialProvider = 'google' | 'github' | 'apple' | 'microsoft' | 'email'

export interface SocialButtonsProps {
  providers?: SocialProvider[]
  onSelect?: (provider: SocialProvider) => void
  /** Which one is mid-redirect. Only that button spins; the rest disable. */
  pending?: SocialProvider | null
  /** Side by side once there are more than two, which is the usual case. */
  layout?: 'stack' | 'grid'
  className?: string
}

const LABELS: Record<SocialProvider, string> = {
  google: 'Google',
  github: 'GitHub',
  apple: 'Apple',
  microsoft: 'Microsoft',
  email: 'email',
}

export function SocialButtons({
  providers = ['google', 'github', 'apple'],
  onSelect,
  pending = null,
  layout = 'stack',
  className = '',
}: SocialButtonsProps) {
  return (
    <div
      className={[
        'grid gap-2',
        layout === 'grid' ? 'grid-cols-2' : 'grid-cols-1',
        className,
      ].join(' ')}
    >
      {providers.map((provider) => {
        const isPending = pending === provider
        return (
          <button
            key={provider}
            type="button"
            onClick={() => onSelect?.(provider)}
            // Every button disables while any one of them is redirecting:
            // a second OAuth window opened during the first is a state
            // neither provider handles well.
            disabled={pending !== null}
            aria-busy={isPending || undefined}
            className="inline-flex h-10 items-center justify-center gap-2.5 rounded-lg border border-border bg-background px-4 text-sm font-medium text-foreground transition-colors hover:bg-muted/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-60"
          >
            {isPending ? (
              <Loader2 className="h-4 w-4 animate-spin motion-reduce:animate-none" aria-hidden />
            ) : (
              <ProviderMark provider={provider} />
            )}
            Continue with {LABELS[provider]}
          </button>
        )
      })}
    </div>
  )
}

/**
 * The marks, drawn at 16px on a 24-unit grid.
 *
 * Apple and GitHub use `currentColor` so they invert with the theme, which
 * is what both sets of brand guidelines ask for. Google does not: its mark
 * is four fixed colours and recolouring it is explicitly disallowed, so it
 * looks identical in light and dark — which is correct, not an oversight.
 */
function ProviderMark({ provider }: { provider: SocialProvider }) {
  const common = { width: 16, height: 16, viewBox: '0 0 24 24', 'aria-hidden': true } as const

  if (provider === 'google') {
    return (
      <svg {...common}>
        <path
          fill="#4285F4"
          d="M23.06 12.25c0-.82-.07-1.6-.21-2.36H12v4.47h6.2a5.3 5.3 0 0 1-2.3 3.48v2.9h3.72c2.18-2 3.44-4.96 3.44-8.49Z"
        />
        <path
          fill="#34A853"
          d="M12 23.5c3.11 0 5.72-1.03 7.62-2.79l-3.72-2.89c-1.03.69-2.35 1.1-3.9 1.1-3 0-5.55-2.03-6.46-4.76H1.69v2.98A11.5 11.5 0 0 0 12 23.5Z"
        />
        <path
          fill="#FBBC05"
          d="M5.54 14.16a6.9 6.9 0 0 1 0-4.32V6.86H1.69a11.5 11.5 0 0 0 0 10.28l3.85-2.98Z"
        />
        <path
          fill="#EA4335"
          d="M12 5.08c1.69 0 3.2.58 4.4 1.72l3.3-3.3C17.72 1.62 15.11.5 12 .5A11.5 11.5 0 0 0 1.69 6.86l3.85 2.98C6.45 7.11 9 5.08 12 5.08Z"
        />
      </svg>
    )
  }

  if (provider === 'github') {
    return (
      <svg {...common} fill="currentColor">
        <path d="M12 .5a11.5 11.5 0 0 0-3.64 22.41c.58.1.79-.25.79-.55v-2.1c-3.2.7-3.88-1.37-3.88-1.37-.53-1.34-1.29-1.7-1.29-1.7-1.05-.72.08-.7.08-.7 1.16.08 1.77 1.2 1.77 1.2 1.03 1.77 2.7 1.26 3.36.96.1-.75.4-1.26.73-1.55-2.56-.29-5.25-1.28-5.25-5.7 0-1.26.45-2.29 1.19-3.1-.12-.29-.52-1.46.11-3.05 0 0 .97-.31 3.18 1.18a11 11 0 0 1 5.8 0c2.2-1.5 3.17-1.18 3.17-1.18.63 1.59.24 2.76.12 3.05.74.81 1.19 1.84 1.19 3.1 0 4.43-2.7 5.4-5.27 5.69.41.36.78 1.06.78 2.14v3.17c0 .3.21.66.8.55A11.5 11.5 0 0 0 12 .5Z" />
      </svg>
    )
  }

  if (provider === 'apple') {
    return (
      <svg {...common} fill="currentColor">
        <path d="M17.05 12.7c-.03-2.6 2.12-3.85 2.22-3.91-1.21-1.77-3.1-2.02-3.77-2.04-1.6-.17-3.13.94-3.94.94-.82 0-2.07-.92-3.4-.9-1.75.03-3.36 1.02-4.26 2.58-1.82 3.15-.46 7.8 1.3 10.36.87 1.25 1.9 2.66 3.25 2.6 1.31-.05 1.8-.84 3.38-.84 1.57 0 2.02.84 3.4.82 1.4-.03 2.29-1.27 3.14-2.53.99-1.45 1.4-2.86 1.42-2.93-.03-.01-2.72-1.04-2.74-4.14ZM14.47 4.5c.72-.87 1.2-2.08 1.07-3.29-1.03.04-2.28.69-3.02 1.56-.66.77-1.24 2-1.09 3.18 1.15.09 2.32-.58 3.04-1.45Z" />
      </svg>
    )
  }

  if (provider === 'microsoft') {
    return (
      <svg {...common}>
        <path fill="#F25022" d="M2 2h9.5v9.5H2z" />
        <path fill="#7FBA00" d="M12.5 2H22v9.5h-9.5z" />
        <path fill="#00A4EF" d="M2 12.5h9.5V22H2z" />
        <path fill="#FFB900" d="M12.5 12.5H22V22h-9.5z" />
      </svg>
    )
  }

  return <Mail className="h-4 w-4" aria-hidden />
}

field.source:
'use client'

/**
 * <Field> — the label, hint, error and aria wiring around one input.
 *
 * This is the primitive that is missing from every base library and
 * rebuilt, slightly wrong, in every project. The wiring it owns:
 *
 *   label      `htmlFor` pointing at the control's id
 *   hint       its own id, joined into `aria-describedby`
 *   error      its own id, ALSO joined into `aria-describedby`, plus
 *              `aria-invalid` on the control
 *   required   a visual marker and `aria-required`, which are different
 *              things and both needed
 *
 * The part that is usually wrong is the error. Screen readers announce
 * `aria-describedby`, so an error message that is only visually adjacent is
 * invisible to them; and the hint must stay in the list when an error
 * appears, because "must be 8 characters" is exactly what the person who
 * just failed validation needs to hear.
 *
 * The control is a render prop rather than a cloned child. `cloneElement`
 * reads nicer in a demo and then quietly fails on the first control that is
 * a wrapper — a Radix Select, a react-hook-form Controller, anything that
 * does not forward unknown props to a DOM node. Handing the ids out and
 * letting the caller apply them works for every one of those, and it makes
 * the wiring visible at the call site instead of magic.
 */

import * as React from 'react'
import { AlertCircle } from 'lucide-react'

export interface FieldRenderProps {
  /** Put this on the control. The label's `htmlFor` already points at it. */
  id: string
  /** Spread onto the control: `aria-describedby` and `aria-invalid`. */
  'aria-describedby': string | undefined
  'aria-invalid': boolean | undefined
  'aria-required': boolean | undefined
}

export interface FieldProps {
  label: string
  /** Persistent help text. Stays visible when an error appears. */
  hint?: string
  /** Validation message. Its presence is what makes the field invalid. */
  error?: string
  required?: boolean
  /** Hide the label visually but keep it for screen readers. */
  labelHidden?: boolean
  children: (props: FieldRenderProps) => React.ReactNode
  className?: string
}

export function Field({
  label,
  hint,
  error,
  required = false,
  labelHidden = false,
  children,
  className = '',
}: FieldProps) {
  // `useId` rather than a counter: a server-rendered id has to match the
  // client's or React discards the markup and rerenders the whole subtree.
  const id = React.useId()
  const hintId = `${id}-hint`
  const errorId = `${id}-error`

  const describedBy =
    [hint ? hintId : null, error ? errorId : null].filter(Boolean).join(' ') || undefined

  return (
    <div className={`flex flex-col gap-1.5 ${className}`}>
      <label
        htmlFor={id}
        className={
          labelHidden
            ? 'sr-only'
            : 'text-sm font-medium leading-none text-foreground'
        }
      >
        {label}
        {required ? (
          <>
            {/* The asterisk is decoration; `aria-required` on the control
                is what actually announces it, so this is hidden rather
                than read out as "star". */}
            <span aria-hidden className="ms-1 text-destructive">
              *
            </span>
          </>
        ) : null}
      </label>

      {children({
        id,
        'aria-describedby': describedBy,
        'aria-invalid': error ? true : undefined,
        'aria-required': required || undefined,
      })}

      {hint ? (
        <p id={hintId} className="text-xs text-muted-foreground">
          {hint}
        </p>
      ) : null}

      {error ? (
        <p
          id={errorId}
          /*
           * `role="alert"` announces the message when it appears, which is
           * what you want on submit. It is on the message and not on a
           * permanent wrapper: an empty live region that exists from first
           * paint announces nothing, and a wrapper that is always there
           * re-announces on every keystroke that changes the text.
           */
          role="alert"
          className="flex items-center gap-1.5 text-xs font-medium text-destructive"
        >
          <AlertCircle className="h-3.5 w-3.5 shrink-0" aria-hidden />
          {error}
        </p>
      ) : null}
    </div>
  )
}

input-group.source:
'use client'

/**
 * <InputGroup> — an input with something attached to it.
 *
 * Four shapes, and they are not interchangeable:
 *
 *   addon    a bordered box sharing the input's edge — "https://", ".com",
 *            a currency, a unit. Static text, not interactive.
 *   icon     a glyph INSIDE the field, with padding reserved for it. The
 *            common bug is forgetting the padding, so the caret starts
 *            underneath the magnifier.
 *   action   a button inside the trailing edge — clear, reveal password,
 *            copy. Must be reachable by keyboard and must not be reached
 *            before the input it belongs to.
 *   select   a control sharing the edge, like a country code.
 *
 * Everything here is logical-direction. `ps-9` reserves space at the
 * *start* of the text, so in Arabic the icon and its padding both move to
 * the right together — the physical version puts the icon on the right and
 * leaves the hole on the left.
 *
 * The focus ring is on the group, not the input. A ring around only the
 * middle third of a joined control looks like a rendering bug, so the input
 * drops its own ring and the wrapper grows one via `focus-within`.
 */

import * as React from 'react'

export interface InputGroupProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'size' | 'prefix'> {
  /** Bordered box before the field — "https://", "$", "+44". */
  addonStart?: React.ReactNode
  /** Bordered box after the field — ".com", "USD", "/month". */
  addonEnd?: React.ReactNode
  /** Glyph inside the field at the start. Padding is reserved for it. */
  iconStart?: React.ReactNode
  /** Interactive control inside the field at the end — clear, reveal, copy. */
  action?: React.ReactNode
  invalid?: boolean
  className?: string
}

export function InputGroup({
  addonStart,
  addonEnd,
  iconStart,
  action,
  invalid = false,
  className = '',
  disabled,
  ...rest
}: InputGroupProps) {
  return (
    <div
      className={[
        'flex w-full items-stretch rounded-lg border bg-background text-sm',
        'transition-shadow focus-within:ring-2 focus-within:ring-ring',
        invalid ? 'border-destructive' : 'border-border',
        disabled ? 'opacity-60' : '',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
    >
      {addonStart ? <Addon side="start">{addonStart}</Addon> : null}

      <div className="relative flex min-w-0 flex-1 items-center">
        {iconStart ? (
          <span
            aria-hidden
            // `start-0` and `ps-3` rather than `left-0`/`pl-3`: the icon
            // and the padding that makes room for it have to move together
            // when the document direction flips.
            className="pointer-events-none absolute inset-y-0 start-0 flex items-center ps-3 text-muted-foreground"
          >
            {iconStart}
          </span>
        ) : null}

        <input
          disabled={disabled}
          className={[
            'w-full bg-transparent py-2 text-foreground outline-none',
            'placeholder:text-muted-foreground disabled:cursor-not-allowed',
            iconStart ? 'ps-9' : 'ps-3',
            action ? 'pe-1' : 'pe-3',
          ].join(' ')}
          {...rest}
        />

        {action ? <span className="flex items-center pe-1.5">{action}</span> : null}
      </div>

      {addonEnd ? <Addon side="end">{addonEnd}</Addon> : null}
    </div>
  )
}

/**
 * The bordered box on one end.
 *
 * Its own border is only on the edge it shares with the input, and the
 * group's border draws the rest — two full borders meeting would double up
 * into a heavier seam than the outer edge.
 */
function Addon({ side, children }: { side: 'start' | 'end'; children: React.ReactNode }) {
  return (
    <span
      className={[
        'inline-flex shrink-0 select-none items-center bg-muted/50 px-3',
        'text-sm text-muted-foreground',
        side === 'start' ? 'rounded-s-lg border-e border-border' : 'rounded-e-lg border-s border-border',
      ].join(' ')}
    >
      {children}
    </span>
  )
}

verification-code-input.source:
'use client'

/**
 * <VerificationCodeInput> — the six boxes after "check your email".
 *
 * Almost every hand-rolled version of this fails the only interaction that
 * matters. The user does not type the code; they copy it from the email and
 * paste it, and they paste it into whichever box happens to be focused. So:
 *
 *   paste       distributes across the boxes from the FIRST one, whichever
 *               box received the event, and focus lands on the last filled
 *               box or the first empty one
 *   backspace   in an empty box moves back and clears, rather than doing
 *               nothing and leaving the user pressing it again
 *   arrows      move between boxes; Home and End jump to the ends
 *   overtype    typing in a filled box replaces and advances, instead of
 *               being swallowed by maxLength
 *
 * `autoComplete="one-time-code"` on the first box is what makes iOS offer
 * the code from Messages above the keyboard, and it only works on the
 * first. `inputMode="numeric"` gets the number pad without `type="number"`,
 * which would bring a spinner and accept "e" and "-".
 */

import * as React from 'react'

export interface VerificationCodeInputProps {
  length?: number
  value?: string
  onChange?: (value: string) => void
  /** Fired when the last box is filled — usually submits the form. */
  onComplete?: (value: string) => void
  invalid?: boolean
  disabled?: boolean
  /** Names the whole group, since each box on its own is meaningless. */
  label?: string
  className?: string
}

export function VerificationCodeInput({
  length = 6,
  value,
  onChange,
  onComplete,
  invalid = false,
  disabled = false,
  label = 'Verification code',
  className = '',
}: VerificationCodeInputProps) {
  const [internal, setInternal] = React.useState('')
  const code = value ?? internal
  const refs = React.useRef<(HTMLInputElement | null)[]>([])

  const commit = (next: string) => {
    const clean = next.replace(/\D/g, '').slice(0, length)
    if (value === undefined) setInternal(clean)
    onChange?.(clean)
    if (clean.length === length) onComplete?.(clean)
    return clean
  }

  const focusAt = (index: number) => {
    const target = refs.current[Math.max(0, Math.min(length - 1, index))]
    target?.focus()
    target?.select()
  }

  const handleChange = (index: number, raw: string) => {
    const digits = raw.replace(/\D/g, '')
    if (digits.length === 0) return

    // More than one digit means a paste or an autofill landed here, so it
    // fills forward from this box rather than being truncated to one.
    const chars = code.padEnd(length, ' ').split('')
    for (let i = 0; i < digits.length && index + i < length; i++) {
      chars[index + i] = digits[i]
    }
    const next = commit(chars.join('').trimEnd())
    focusAt(Math.min(index + digits.length, length - 1))
    void next
  }

  const handleKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Backspace') {
      e.preventDefault()
      if (code[index]) {
        commit(code.slice(0, index) + code.slice(index + 1))
        return
      }
      // Empty box: step back and clear the one behind, which is what the
      // user is trying to do when they press it a second time.
      if (index > 0) {
        commit(code.slice(0, index - 1) + code.slice(index))
        focusAt(index - 1)
      }
      return
    }

    // Deliberately physical, not logical. These boxes are a number written
    // left to right in every locale — a verification code is not prose, and
    // RTL users read and type it in the same order.
    if (e.key === 'ArrowLeft') {
      e.preventDefault()
      focusAt(index - 1)
    } else if (e.key === 'ArrowRight') {
      e.preventDefault()
      focusAt(index + 1)
    } else if (e.key === 'Home') {
      e.preventDefault()
      focusAt(0)
    } else if (e.key === 'End') {
      e.preventDefault()
      focusAt(length - 1)
    }
  }

  const handlePaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
    e.preventDefault()
    const digits = e.clipboardData.getData('text').replace(/\D/g, '').slice(0, length)
    if (!digits) return
    // From the first box regardless of which one was focused: a pasted
    // code is the whole code.
    commit(digits)
    focusAt(digits.length >= length ? length - 1 : digits.length)
  }

  return (
    <div
      role="group"
      aria-label={label}
      /*
       * `aria-invalid` is NOT here. The group role does not support it —
       * an assistive technology is free to ignore it, and several do — so
       * the state would be visible and unannounced. It goes on each input
       * below instead, where it is part of the role's own contract.
       */
      className={`flex items-center gap-2 ${className}`}
    >
      {Array.from({ length }, (_, i) => (
        <input
          key={i}
          ref={(el) => {
            refs.current[i] = el
          }}
          type="text"
          inputMode="numeric"
          // Only the first box offers the SMS code; on the rest it makes
          // the platform suggest the whole code into a single digit slot.
          autoComplete={i === 0 ? 'one-time-code' : 'off'}
          maxLength={length}
          disabled={disabled}
          value={code[i] ?? ''}
          aria-label={`Digit ${i + 1} of ${length}`}
          onChange={(e) => handleChange(i, e.target.value)}
          onKeyDown={(e) => handleKeyDown(i, e)}
          onPaste={handlePaste}
          onFocus={(e) => e.currentTarget.select()}
          aria-invalid={invalid || undefined}
          className={[
            'h-12 w-10 rounded-lg border text-center font-mono text-lg font-semibold',
            'text-foreground transition-colors focus:outline-none focus:ring-2 focus:ring-ring',
            'disabled:cursor-not-allowed disabled:opacity-50',
            invalid ? 'border-destructive bg-destructive/5' : 'border-border bg-background',
          ].join(' ')}
        />
      ))}
    </div>
  )
}

stepper.source:
'use client'

/**
 * <Stepper> — a number with a minus and a plus.
 *
 * The one people reach for `<input type="number">` for, and then spend an
 * afternoon on. That element brings a locale-dependent spinner you cannot
 * style, accepts `e`, `+` and `-` anywhere in the string, reports `""` for
 * anything it considers invalid so you cannot tell "empty" from "abc", and
 * on a phone shows a keyboard with a decimal point on a field that wants
 * integers.
 *
 * So the field is a text input with `inputMode="numeric"`, and the
 * component owns the arithmetic:
 *
 *   - the buttons disable AT the bounds, not after crossing them
 *   - ArrowUp/ArrowDown step, PageUp/PageDown step by ten, Home/End jump
 *     to min/max — the same keys the native spinner answers, which is what
 *     a keyboard user will try
 *   - typing is unrestricted while the field has focus and clamped on
 *     blur, because clamping mid-keystroke means typing "25" into a field
 *     with a minimum of 10 rewrites your "2" to "10"
 *
 * `role="spinbutton"` with the three aria-value attributes is what makes a
 * screen reader announce "3 of 10" instead of reading an unlabelled
 * textbox next to two unlabelled buttons.
 */

import * as React from 'react'
import { Minus, Plus } from 'lucide-react'

export interface StepperProps {
  value?: number
  defaultValue?: number
  onChange?: (value: number) => void
  min?: number
  max?: number
  step?: number
  /** Appended after the number — "kg", "seats", "×". */
  unit?: string
  disabled?: boolean
  /** Names the control. Required: "3" on its own means nothing. */
  label: string
  size?: 'sm' | 'md'
  className?: string
}

export function Stepper({
  value,
  defaultValue = 1,
  onChange,
  min = 0,
  max = 99,
  step = 1,
  unit,
  disabled = false,
  label,
  size = 'md',
  className = '',
}: StepperProps) {
  const [internal, setInternal] = React.useState(defaultValue)
  const current = value ?? internal
  const [draft, setDraft] = React.useState<string | null>(null)

  const clamp = (n: number) => Math.min(max, Math.max(min, n))

  const set = (next: number) => {
    const clamped = clamp(next)
    if (value === undefined) setInternal(clamped)
    onChange?.(clamped)
  }

  const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    const jump: Record<string, number> = {
      ArrowUp: step,
      ArrowDown: -step,
      PageUp: step * 10,
      PageDown: -step * 10,
    }
    if (e.key in jump) {
      e.preventDefault()
      setDraft(null)
      set(current + jump[e.key])
    } else if (e.key === 'Home') {
      e.preventDefault()
      setDraft(null)
      set(min)
    } else if (e.key === 'End') {
      e.preventDefault()
      setDraft(null)
      set(max)
    }
  }

  const height = size === 'sm' ? 'h-8' : 'h-9'
  const button =
    'inline-flex aspect-square shrink-0 items-center justify-center text-muted-foreground ' +
    'transition-colors hover:bg-muted/70 hover:text-foreground focus-visible:outline-none ' +
    'focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring ' +
    'disabled:pointer-events-none disabled:opacity-40'

  return (
    <div
      role="spinbutton"
      aria-label={label}
      aria-valuenow={current}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuetext={unit ? `${current} ${unit}` : undefined}
      className={[
        'inline-flex items-stretch overflow-hidden rounded-lg border border-border bg-background',
        'focus-within:ring-2 focus-within:ring-ring',
        height,
        disabled ? 'opacity-60' : '',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
    >
      <button
        type="button"
        // Labelled, because a bare minus sign is announced as "button".
        aria-label={`Decrease ${label}`}
        // Hidden from the accessibility tree's value story: the spinbutton
        // above already reports the number and its bounds, and a screen
        // reader user changes it with the arrow keys.
        tabIndex={-1}
        disabled={disabled || current <= min}
        onClick={() => set(current - step)}
        className={`${button} rounded-s-lg border-e border-border`}
      >
        <Minus className="h-3.5 w-3.5" aria-hidden />
      </button>

      <input
        type="text"
        inputMode="numeric"
        disabled={disabled}
        // While focused the field shows exactly what was typed. Clamping on
        // every keystroke turns "2" into "10" on a field whose minimum is
        // 10, and the user never gets to type the 5.
        value={draft ?? String(current)}
        onChange={(e) => setDraft(e.target.value.replace(/[^\d-]/g, ''))}
        onBlur={() => {
          if (draft !== null) {
            const parsed = Number.parseInt(draft, 10)
            set(Number.isNaN(parsed) ? current : parsed)
            setDraft(null)
          }
        }}
        onKeyDown={onKeyDown}
        aria-label={label}
        className={[
          'w-12 bg-transparent text-center text-sm font-medium tabular-nums',
          'text-foreground outline-none disabled:cursor-not-allowed',
        ].join(' ')}
      />

      {unit ? (
        <span className="flex select-none items-center pe-2 text-xs text-muted-foreground">
          {unit}
        </span>
      ) : null}

      <button
        type="button"
        aria-label={`Increase ${label}`}
        tabIndex={-1}
        disabled={disabled || current >= max}
        onClick={() => set(current + step)}
        className={`${button} rounded-e-lg border-s border-border`}
      >
        <Plus className="h-3.5 w-3.5" aria-hidden />
      </button>
    </div>
  )
}

kbd.source:
'use client'

/**
 * <Kbd> — a keyboard shortcut, rendered for the keyboard it will be typed on.
 *
 * The reason this is a component and not a `<kbd>` tag with a border: the
 * shortcut is different on every platform, and hardcoding one is how a Mac
 * user reads "Ctrl K" next to a search box that does not answer Ctrl K.
 *
 * So a shortcut is written once, in the abstract — `"mod+k"` — and resolved
 * at render: `mod` is ⌘ on Apple platforms and Ctrl everywhere else, `alt`
 * is ⌥ or Alt, `shift` is ⇧ or Shift. Apple's own guidelines say the
 * symbols are shown without separators, which is why the Mac rendering
 * joins them and the Windows one uses a thin space.
 *
 * The platform is read after mount, not during render. `navigator` does not
 * exist on the server, and branching on it during the first client render
 * makes the markup disagree with what the server sent — React then throws
 * the whole tree away and rebuilds it. Rendering the non-Apple form first
 * and correcting it in an effect costs one paint and is always right.
 */

import * as React from 'react'

export interface KbdProps {
  /**
   * The shortcut, as `mod`, `alt`, `shift`, `ctrl`, `meta` and literal keys
   * joined by `+` — `"mod+shift+p"`. Also accepts a sequence: `"g then i"`.
   */
  keys: string
  size?: 'sm' | 'md'
  className?: string
}

const APPLE_SYMBOL: Record<string, string> = {
  mod: '⌘',
  meta: '⌘',
  ctrl: '⌃',
  alt: '⌥',
  shift: '⇧',
  enter: '↩',
  backspace: '⌫',
  delete: '⌦',
  escape: '⎋',
  tab: '⇥',
  space: '␣',
}

const OTHER_LABEL: Record<string, string> = {
  mod: 'Ctrl',
  meta: 'Win',
  ctrl: 'Ctrl',
  alt: 'Alt',
  shift: 'Shift',
  enter: 'Enter',
  backspace: 'Backspace',
  delete: 'Del',
  escape: 'Esc',
  tab: 'Tab',
  space: 'Space',
}

/** True on macOS, iPadOS and iOS. */
function detectApple(): boolean {
  if (typeof navigator === 'undefined') return false
  // `navigator.platform` is deprecated but is the only thing that
  // distinguishes an iPad — which reports a Mac user-agent — reliably
  // enough for a cosmetic choice. Wrong here costs a wrong glyph.
  return /Mac|iPhone|iPad|iPod/.test(navigator.platform || navigator.userAgent)
}

export function Kbd({ keys, size = 'md', className = '' }: KbdProps) {
  const [apple, setApple] = React.useState(false)
  React.useEffect(() => setApple(detectApple()), [])

  const steps = keys.split(/\s+then\s+/i)

  return (
    <span
      className={`inline-flex items-center gap-1 ${className}`}
      /*
       * The rendered form is symbols a screen reader cannot pronounce —
       * "⌘⇧P" is read as nothing useful. The abstract shortcut is the
       * label, spelled out, and the symbols are decoration.
       */
      aria-label={spoken(keys)}
      role="img"
    >
      {steps.map((step, s) => (
        <React.Fragment key={s}>
          {s > 0 ? <span className="text-xs text-muted-foreground">then</span> : null}
          <span aria-hidden className={apple ? 'inline-flex' : 'inline-flex gap-1'}>
            {step.split('+').map((raw, i) => {
              const key = raw.trim().toLowerCase()
              const label = apple
                ? (APPLE_SYMBOL[key] ?? raw.trim().toUpperCase())
                : (OTHER_LABEL[key] ?? raw.trim().toUpperCase())
              return (
                <kbd
                  key={i}
                  className={[
                    'inline-flex select-none items-center justify-center rounded border border-border',
                    'bg-muted/60 font-sans font-medium text-muted-foreground',
                    // The 1px bottom border is the whole "keycap" read. Not
                    // a shadow: a shadow under a chip inside a menu item
                    // smears against the highlight behind it.
                    'border-b-2',
                    size === 'sm'
                      ? 'h-5 min-w-5 px-1 text-[10px]'
                      : 'h-6 min-w-6 px-1.5 text-xs',
                    apple && i > 0 ? '-ms-px' : '',
                  ]
                    .filter(Boolean)
                    .join(' ')}
                >
                  {label}
                </kbd>
              )
            })}
          </span>
        </React.Fragment>
      ))}
    </span>
  )
}

/** "mod+shift+p" → "Command Shift P", for the accessible name. */
function spoken(keys: string): string {
  return keys
    .split(/(\s+then\s+)/i)
    .map((part) =>
      /then/i.test(part)
        ? ' then '
        : part
            .split('+')
            .map((raw) => {
              const key = raw.trim().toLowerCase()
              if (key === 'mod' || key === 'meta') return 'Command'
              if (key === 'ctrl') return 'Control'
              if (key === 'alt') return 'Alt'
              if (key === 'shift') return 'Shift'
              return raw.trim().toUpperCase()
            })
            .join(' '),
    )
    .join('')
    .trim()
}

combobox.source:
'use client'

/**
 * <Combobox> — a select you can type into.
 *
 * A native `<select>` is the right control for five options and the wrong
 * one for five hundred: it cannot be filtered, cannot show two lines per
 * row, and on desktop opens a list nobody can style. Every app ends up
 * building this, and most build it without the keyboard contract, which is
 * the part that makes it a control rather than a div with a list under it.
 *
 * What the WAI-ARIA combobox pattern actually requires, and what is here:
 *
 *   Down/Up      move the active option, opening the list if closed
 *   Home/End     first and last option
 *   Enter        select the active option
 *   Escape       close; a second Escape clears the query
 *   Tab          close and commit, because Tab means "I am done here"
 *   blur         close without selecting
 *
 * The focus never leaves the input. Options are marked active with
 * `aria-activedescendant` rather than by focusing them — moving DOM focus
 * into the list is what breaks typing, and it is the single most common
 * defect in hand-built comboboxes.
 */

import * as React from 'react'
import { Check, ChevronsUpDown, Search } from 'lucide-react'

export interface ComboboxOption {
  value: string
  label: string
  /** Second line — an email under a name, a path under a file. */
  hint?: string
  disabled?: boolean
}

export interface ComboboxProps {
  options: ComboboxOption[]
  value?: string | null
  onChange?: (value: string) => void
  placeholder?: string
  emptyMessage?: string
  disabled?: boolean
  /** Names the control for assistive tech. */
  label: string
  className?: string
}

export function Combobox({
  options,
  value = null,
  onChange,
  placeholder = 'Select…',
  emptyMessage = 'Nothing matches that.',
  disabled = false,
  label,
  className = '',
}: ComboboxProps) {
  const id = React.useId()
  const [open, setOpen] = React.useState(false)
  const [query, setQuery] = React.useState('')
  const [active, setActive] = React.useState(0)
  const rootRef = React.useRef<HTMLDivElement>(null)
  const listRef = React.useRef<HTMLUListElement>(null)

  const selected = options.find((o) => o.value === value) ?? null

  const matches = React.useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return options
    return options.filter(
      (o) =>
        o.label.toLowerCase().includes(q) || (o.hint ?? '').toLowerCase().includes(q),
    )
  }, [options, query])

  // Clamp rather than reset: filtering down to fewer options should not
  // send the highlight back to the top mid-typing if it is still in range.
  React.useEffect(() => {
    setActive((a) => Math.min(a, Math.max(0, matches.length - 1)))
  }, [matches.length])

  /* Keep the active option in view when the arrows walk past the fold. */
  React.useEffect(() => {
    if (!open) return
    listRef.current
      ?.querySelector(`[data-index="${active}"]`)
      ?.scrollIntoView({ block: 'nearest' })
  }, [active, open])

  /* A click outside closes. Pointerdown, not click: a click that starts
     outside and ends inside should still close, and vice versa. */
  React.useEffect(() => {
    if (!open) return
    const onPointerDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false)
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  }, [open])

  const commit = (option: ComboboxOption) => {
    if (option.disabled) return
    onChange?.(option.value)
    setQuery('')
    setOpen(false)
  }

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault()
      if (!open) {
        setOpen(true)
        return
      }
      const delta = e.key === 'ArrowDown' ? 1 : -1
      setActive((a) => (a + delta + matches.length) % Math.max(1, matches.length))
    } else if (e.key === 'Home') {
      e.preventDefault()
      setActive(0)
    } else if (e.key === 'End') {
      e.preventDefault()
      setActive(Math.max(0, matches.length - 1))
    } else if (e.key === 'Enter') {
      if (!open) return
      e.preventDefault()
      const option = matches[active]
      if (option) commit(option)
    } else if (e.key === 'Escape') {
      e.preventDefault()
      // Two meanings, in the order a user expects them: close the list,
      // then — if it was already closed — abandon what they typed.
      if (open) setOpen(false)
      else setQuery('')
    } else if (e.key === 'Tab') {
      setOpen(false)
    }
  }

  return (
    <div ref={rootRef} className={`relative ${className}`}>
      <div
        className={[
          'flex items-center gap-2 rounded-lg border border-border bg-background px-3',
          'focus-within:ring-2 focus-within:ring-ring',
          disabled ? 'opacity-60' : '',
        ]
          .filter(Boolean)
          .join(' ')}
      >
        <Search className="h-4 w-4 shrink-0 text-muted-foreground" aria-hidden />
        <input
          id={id}
          role="combobox"
          aria-expanded={open}
          aria-controls={`${id}-list`}
          aria-autocomplete="list"
          aria-label={label}
          aria-activedescendant={open && matches[active] ? `${id}-opt-${active}` : undefined}
          autoComplete="off"
          disabled={disabled}
          value={open ? query : (selected?.label ?? '')}
          placeholder={selected ? selected.label : placeholder}
          onChange={(e) => {
            setQuery(e.target.value)
            setOpen(true)
          }}
          onFocus={() => setOpen(true)}
          onKeyDown={onKeyDown}
          className="h-9 w-full min-w-0 bg-transparent text-sm text-foreground outline-none placeholder:text-muted-foreground"
        />
        <ChevronsUpDown className="h-4 w-4 shrink-0 text-muted-foreground" aria-hidden />
      </div>

      {open ? (
        <ul
          ref={listRef}
          id={`${id}-list`}
          role="listbox"
          aria-label={label}
          className="absolute z-50 mt-1 max-h-60 w-full overflow-auto rounded-lg border border-border bg-popover p-1 shadow-lg"
        >
          {matches.length === 0 ? (
            <li className="px-3 py-6 text-center text-sm text-muted-foreground">
              {emptyMessage}
            </li>
          ) : (
            matches.map((option, i) => {
              const isSelected = option.value === value
              return (
                <li
                  key={option.value}
                  id={`${id}-opt-${i}`}
                  data-index={i}
                  role="option"
                  aria-selected={isSelected}
                  aria-disabled={option.disabled || undefined}
                  // Pointerdown, not click: click fires after blur, and by
                  // then the list has closed and the option is gone.
                  onPointerDown={(e) => {
                    e.preventDefault()
                    commit(option)
                  }}
                  onPointerEnter={() => setActive(i)}
                  className={[
                    'flex cursor-pointer items-center gap-2 rounded-md px-2.5 py-2 text-sm',
                    option.disabled ? 'pointer-events-none opacity-50' : '',
                    i === active ? 'bg-muted text-foreground' : 'text-foreground',
                  ]
                    .filter(Boolean)
                    .join(' ')}
                >
                  <Check
                    className={`h-4 w-4 shrink-0 ${isSelected ? 'opacity-100' : 'opacity-0'}`}
                    aria-hidden
                  />
                  <span className="min-w-0 flex-1">
                    <span className="block truncate">{option.label}</span>
                    {option.hint ? (
                      <span className="block truncate text-xs text-muted-foreground">
                        {option.hint}
                      </span>
                    ) : null}
                  </span>
                </li>
              )
            })
          )}
        </ul>
      ) : null}
    </div>
  )
}

segmented-control.source:
'use client'

/**
 * <SegmentedControl> — pick exactly one, from two to five.
 *
 * It looks like `ButtonGroup` and is a different control. A button group is
 * a set of actions; this is a single value with several possible states, so
 * it is a radio group — `role="radiogroup"` with `role="radio"` children —
 * and a screen reader says "Month, radio button, 2 of 3, selected". Built
 * as buttons, as most segmented controls are, it announces three unrelated
 * buttons and never says which one is on.
 *
 * That semantic choice brings a keyboard contract with it. A radio group is
 * ONE tab stop: Tab moves into it and out of it, and the arrow keys move
 * between the options, wrapping. That is the roving-tabindex pattern below,
 * and it is why the unselected options have `tabIndex={-1}`.
 *
 * The sliding indicator is a single absolutely positioned element moved
 * with a transform, not a background colour on the selected item. Moving
 * one element animates; repainting backgrounds does not, and the difference
 * is the entire reason this control is nicer than tabs.
 */

import * as React from 'react'

export interface SegmentedOption {
  value: string
  label: string
  icon?: React.ReactNode
  disabled?: boolean
}

export interface SegmentedControlProps {
  options: SegmentedOption[]
  value: string
  onChange: (value: string) => void
  size?: 'sm' | 'md'
  /** Fill the container and split it evenly. */
  block?: boolean
  /** Names the group — "View", "Billing period". */
  label: string
  className?: string
}

export function SegmentedControl({
  options,
  value,
  onChange,
  size = 'md',
  block = false,
  label,
  className = '',
}: SegmentedControlProps) {
  const refs = React.useRef<(HTMLButtonElement | null)[]>([])
  const index = Math.max(0, options.findIndex((o) => o.value === value))

  const move = (delta: number) => {
    const count = options.length
    let next = index
    // Skip disabled options rather than landing on one — the loop bound
    // stops it spinning forever if every other option is disabled.
    for (let i = 0; i < count; i++) {
      next = (next + delta + count) % count
      if (!options[next].disabled) break
    }
    onChange(options[next].value)
    refs.current[next]?.focus()
  }

  const onKeyDown = (e: React.KeyboardEvent) => {
    /*
     * Physical arrow keys mapped through the reading direction. In a
     * right-to-left document the first option is on the right, so ArrowLeft
     * has to move FORWARD through the list — a radio group that walks
     * backwards when you press the key pointing at the next option is the
     * RTL bug nobody catches, because it is invisible in a screenshot.
     */
    const rtl =
      typeof document !== 'undefined' && document.documentElement.dir === 'rtl'
    const forward = rtl ? 'ArrowLeft' : 'ArrowRight'
    const back = rtl ? 'ArrowRight' : 'ArrowLeft'

    if (e.key === forward || e.key === 'ArrowDown') {
      e.preventDefault()
      move(1)
    } else if (e.key === back || e.key === 'ArrowUp') {
      e.preventDefault()
      move(-1)
    } else if (e.key === 'Home') {
      e.preventDefault()
      onChange(options[0].value)
      refs.current[0]?.focus()
    } else if (e.key === 'End') {
      e.preventDefault()
      const last = options.length - 1
      onChange(options[last].value)
      refs.current[last]?.focus()
    }
  }

  return (
    <div
      role="radiogroup"
      aria-label={label}
      onKeyDown={onKeyDown}
      className={[
        'relative isolate inline-flex rounded-lg bg-muted/70 p-1',
        block ? 'flex w-full' : '',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
    >
      {/*
        The indicator, positioned in percentage of the track so it needs no
        measurement pass — which also means it is correct on first paint
        instead of snapping into place after a layout effect.

        `inset-inline-start` via `start-*` is not available as a percentage
        utility, so this uses an inline style with a logical property.
      */}
      <span
        aria-hidden
        className="absolute inset-y-1 z-0 rounded-md bg-background shadow-sm transition-[inset-inline-start] duration-200 ease-out motion-reduce:transition-none"
        style={{
          insetInlineStart: `calc(${(index / options.length) * 100}% + 0.25rem)`,
          width: `calc(${100 / options.length}% - 0.5rem)`,
        }}
      />

      {options.map((option, i) => {
        const selected = option.value === value
        return (
          <button
            key={option.value}
            ref={(el) => {
              refs.current[i] = el
            }}
            type="button"
            role="radio"
            aria-checked={selected}
            disabled={option.disabled}
            // Roving tabindex: the group is one tab stop and the arrows
            // move within it.
            tabIndex={selected ? 0 : -1}
            onClick={() => onChange(option.value)}
            className={[
              'relative z-10 inline-flex flex-1 items-center justify-center gap-1.5 rounded-md',
              'font-medium transition-colors focus-visible:outline-none',
              'focus-visible:ring-2 focus-visible:ring-ring',
              'disabled:pointer-events-none disabled:opacity-40',
              size === 'sm' ? 'h-7 px-2.5 text-xs' : 'h-8 px-3.5 text-sm',
              selected ? 'text-foreground' : 'text-muted-foreground hover:text-foreground',
            ].join(' ')}
          >
            {option.icon}
            {option.label}
          </button>
        )
      })}
    </div>
  )
}

rating.source:
'use client'

/**
 * <Rating> — stars, in both of the two modes people forget are different.
 *
 * A rating widget does two unrelated jobs and the same component is usually
 * shipped for both:
 *
 *   input     the user is choosing. It is a radio group, one tab stop,
 *             arrow keys move, and it needs whole values only — nobody
 *             clicks a half star on purpose.
 *   display   the average of 1,284 ratings. It is 4.3, not 4, so it needs
 *             fractional fill; and it is not interactive, so it must not be
 *             focusable, must not have radio semantics, and should be one
 *             piece of text to a screen reader: "4.3 out of 5".
 *
 * The fractional fill is a clipped overlay rather than a half-star glyph —
 * a `width: 43%` layer over the outlines. Half-star icons only do halves,
 * and an average of 4.3 drawn as 4.5 is a number the page is making up.
 */

import * as React from 'react'
import { Star } from 'lucide-react'

export interface RatingProps {
  value: number
  max?: number
  /** Omit for display mode — that is what makes it non-interactive. */
  onChange?: (value: number) => void
  size?: 'sm' | 'md' | 'lg'
  /** Shown after the stars in display mode: "4.3 (1,284)". */
  count?: number
  /** Names the control when it takes input. */
  label?: string
  className?: string
}

const SIZES = { sm: 'h-3.5 w-3.5', md: 'h-5 w-5', lg: 'h-7 w-7' } as const

export function Rating({
  value,
  max = 5,
  onChange,
  size = 'md',
  count,
  label = 'Rating',
  className = '',
}: RatingProps) {
  const [hover, setHover] = React.useState<number | null>(null)
  const interactive = typeof onChange === 'function'
  const shown = hover ?? value

  /* ---- Display: one label, no focus, fractional fill ---- */

  if (!interactive) {
    const percent = Math.max(0, Math.min(1, value / max)) * 100
    return (
      <span
        className={`inline-flex items-center gap-1.5 ${className}`}
        role="img"
        aria-label={`${value.toFixed(1)} out of ${max}${count === undefined ? '' : `, ${count} ratings`}`}
      >
        <span className="relative inline-flex">
          <span aria-hidden className="inline-flex gap-0.5 text-muted-foreground/40">
            {Array.from({ length: max }, (_, i) => (
              <Star key={i} className={SIZES[size]} />
            ))}
          </span>
          {/*
            The filled layer, clipped to the fraction. `inset-inline-start`
            so the fill grows from the first star in either direction, and
            `overflow-hidden` on a sized box rather than a clip-path, which
            Safari still antialiases badly at small sizes.
          */}
          <span
            aria-hidden
            className="absolute inset-y-0 start-0 overflow-hidden"
            style={{ width: `${percent}%` }}
          >
            <span className="inline-flex gap-0.5 text-amber-400">
              {Array.from({ length: max }, (_, i) => (
                <Star key={i} className={SIZES[size]} fill="currentColor" />
              ))}
            </span>
          </span>
        </span>

        <span className="text-sm font-medium tabular-nums text-foreground">
          {value.toFixed(1)}
        </span>
        {count === undefined ? null : (
          <span className="text-sm text-muted-foreground">
            ({count.toLocaleString()})
          </span>
        )}
      </span>
    )
  }

  /* ---- Input: a radio group over whole values ---- */

  const move = (next: number) => {
    const clamped = Math.max(1, Math.min(max, next))
    onChange?.(clamped)
  }

  return (
    <span
      role="radiogroup"
      aria-label={label}
      className={`inline-flex items-center gap-0.5 ${className}`}
      onPointerLeave={() => setHover(null)}
      onKeyDown={(e) => {
        // Up and Down rather than Left and Right: "more" and "less" are the
        // axis here, and the vertical keys mean the same thing in every
        // reading direction.
        if (e.key === 'ArrowUp' || e.key === 'ArrowRight') {
          e.preventDefault()
          move(value + 1)
        } else if (e.key === 'ArrowDown' || e.key === 'ArrowLeft') {
          e.preventDefault()
          move(value - 1)
        } else if (e.key === 'Home') {
          e.preventDefault()
          move(1)
        } else if (e.key === 'End') {
          e.preventDefault()
          move(max)
        }
      }}
    >
      {Array.from({ length: max }, (_, i) => {
        const star = i + 1
        const filled = star <= shown
        return (
          <button
            key={star}
            type="button"
            role="radio"
            aria-checked={star === value}
            aria-label={`${star} ${star === 1 ? 'star' : 'stars'}`}
            tabIndex={star === value || (value === 0 && star === 1) ? 0 : -1}
            onClick={() => onChange?.(star)}
            onPointerEnter={() => setHover(star)}
            className="rounded p-0.5 transition-transform hover:scale-110 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring motion-reduce:transform-none"
          >
            <Star
              className={`${SIZES[size]} ${filled ? 'text-amber-400' : 'text-muted-foreground/40'}`}
              fill={filled ? 'currentColor' : 'none'}
              aria-hidden
            />
          </button>
        )
      })}
    </span>
  )
}

emoji-selector.source:
'use client'

/**
 * <EmojiSelector> — reactions on a message, and the picker that adds one.
 *
 * The control is the row of counts, not the picker. That is the part that
 * carries state, the part that is pressed most, and the part everyone gets
 * wrong: a reaction pill is a TOGGLE, so it is `aria-pressed`, and it has
 * to say whose reaction it is — "👍 3" tells you nothing about whether one
 * of those three is you, and pressing it is how you find out.
 *
 * So a pill you have reacted with is visually distinct AND announced as
 * pressed, and its accessible name spells out the emoji, which a screen
 * reader otherwise reads as "thumbs up sign" glued to a number.
 *
 * The picker is deliberately a short fixed set rather than a full emoji
 * keyboard. A complete picker is a search index, a skin-tone selector, a
 * category rail and about 40 KB of data — a different component, and one
 * whose absence nobody has ever complained about on a reaction row.
 */

import * as React from 'react'
import { SmilePlus } from 'lucide-react'

export interface Reaction {
  emoji: string
  count: number
  /** Whether the current user is one of the count. */
  reacted?: boolean
  /** Spoken instead of the glyph: "thumbs up". */
  name?: string
}

export interface EmojiSelectorProps {
  reactions: Reaction[]
  onToggle?: (emoji: string) => void
  /** Offered by the "add" button. Kept short on purpose. */
  choices?: string[]
  className?: string
}

const DEFAULT_CHOICES = ['👍', '🎉', '❤️', '🚀', '👀', '😄', '🤔', '✅']

/** Names for the default set, so the pills do not announce raw glyphs. */
const NAMES: Record<string, string> = {
  '👍': 'thumbs up',
  '🎉': 'celebrate',
  '❤️': 'heart',
  '🚀': 'rocket',
  '👀': 'eyes',
  '😄': 'smile',
  '🤔': 'thinking',
  '✅': 'done',
}

export function EmojiSelector({
  reactions,
  onToggle,
  choices = DEFAULT_CHOICES,
  className = '',
}: EmojiSelectorProps) {
  const [open, setOpen] = React.useState(false)
  const rootRef = React.useRef<HTMLDivElement>(null)

  React.useEffect(() => {
    if (!open) return
    const onPointerDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false)
    }
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false)
    }
    document.addEventListener('pointerdown', onPointerDown)
    document.addEventListener('keydown', onKey)
    return () => {
      document.removeEventListener('pointerdown', onPointerDown)
      document.removeEventListener('keydown', onKey)
    }
  }, [open])

  const pick = (emoji: string) => {
    onToggle?.(emoji)
    setOpen(false)
  }

  return (
    <div ref={rootRef} className={`relative inline-flex flex-wrap items-center gap-1 ${className}`}>
      {reactions.map((reaction) => {
        const name = reaction.name ?? NAMES[reaction.emoji] ?? 'reaction'
        return (
          <button
            key={reaction.emoji}
            type="button"
            // A toggle, not a button: the state is "have I reacted", and
            // `aria-pressed` is the only thing that conveys it.
            aria-pressed={reaction.reacted === true}
            aria-label={`${name}, ${reaction.count}`}
            onClick={() => onToggle?.(reaction.emoji)}
            className={[
              'inline-flex h-7 items-center gap-1 rounded-full border px-2 text-xs',
              'transition-colors focus-visible:outline-none focus-visible:ring-2',
              'focus-visible:ring-ring',
              reaction.reacted
                ? 'border-primary/40 bg-primary/10 text-foreground'
                : 'border-border bg-background text-muted-foreground hover:bg-muted/60',
            ].join(' ')}
          >
            <span aria-hidden className="text-sm leading-none">
              {reaction.emoji}
            </span>
            <span className="font-medium tabular-nums">{reaction.count}</span>
          </button>
        )
      })}

      <button
        type="button"
        aria-label="Add a reaction"
        aria-expanded={open}
        aria-haspopup="menu"
        onClick={() => setOpen((o) => !o)}
        className="inline-flex h-7 w-7 items-center justify-center rounded-full border border-dashed border-border text-muted-foreground transition-colors hover:bg-muted/60 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        <SmilePlus className="h-3.5 w-3.5" aria-hidden />
      </button>

      {open ? (
        <div
          role="menu"
          aria-label="Reactions"
          // `bottom-full` and `start-0`: above the row, aligned to the
          // reading start, so it never opens off the edge of a message
          // bubble at the end of a thread.
          className="absolute bottom-full start-0 z-50 mb-1 flex gap-0.5 rounded-lg border border-border bg-popover p-1 shadow-lg"
        >
          {choices.map((emoji) => (
            <button
              key={emoji}
              type="button"
              role="menuitem"
              aria-label={NAMES[emoji] ?? emoji}
              onClick={() => pick(emoji)}
              className="inline-flex h-8 w-8 items-center justify-center rounded-md text-base transition-transform hover:scale-125 hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring motion-reduce:transform-none"
            >
              <span aria-hidden>{emoji}</span>
            </button>
          ))}
        </div>
      ) : null}
    </div>
  )
}

badge.source:
/**
 * <Badge> — a small piece of labelled text.
 *
 * Six tones and three shapes, and the only interesting decision is that
 * tone is separate from shape. Most badge components fuse the two —
 * `variant="destructive"` implying both a red colour and a solid fill — and
 * then a design needs a red outline badge and there is no way to ask for
 * one.
 *
 * The tones are semantic rather than colours: `success`, not `green`. A
 * badge named after its colour is renamed the first time the palette
 * changes, and every call site has to be found.
 */

import * as React from 'react'

export type BadgeTone = 'neutral' | 'brand' | 'success' | 'warning' | 'danger' | 'info'
export type BadgeShape = 'solid' | 'soft' | 'outline'

const TONES: Record<BadgeTone, Record<BadgeShape, string>> = {
  neutral: {
    solid: 'bg-foreground text-background',
    soft: 'bg-muted text-muted-foreground',
    outline: 'border border-border text-muted-foreground',
  },
  brand: {
    solid: 'bg-primary text-primary-foreground',
    soft: 'bg-primary/10 text-primary',
    outline: 'border border-primary/40 text-primary',
  },
  success: {
    solid: 'bg-emerald-600 text-white',
    soft: 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-400',
    outline: 'border border-emerald-500/40 text-emerald-700 dark:text-emerald-400',
  },
  warning: {
    solid: 'bg-amber-500 text-amber-950',
    soft: 'bg-amber-500/10 text-amber-700 dark:text-amber-400',
    outline: 'border border-amber-500/40 text-amber-700 dark:text-amber-400',
  },
  danger: {
    solid: 'bg-destructive text-white',
    soft: 'bg-destructive/10 text-destructive',
    outline: 'border border-destructive/40 text-destructive',
  },
  info: {
    solid: 'bg-sky-600 text-white',
    soft: 'bg-sky-500/10 text-sky-700 dark:text-sky-400',
    outline: 'border border-sky-500/40 text-sky-700 dark:text-sky-400',
  },
}

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  tone?: BadgeTone
  shape?: BadgeShape
  size?: 'sm' | 'md'
  icon?: React.ReactNode
  /** Pill rather than rounded rectangle. Use for counts and statuses. */
  pill?: boolean
}

export function Badge({
  tone = 'neutral',
  shape = 'soft',
  size = 'md',
  pill = false,
  icon,
  className = '',
  children,
  ...rest
}: BadgeProps) {
  return (
    <span
      className={[
        'inline-flex shrink-0 items-center gap-1 font-medium leading-none',
        'whitespace-nowrap',
        pill ? 'rounded-full' : 'rounded-md',
        size === 'sm' ? 'h-5 px-1.5 text-[11px]' : 'h-6 px-2 text-xs',
        TONES[tone][shape],
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      {...rest}
    >
      {icon}
      {children}
    </span>
  )
}

tag-chip.source:
'use client'

/**
 * <TagChip> and <TagInput> — removable tags, and the field that makes them.
 *
 * The chip's whole difficulty is the remove button. It is a button inside
 * another interactive element, which means:
 *
 *   - it needs its own accessible name, and "×" is not one. "Remove
 *     design" is, and it has to include the tag, because a screen reader
 *     user tabbing through eight chips otherwise hears "remove" eight
 *     times with no way to tell which is which
 *   - clicking it must not also trigger the chip, so the click stops
 *     propagating
 *   - after removing, focus has to go somewhere deliberate. It is on a
 *     button that no longer exists, and the browser's answer is to move it
 *     to `<body>` — which drops the keyboard user back to the top of the
 *     page. Focus moves to the next chip, or to the input.
 *
 * That last one is the reason this is a pair of components rather than a
 * chip on its own: only the container knows what the next chip is.
 */

import * as React from 'react'
import { X } from 'lucide-react'

export interface TagChipProps {
  label: string
  onRemove?: () => void
  tone?: 'neutral' | 'brand'
  size?: 'sm' | 'md'
  className?: string
}

export const TagChip = React.forwardRef<HTMLSpanElement, TagChipProps>(
  function TagChip({ label, onRemove, tone = 'neutral', size = 'md', className = '' }, ref) {
    return (
      <span
        ref={ref}
        className={[
          'inline-flex shrink-0 items-center gap-1 rounded-md border font-medium',
          size === 'sm' ? 'h-6 ps-2 text-xs' : 'h-7 ps-2.5 text-sm',
          onRemove ? 'pe-1' : size === 'sm' ? 'pe-2' : 'pe-2.5',
          tone === 'brand'
            ? 'border-primary/30 bg-primary/10 text-primary'
            : 'border-border bg-muted/60 text-foreground',
          className,
        ]
          .filter(Boolean)
          .join(' ')}
      >
        <span className="max-w-[12rem] truncate">{label}</span>
        {onRemove ? (
          <button
            type="button"
            // The tag is in the name, so eight chips do not all announce
            // "remove".
            aria-label={`Remove ${label}`}
            onClick={(e) => {
              e.stopPropagation()
              onRemove()
            }}
            className="inline-flex h-4 w-4 shrink-0 items-center justify-center rounded text-muted-foreground transition-colors hover:bg-foreground/10 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <X className="h-3 w-3" aria-hidden />
          </button>
        ) : null}
      </span>
    )
  },
)

export interface TagInputProps {
  value: string[]
  onChange: (tags: string[]) => void
  placeholder?: string
  max?: number
  label: string
  className?: string
}

export function TagInput({
  value,
  onChange,
  placeholder = 'Add a tag…',
  max,
  label,
  className = '',
}: TagInputProps) {
  const [draft, setDraft] = React.useState('')
  const inputRef = React.useRef<HTMLInputElement>(null)
  const chipRefs = React.useRef<(HTMLSpanElement | null)[]>([])

  const add = (raw: string) => {
    const tag = raw.trim().replace(/,$/, '')
    if (!tag || value.includes(tag)) return
    if (max !== undefined && value.length >= max) return
    onChange([...value, tag])
    setDraft('')
  }

  const removeAt = (index: number) => {
    onChange(value.filter((_, i) => i !== index))
    /*
     * Move focus deliberately. The button that was focused has just been
     * unmounted, and the browser's fallback is `<body>` — which sends a
     * keyboard user back to the top of the document. The next chip is the
     * closest thing to "where they were"; the input is the fallback when
     * the removed chip was the last one.
     */
    requestAnimationFrame(() => {
      const next = chipRefs.current[index] ?? chipRefs.current[index - 1]
      const button = next?.querySelector('button')
      if (button) button.focus()
      else inputRef.current?.focus()
    })
  }

  return (
    <div
      className={[
        'flex flex-wrap items-center gap-1.5 rounded-lg border border-border bg-background p-1.5',
        'focus-within:ring-2 focus-within:ring-ring',
        className,
      ].join(' ')}
      // Clicking the gaps between chips focuses the input, which is what
      // the whole box looks like it should do.
      onClick={() => inputRef.current?.focus()}
    >
      {value.map((tag, i) => (
        <TagChip
          key={tag}
          ref={(el) => {
            chipRefs.current[i] = el
          }}
          label={tag}
          size="sm"
          onRemove={() => removeAt(i)}
        />
      ))}

      <input
        ref={inputRef}
        value={draft}
        aria-label={label}
        placeholder={value.length === 0 ? placeholder : ''}
        disabled={max !== undefined && value.length >= max}
        onChange={(e) => setDraft(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ',') {
            e.preventDefault()
            add(draft)
          } else if (e.key === 'Backspace' && draft === '' && value.length > 0) {
            // Backspace in an empty field removes the last tag — the
            // behaviour every messaging app's recipient field has taught
            // people to expect.
            onChange(value.slice(0, -1))
          }
        }}
        onBlur={() => add(draft)}
        className="h-6 min-w-[8rem] flex-1 bg-transparent px-1 text-sm text-foreground outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed"
      />
    </div>
  )
}

skeleton.source:
/**
 * <Skeleton> — the placeholder, and the two rules that make it work.
 *
 * Rule one: a skeleton must match the shape of what replaces it. A grey
 * rectangle where a three-line paragraph will land means the page jumps
 * when the data arrives, which is worse than a spinner — the spinner at
 * least did not lie about the layout. So this ships shapes (`text`,
 * `avatar`, `card`, `button`) rather than one box, and `lines` makes the
 * last line short, the way a real paragraph ends.
 *
 * Rule two: it is invisible to assistive technology. A screen reader user
 * does not benefit from being told there are six grey rectangles; they
 * benefit from the container saying "loading" once. So every skeleton is
 * `aria-hidden`, and `<SkeletonGroup>` is the live region that speaks.
 *
 * The animation is Tailwind's own `animate-pulse` rather than a sweeping
 * gradient, and that is a deliberate trade. A sweep looks better and needs
 * a `@keyframes` block in the consumer's stylesheet — so the component
 * would paste in, render a static grey box, and give no hint why. A
 * primitive whose appearance depends on config the buyer does not have is
 * worse than a plainer one that always works.
 *
 * Either way it stops under `prefers-reduced-motion`: an animation that
 * never ends is the exact case that setting exists for, and a flat tinted
 * block is still a perfectly good skeleton.
 */

import * as React from 'react'

type Shape = 'text' | 'avatar' | 'card' | 'button' | 'thumbnail'

export interface SkeletonProps {
  shape?: Shape
  /** For `shape="text"`: how many lines. The last one is shortened. */
  lines?: number
  /** Tailwind width class, when the default for the shape is wrong. */
  width?: string
  /** Tailwind height class, same. */
  height?: string
  className?: string
}

const BASE = 'bg-muted/70 animate-pulse motion-reduce:animate-none'

const SHAPES: Record<Shape, string> = {
  text: 'h-3.5 rounded',
  avatar: 'h-10 w-10 rounded-full',
  card: 'h-32 w-full rounded-xl',
  button: 'h-9 w-24 rounded-lg',
  thumbnail: 'h-16 w-16 rounded-lg',
}

export function Skeleton({
  shape = 'text',
  lines = 1,
  width,
  height,
  className = '',
}: SkeletonProps) {
  if (shape === 'text' && lines > 1) {
    return (
      <div aria-hidden className={`flex flex-col gap-2 ${className}`}>
        {Array.from({ length: lines }, (_, i) => (
          <div
            key={i}
            className={[
              BASE,
              SHAPES.text,
              // The last line of a paragraph is never full width, and a
              // stack of identical bars is the tell that this is a
              // placeholder rather than a preview of the shape.
              i === lines - 1 ? 'w-3/5' : 'w-full',
            ].join(' ')}
          />
        ))}
      </div>
    )
  }

  return (
    <div
      aria-hidden
      className={[BASE, SHAPES[shape], width ?? '', height ?? '', className]
        .filter(Boolean)
        .join(' ')}
    />
  )
}

export interface SkeletonGroupProps {
  /** True while loading. When false, renders `children` instead. */
  loading: boolean
  /** What a screen reader is told once, in place of the shapes. */
  label?: string
  skeleton: React.ReactNode
  children?: React.ReactNode
  className?: string
}

/**
 * The wrapper that speaks.
 *
 * `aria-busy` on a `role="status"` region is the whole accessibility story
 * for a loading screen: one announcement, once, instead of a description of
 * the placeholder furniture.
 */
export function SkeletonGroup({
  loading,
  label = 'Loading',
  skeleton,
  children,
  className = '',
}: SkeletonGroupProps) {
  return (
    <div role="status" aria-busy={loading} aria-live="polite" className={className}>
      {loading ? (
        <>
          <span className="sr-only">{label}</span>
          {skeleton}
        </>
      ) : (
        children
      )}
    </div>
  )
}

progress-steps.source:
/**
 * <ProgressSteps> — where you are in something that has an order.
 *
 * The markup is the interesting part. A stepper is a list of steps, in
 * order, so it is an `<ol>` inside a `<nav>` — not a row of divs. That one
 * choice gives screen-reader users the count ("list, 4 items") and the
 * position for free, and `aria-current="step"` names the one you are on.
 * Everything built from divs has to reconstruct all of that with labels,
 * and usually reconstructs none of it.
 *
 * The connector between steps is a sibling element rather than a border on
 * the step, because it has to be half-coloured: the line leaving a
 * completed step is done, the line entering the current one is not. A
 * border cannot be two colours and a gradient cannot animate cleanly
 * between them.
 *
 * The vertical orientation is not a variant of the horizontal one so much
 * as the only usable form on a phone — four labelled steps across a 390px
 * screen leaves about 80px per label, which is one word. Both are here for
 * that reason, not for variety.
 */

import * as React from 'react'
import { Check } from 'lucide-react'

export interface Step {
  label: string
  /** One line under the label. Dropped on the horizontal layout when tight. */
  description?: string
}

export interface ProgressStepsProps {
  steps: Step[]
  /** Index of the step in progress. Everything before it is complete. */
  current: number
  orientation?: 'horizontal' | 'vertical'
  /** Names the sequence: "Checkout", "Onboarding". */
  label: string
  className?: string
}

export function ProgressSteps({
  steps,
  current,
  orientation = 'horizontal',
  label,
  className = '',
}: ProgressStepsProps) {
  const vertical = orientation === 'vertical'

  return (
    <nav aria-label={label} className={className}>
      <ol className={vertical ? 'flex flex-col' : 'flex items-start'}>
        {steps.map((step, i) => {
          const done = i < current
          const active = i === current
          const last = i === steps.length - 1

          const marker = (
            <span
              className={[
                'flex h-8 w-8 shrink-0 items-center justify-center rounded-full border-2',
                'text-xs font-semibold transition-colors',
                done
                  ? 'border-primary bg-primary text-primary-foreground'
                  : active
                    ? 'border-primary bg-background text-primary'
                    : 'border-border bg-background text-muted-foreground',
              ].join(' ')}
            >
              {done ? (
                <>
                  {/* The tick is the only thing marking a step done
                      visually; without the label beside it the state
                      would be carried by colour alone. */}
                  <span className="sr-only">Completed</span>
                  <Check className="h-4 w-4" aria-hidden />
                </>
              ) : (
                i + 1
              )}
            </span>
          )

          const text = (
            <>
              <p
                className={`text-sm font-medium ${active || done ? 'text-foreground' : 'text-muted-foreground'}`}
              >
                {step.label}
              </p>
              {step.description ? (
                <p className="mt-0.5 text-xs text-muted-foreground">{step.description}</p>
              ) : null}
            </>
          )

          if (vertical) {
            return (
              <li
                key={step.label}
                aria-current={active ? 'step' : undefined}
                className="flex gap-3"
              >
                <div className="flex flex-col items-center">
                  {marker}
                  {last ? null : (
                    <span
                      aria-hidden
                      className={`my-1 w-0.5 flex-1 rounded-full ${done ? 'bg-primary' : 'bg-border'}`}
                    />
                  )}
                </div>
                <div className={last ? 'pt-1.5' : 'pb-6 pt-1.5'}>{text}</div>
              </li>
            )
          }

          return (
            <li
              key={step.label}
              aria-current={active ? 'step' : undefined}
              // The last step has no connector, so it must not claim a
              // share of the width — otherwise its label sits in the
              // middle of an empty quarter of the row.
              className={last ? 'flex flex-col' : 'flex flex-1 flex-col'}
            >
              <div className="flex items-center">
                {marker}
                {last ? null : (
                  <span
                    aria-hidden
                    className={`ms-2 h-0.5 flex-1 rounded-full ${done ? 'bg-primary' : 'bg-border'}`}
                  />
                )}
              </div>
              <div className="mt-2 pe-3">{text}</div>
            </li>
          )
        })}
      </ol>
    </nav>
  )
}

tree-view.source:
'use client'

/**
 * <TreeView> — a file tree, with the keyboard contract that makes it one.
 *
 * Nested `<details>` gets you collapsing for free and is genuinely a good
 * answer for a sidebar of three sections. It is not an answer for a tree,
 * because a tree is one tab stop with arrow-key navigation across the whole
 * structure, and `<details>` gives you one tab stop per node.
 *
 * The ARIA tree pattern, and all of it is here:
 *
 *   Down/Up      next/previous VISIBLE node — so a collapsed folder's
 *                children are skipped, which is the part that is fiddly
 *   Right        expand a closed folder; on an open one, move to its first
 *                child; on a leaf, nothing
 *   Left         collapse an open folder; otherwise move to its parent
 *   Home/End     first and last visible node
 *   Enter/Space  select, or toggle a folder
 *   a letter     jump to the next node starting with it
 *
 * Right and Left are mapped through the reading direction: in an RTL tree
 * the children are indented from the right, so ArrowLeft is "go deeper".
 *
 * Only one node is tabbable at a time (`tabIndex={0}`), which is what makes
 * Tab leave the tree rather than walk 400 files.
 */

import * as React from 'react'
import { ChevronRight, File, Folder, FolderOpen } from 'lucide-react'

export interface TreeNode {
  id: string
  label: string
  children?: TreeNode[]
}

export interface TreeViewProps {
  nodes: TreeNode[]
  /** Ids open on first render. */
  defaultExpanded?: string[]
  selectedId?: string
  onSelect?: (node: TreeNode) => void
  /** Names the tree: "Project files". */
  label: string
  className?: string
}

interface Flat {
  node: TreeNode
  depth: number
  parentId: string | null
  expandable: boolean
}

export function TreeView({
  nodes,
  defaultExpanded = [],
  selectedId,
  onSelect,
  label,
  className = '',
}: TreeViewProps) {
  const [expanded, setExpanded] = React.useState<Set<string>>(new Set(defaultExpanded))
  const [focusId, setFocusId] = React.useState<string | null>(null)
  const rootRef = React.useRef<HTMLUListElement>(null)

  /**
   * Every node currently on screen, in visual order.
   *
   * Recomputed from the tree rather than tracked incrementally, because
   * "the next visible node" is a question about the whole structure and
   * the alternative is a linked list that has to be repaired on every
   * expand. A few hundred nodes is nothing; a tree big enough for this to
   * matter needs virtualising, which is a different component.
   */
  const visible = React.useMemo(() => {
    const out: Flat[] = []
    const walk = (list: TreeNode[], depth: number, parentId: string | null) => {
      for (const node of list) {
        const expandable = Array.isArray(node.children) && node.children.length > 0
        out.push({ node, depth, parentId, expandable })
        if (expandable && expanded.has(node.id)) {
          walk(node.children!, depth + 1, node.id)
        }
      }
    }
    walk(nodes, 0, null)
    return out
  }, [nodes, expanded])

  const activeId = focusId ?? selectedId ?? visible[0]?.node.id ?? null
  const activeIndex = visible.findIndex((f) => f.node.id === activeId)

  const focusNode = (id: string) => {
    setFocusId(id)
    // The tree owns focus placement, so it has to move DOM focus too —
    // `aria-activedescendant` is the alternative, and it reads worse in
    // several screen readers for trees specifically.
    requestAnimationFrame(() => {
      rootRef.current?.querySelector<HTMLElement>(`[data-node="${CSS.escape(id)}"]`)?.focus()
    })
  }

  const toggle = (id: string, open?: boolean) => {
    setExpanded((prev) => {
      const next = new Set(prev)
      const shouldOpen = open ?? !next.has(id)
      if (shouldOpen) next.add(id)
      else next.delete(id)
      return next
    })
  }

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (activeIndex < 0) return
    const entry = visible[activeIndex]
    const rtl = typeof document !== 'undefined' && document.documentElement.dir === 'rtl'
    const deeper = rtl ? 'ArrowLeft' : 'ArrowRight'
    const shallower = rtl ? 'ArrowRight' : 'ArrowLeft'

    if (e.key === 'ArrowDown') {
      e.preventDefault()
      const next = visible[activeIndex + 1]
      if (next) focusNode(next.node.id)
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      const prev = visible[activeIndex - 1]
      if (prev) focusNode(prev.node.id)
    } else if (e.key === deeper) {
      e.preventDefault()
      if (entry.expandable && !expanded.has(entry.node.id)) {
        toggle(entry.node.id, true)
      } else if (entry.expandable) {
        const child = visible[activeIndex + 1]
        if (child) focusNode(child.node.id)
      }
    } else if (e.key === shallower) {
      e.preventDefault()
      if (entry.expandable && expanded.has(entry.node.id)) {
        toggle(entry.node.id, false)
      } else if (entry.parentId) {
        focusNode(entry.parentId)
      }
    } else if (e.key === 'Home') {
      e.preventDefault()
      if (visible[0]) focusNode(visible[0].node.id)
    } else if (e.key === 'End') {
      e.preventDefault()
      const last = visible[visible.length - 1]
      if (last) focusNode(last.node.id)
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      if (entry.expandable) toggle(entry.node.id)
      else onSelect?.(entry.node)
    } else if (e.key.length === 1 && /\S/.test(e.key)) {
      // Typeahead, wrapping from the current position — the behaviour a
      // file list has in every OS.
      const letter = e.key.toLowerCase()
      const order = [
        ...visible.slice(activeIndex + 1),
        ...visible.slice(0, activeIndex + 1),
      ]
      const hit = order.find((f) => f.node.label.toLowerCase().startsWith(letter))
      if (hit) focusNode(hit.node.id)
    }
  }

  return (
    <ul
      ref={rootRef}
      role="tree"
      aria-label={label}
      onKeyDown={onKeyDown}
      className={`select-none text-sm ${className}`}
    >
      {visible.map((entry) => {
        const { node, depth, expandable } = entry
        const isOpen = expanded.has(node.id)
        const isSelected = node.id === selectedId

        return (
          <li
            key={node.id}
            role="treeitem"
            aria-expanded={expandable ? isOpen : undefined}
            aria-selected={isSelected}
            // The depth has to be stated: the flattened list has no nesting
            // for a screen reader to infer it from.
            aria-level={depth + 1}
            data-node={node.id}
            // Roving tabindex — one stop for the whole tree.
            tabIndex={node.id === activeId ? 0 : -1}
            onFocus={() => setFocusId(node.id)}
            onClick={() => {
              if (expandable) toggle(node.id)
              else onSelect?.(node)
            }}
            className={[
              'flex cursor-pointer items-center gap-1.5 rounded-md py-1 pe-2',
              'outline-none focus-visible:ring-2 focus-visible:ring-ring',
              isSelected ? 'bg-primary/10 text-primary' : 'text-foreground hover:bg-muted/60',
            ].join(' ')}
            // Indentation is inline because the depth is data, not a fixed
            // set of classes — `padding-inline-start` so the tree indents
            // away from the reading edge in both directions.
            style={{ paddingInlineStart: `${depth * 1.125 + 0.5}rem` }}
          >
            {expandable ? (
              <ChevronRight
                className={`h-3.5 w-3.5 shrink-0 text-muted-foreground transition-transform rtl:-scale-x-100 ${isOpen ? 'rotate-90 rtl:-rotate-90' : ''}`}
                aria-hidden
              />
            ) : (
              <span aria-hidden className="w-3.5 shrink-0" />
            )}

            {expandable ? (
              isOpen ? (
                <FolderOpen className="h-4 w-4 shrink-0 text-muted-foreground" aria-hidden />
              ) : (
                <Folder className="h-4 w-4 shrink-0 text-muted-foreground" aria-hidden />
              )
            ) : (
              <File className="h-4 w-4 shrink-0 text-muted-foreground" aria-hidden />
            )}

            <span className="truncate">{node.label}</span>
          </li>
        )
      })}
    </ul>
  )
}

avatar-group.source:
'use client'

/**
 * <AvatarGroup> — overlapping faces with an honest overflow count.
 *
 * Two things are usually wrong with this component.
 *
 * The first is the stacking order. Avatars overlap, and the default paint
 * order puts each one on top of the last — so the stack reads
 * right-to-left, the overflow chip sits *under* the avatar before it, and
 * the ring around the first face is clipped. Fixing it means an explicit
 * descending `z-index`, which also has to survive `isolation` so it does
 * not fight the page's own stacking contexts.
 *
 * The second is the count. `+3` next to five avatars is ambiguous — three
 * more, or three total? It is announced here as "and 3 more", and the
 * group's accessible name is the whole list, so a screen reader user hears
 * who is actually on the team rather than "image image image".
 *
 * Initials, not a broken image icon, are the fallback. A missing avatar is
 * the normal case in any product where people have not uploaded one, and
 * the initials are derived from the same name that is already required for
 * the alt text.
 */

import * as React from 'react'

export interface AvatarPerson {
  name: string
  src?: string
}

export interface AvatarGroupProps {
  people: AvatarPerson[]
  /** How many faces before the rest collapse into a count. */
  max?: number
  size?: 'sm' | 'md' | 'lg'
  /** Names the group: "Project members". */
  label?: string
  className?: string
}

const SIZES = {
  sm: { box: 'h-6 w-6 text-[10px]', ring: 'ring-2', overlap: '-ms-2' },
  md: { box: 'h-8 w-8 text-xs', ring: 'ring-2', overlap: '-ms-2.5' },
  lg: { box: 'h-11 w-11 text-sm', ring: 'ring-[3px]', overlap: '-ms-3' },
} as const

/** "Ada Lovelace" → "AL"; "cher" → "C". */
function initials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean)
  if (parts.length === 0) return '?'
  if (parts.length === 1) return parts[0][0].toUpperCase()
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase()
}

/**
 * A stable colour per person, from the name.
 *
 * Deterministic rather than random: the same person is the same colour on
 * every page and after every reload, which is most of what makes initials
 * readable as identity at all.
 */
function tint(name: string): string {
  const palette = [
    'bg-rose-500/15 text-rose-700 dark:text-rose-300',
    'bg-amber-500/15 text-amber-700 dark:text-amber-300',
    'bg-emerald-500/15 text-emerald-700 dark:text-emerald-300',
    'bg-sky-500/15 text-sky-700 dark:text-sky-300',
    'bg-violet-500/15 text-violet-700 dark:text-violet-300',
    'bg-fuchsia-500/15 text-fuchsia-700 dark:text-fuchsia-300',
  ]
  let hash = 0
  for (let i = 0; i < name.length; i++) hash = (hash * 31 + name.charCodeAt(i)) >>> 0
  return palette[hash % palette.length]
}

export function AvatarGroup({
  people,
  max = 4,
  size = 'md',
  label = 'Members',
  className = '',
}: AvatarGroupProps) {
  const shown = people.slice(0, max)
  const overflow = people.length - shown.length
  const s = SIZES[size]

  return (
    <div
      role="group"
      // The whole list, not "4 images". This is the accessible content of
      // the component; everything inside is hidden from the tree.
      aria-label={`${label}: ${people.map((p) => p.name).join(', ')}`}
      // `isolation` so the descending z-indexes below resolve against this
      // group and cannot be reordered by a stacking context on the page.
      className={`isolate flex items-center ${className}`}
    >
      {shown.map((person, i) => (
        <span
          key={`${person.name}-${i}`}
          aria-hidden
          title={person.name}
          // Descending, so each avatar paints OVER the one after it and
          // the stack reads from the first face.
          style={{ zIndex: shown.length - i }}
          className={[
            'relative inline-flex shrink-0 items-center justify-center overflow-hidden',
            'rounded-full font-semibold ring-background',
            s.box,
            s.ring,
            i === 0 ? '' : s.overlap,
            person.src ? 'bg-muted' : tint(person.name),
          ]
            .filter(Boolean)
            .join(' ')}
        >
          {person.src ? (
            /* A plain <img>, not next/image: a primitive has to paste
               into a Vite, CRA or Remix project unchanged, and the alt is
               empty because the group's own label already names everyone
               in it. */
            <img src={person.src} alt="" className="h-full w-full object-cover" />
          ) : (
            initials(person.name)
          )}
        </span>
      ))}

      {overflow > 0 ? (
        <span
          aria-hidden
          style={{ zIndex: 0 }}
          className={[
            'relative inline-flex shrink-0 items-center justify-center rounded-full',
            'bg-muted font-semibold text-muted-foreground ring-background',
            s.box,
            s.ring,
            s.overlap,
          ].join(' ')}
        >
          +{overflow}
        </span>
      ) : null}
    </div>
  )
}

featured-icon.source:
/**
 * <FeaturedIcon> — an icon in a container, which is a different thing.
 *
 * This is the single most repeated element in a marketing or empty-state
 * design and nobody ships it: a glyph, centred in a shaped and tinted box,
 * at one of a few sizes. Every feature grid, every empty state, every
 * "what's included" row is a stack of these, and each project rebuilds the
 * ring-and-tint arithmetic by hand.
 *
 * The variants are the ones that actually recur:
 *
 *   soft     tinted background, coloured glyph. The default.
 *   solid    filled with the tone, glyph knocked out.
 *   outline  border only, for dense layouts where a filled square is loud.
 *   ring     soft, with two concentric translucent rings — the "halo"
 *            treatment used in empty states, where the icon carries a
 *            whole screen and needs the extra presence.
 *
 * It is decoration, and it is marked as such. A featured icon sits next to
 * a heading that says the same thing, so announcing it is a duplicate. Pass
 * `label` on the rare occasion it is the only content — then it becomes an
 * `img` role with a name instead of being hidden.
 */

import * as React from 'react'

export type IconTone = 'brand' | 'neutral' | 'success' | 'warning' | 'danger'
export type IconVariant = 'soft' | 'solid' | 'outline' | 'ring'

const TONES: Record<IconTone, { soft: string; solid: string; outline: string; halo: string }> = {
  brand: {
    soft: 'bg-primary/10 text-primary',
    solid: 'bg-primary text-primary-foreground',
    outline: 'border border-primary/30 text-primary',
    halo: 'ring-primary/10',
  },
  neutral: {
    soft: 'bg-muted text-muted-foreground',
    solid: 'bg-foreground text-background',
    outline: 'border border-border text-muted-foreground',
    halo: 'ring-foreground/5',
  },
  success: {
    soft: 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400',
    solid: 'bg-emerald-600 text-white',
    outline: 'border border-emerald-500/30 text-emerald-600 dark:text-emerald-400',
    halo: 'ring-emerald-500/10',
  },
  warning: {
    soft: 'bg-amber-500/10 text-amber-600 dark:text-amber-400',
    solid: 'bg-amber-500 text-amber-950',
    outline: 'border border-amber-500/30 text-amber-600 dark:text-amber-400',
    halo: 'ring-amber-500/10',
  },
  danger: {
    soft: 'bg-destructive/10 text-destructive',
    solid: 'bg-destructive text-white',
    outline: 'border border-destructive/30 text-destructive',
    halo: 'ring-destructive/10',
  },
}

const SIZES = {
  sm: 'h-8 w-8 rounded-lg [&>svg]:h-4 [&>svg]:w-4',
  md: 'h-10 w-10 rounded-xl [&>svg]:h-5 [&>svg]:w-5',
  lg: 'h-12 w-12 rounded-xl [&>svg]:h-6 [&>svg]:w-6',
  xl: 'h-14 w-14 rounded-2xl [&>svg]:h-7 [&>svg]:w-7',
} as const

export interface FeaturedIconProps {
  /** The glyph. Sized by the container, so pass it without size classes. */
  children: React.ReactNode
  tone?: IconTone
  variant?: IconVariant
  size?: keyof typeof SIZES
  /** Circle instead of the rounded square. */
  circle?: boolean
  /** Only when the icon is the sole content. Otherwise it stays decorative. */
  label?: string
  className?: string
}

export function FeaturedIcon({
  children,
  tone = 'brand',
  variant = 'soft',
  size = 'md',
  circle = false,
  label,
  className = '',
}: FeaturedIconProps) {
  const palette = TONES[tone]

  const surface =
    variant === 'solid'
      ? palette.solid
      : variant === 'outline'
        ? palette.outline
        : palette.soft

  return (
    <span
      // Hidden by default: it sits beside a heading that already says this.
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      className={[
        'inline-flex shrink-0 items-center justify-center',
        SIZES[size],
        circle ? 'rounded-full' : '',
        surface,
        // The halo is two rings rather than one wide one, so the falloff
        // reads as a glow instead of a second border.
        variant === 'ring' ? `ring-[6px] ${palette.halo}` : '',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
    >
      {children}
    </span>
  )
}

color-picker.source:
'use client'

/**
 * <ColorPicker> — a swatch grid, a hex field, and the native picker.
 *
 * Deliberately not a saturation-value square with a hue slider. That
 * control is a pointer-capture problem, a colour-space conversion and a
 * keyboard story of its own, and in a product it is almost always the wrong
 * offer: people picking a brand colour paste a hex, and people picking a
 * label colour want the eight the design system allows. So this is the two
 * cases that matter, plus `<input type="color">` as the escape hatch —
 * which is a real, accessible, platform-native picker that costs nothing.
 *
 * The hex field accepts what people actually paste: `#a1b2c3`, `a1b2c3`,
 * `#abc`, and uppercase. It normalises on blur rather than on keystroke,
 * because rewriting the field while somebody is typing the fourth character
 * of six is how you make a field impossible to type into.
 *
 * The swatch grid is a radio group — one value, several options — so it is
 * one tab stop with arrow keys, not eleven tab stops.
 */

import * as React from 'react'
import { Check, Pipette } from 'lucide-react'

export interface ColorPickerProps {
  value: string
  onChange: (hex: string) => void
  /** The palette offered. Keep it to what the design system allows. */
  swatches?: string[]
  /** Hide the free-text hex field to restrict input to the swatches. */
  allowCustom?: boolean
  label: string
  className?: string
}

const DEFAULT_SWATCHES = [
  '#0f172a', '#64748b', '#ef4444', '#f97316', '#eab308', '#22c55e',
  '#14b8a6', '#3b82f6', '#6366f1', '#a855f7', '#ec4899', '#ffffff',
]

/** `#abc` / `abc` / `A1B2C3` → `#a1b2c3`, or null if it is not a colour. */
export function normaliseHex(raw: string): string | null {
  const value = raw.trim().replace(/^#/, '')
  if (/^[0-9a-f]{3}$/i.test(value)) {
    return `#${value[0]}${value[0]}${value[1]}${value[1]}${value[2]}${value[2]}`.toLowerCase()
  }
  if (/^[0-9a-f]{6}$/i.test(value)) return `#${value.toLowerCase()}`
  return null
}

/**
 * Whether to draw the tick in black or white on a given swatch.
 *
 * Relative luminance, not a naive average: the eye is far more sensitive to
 * green than to blue, and averaging puts a white tick on a yellow swatch
 * where it disappears.
 */
function isLight(hex: string): boolean {
  const n = Number.parseInt(hex.slice(1), 16)
  const [r, g, b] = [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((c) => {
    const s = c / 255
    return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4
  })
  return 0.2126 * r + 0.7152 * g + 0.0722 * b > 0.45
}

export function ColorPicker({
  value,
  onChange,
  swatches = DEFAULT_SWATCHES,
  allowCustom = true,
  label,
  className = '',
}: ColorPickerProps) {
  const [draft, setDraft] = React.useState<string | null>(null)
  const refs = React.useRef<(HTMLButtonElement | null)[]>([])
  const index = swatches.findIndex((s) => s.toLowerCase() === value.toLowerCase())

  const move = (delta: number) => {
    const next = (Math.max(0, index) + delta + swatches.length) % swatches.length
    onChange(swatches[next])
    refs.current[next]?.focus()
  }

  return (
    <div className={`flex flex-col gap-3 ${className}`}>
      <div
        role="radiogroup"
        aria-label={label}
        onKeyDown={(e) => {
          // A grid, so all four arrows move: horizontally by one, and
          // vertically by a row. The row length is the grid's column count.
          const columns = 6
          const map: Record<string, number> = {
            ArrowRight: 1,
            ArrowLeft: -1,
            ArrowDown: columns,
            ArrowUp: -columns,
          }
          if (e.key in map) {
            e.preventDefault()
            move(map[e.key])
          }
        }}
        className="grid grid-cols-6 gap-2"
      >
        {swatches.map((swatch, i) => {
          const selected = swatch.toLowerCase() === value.toLowerCase()
          return (
            <button
              key={swatch}
              ref={(el) => {
                refs.current[i] = el
              }}
              type="button"
              role="radio"
              aria-checked={selected}
              // The hex IS the name. "Swatch 4" tells a screen reader user
              // nothing, and the colour name is not knowable from the value.
              aria-label={swatch}
              tabIndex={selected || (index === -1 && i === 0) ? 0 : -1}
              onClick={() => onChange(swatch)}
              style={{ backgroundColor: swatch }}
              className="flex h-8 w-full items-center justify-center rounded-md border border-border/60 transition-transform hover:scale-105 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background motion-reduce:transform-none"
            >
              {selected ? (
                <Check
                  className={`h-4 w-4 ${isLight(swatch) ? 'text-slate-900' : 'text-white'}`}
                  aria-hidden
                />
              ) : null}
            </button>
          )
        })}
      </div>

      {allowCustom ? (
        <div className="flex items-center gap-2">
          <div className="flex h-9 flex-1 items-center rounded-lg border border-border bg-background ps-2.5 focus-within:ring-2 focus-within:ring-ring">
            <span
              aria-hidden
              style={{ backgroundColor: value }}
              className="h-4 w-4 shrink-0 rounded border border-border/60"
            />
            <input
              value={draft ?? value}
              aria-label={`${label} hex value`}
              spellCheck={false}
              onChange={(e) => setDraft(e.target.value)}
              onBlur={() => {
                // Normalised here, not per keystroke: rewriting "#a1b" to
                // "#aa11bb" while somebody is typing "#a1b2c3" makes the
                // field impossible to use.
                const hex = normaliseHex(draft ?? '')
                if (hex) onChange(hex)
                setDraft(null)
              }}
              onKeyDown={(e) => {
                if (e.key === 'Enter') e.currentTarget.blur()
                if (e.key === 'Escape') setDraft(null)
              }}
              className="w-full bg-transparent px-2 font-mono text-sm uppercase text-foreground outline-none"
            />
          </div>

          <label className="relative inline-flex h-9 w-9 shrink-0 cursor-pointer items-center justify-center rounded-lg border border-border bg-background text-muted-foreground transition-colors hover:bg-muted/60 focus-within:ring-2 focus-within:ring-ring">
            <Pipette className="h-4 w-4" aria-hidden />
            <span className="sr-only">Open the system colour picker</span>
            {/*
              The native picker, made invisible rather than hidden: a
              `display:none` input cannot be opened by clicking its label in
              Safari, and `visibility:hidden` has the same problem.
            */}
            <input
              type="color"
              value={value}
              onChange={(e) => onChange(e.target.value)}
              className="absolute inset-0 h-full w-full cursor-pointer opacity-0"
            />
          </label>
        </div>
      ) : null}
    </div>
  )
}

gradient-picker.source:
'use client'

/**
 * <GradientPicker> — stops on a track, an angle, and the CSS it produces.
 *
 * The component that is always a one-off. Every product that lets you brand
 * something needs it, nobody ships it, and the reason is that a gradient is
 * not one value — it is an ordered list of (colour, position) pairs plus a
 * type and an angle, and a control for it has to keep that list sorted
 * while the user drags one stop past another.
 *
 * The decisions worth naming:
 *
 *   - Stops are dragged on a track with pointer capture, so a drag that
 *     leaves the element still tracks. `setPointerCapture` rather than
 *     document listeners: the browser cleans up on its own if the pointer
 *     is lost, which document listeners famously do not.
 *   - The list is kept sorted by position at all times, so the emitted CSS
 *     is valid no matter what order the user made them in. An unsorted
 *     `linear-gradient` is not an error — it silently renders wrong.
 *   - Position is a percentage, snapped to whole numbers. Sub-pixel stop
 *     positions produce CSS nobody can read and no design needs.
 *   - The output string is shown and copyable, because that is what the
 *     user came for. A picker whose value only lives in React state is a
 *     toy.
 */

import * as React from 'react'
import { Plus, Trash2 } from 'lucide-react'

export interface GradientStop {
  color: string
  /** 0–100. */
  position: number
}

export interface GradientValue {
  type: 'linear' | 'radial'
  /** Degrees, for linear only. */
  angle: number
  stops: GradientStop[]
}

export interface GradientPickerProps {
  value: GradientValue
  onChange: (value: GradientValue) => void
  label?: string
  className?: string
}

/** The CSS for a gradient value. Stops are sorted, so this is always valid. */
export function gradientCss(value: GradientValue): string {
  const stops = [...value.stops]
    .sort((a, b) => a.position - b.position)
    .map((s) => `${s.color} ${Math.round(s.position)}%`)
    .join(', ')
  return value.type === 'linear'
    ? `linear-gradient(${Math.round(value.angle)}deg, ${stops})`
    : `radial-gradient(circle, ${stops})`
}

export function GradientPicker({
  value,
  onChange,
  label = 'Gradient',
  className = '',
}: GradientPickerProps) {
  const [activeIndex, setActiveIndex] = React.useState(0)
  const trackRef = React.useRef<HTMLDivElement>(null)
  const css = gradientCss(value)

  const setStop = (index: number, patch: Partial<GradientStop>) => {
    const stops = value.stops.map((s, i) => (i === index ? { ...s, ...patch } : s))
    onChange({ ...value, stops })
  }

  const positionFromEvent = (clientX: number): number => {
    const rect = trackRef.current?.getBoundingClientRect()
    if (!rect || rect.width === 0) return 0
    const raw = (clientX - rect.left) / rect.width
    // Mirrored for RTL: the track is a gradient, which is drawn in the
    // document's direction, so a handle dragged toward the reading start
    // has to move toward 0% in both directions.
    const ratio =
      typeof document !== 'undefined' && document.documentElement.dir === 'rtl'
        ? 1 - raw
        : raw
    return Math.round(Math.max(0, Math.min(1, ratio)) * 100)
  }

  const addStop = () => {
    const sorted = [...value.stops].sort((a, b) => a.position - b.position)
    // Drop the new stop in the widest gap, which is where there is room for
    // it — appending at 100% puts it on top of the last one.
    let gap = 0
    let at = 50
    for (let i = 0; i < sorted.length - 1; i++) {
      const width = sorted[i + 1].position - sorted[i].position
      if (width > gap) {
        gap = width
        at = Math.round(sorted[i].position + width / 2)
      }
    }
    onChange({ ...value, stops: [...value.stops, { color: '#ffffff', position: at }] })
    setActiveIndex(value.stops.length)
  }

  const removeStop = (index: number) => {
    // Two stops is the minimum that is still a gradient.
    if (value.stops.length <= 2) return
    onChange({ ...value, stops: value.stops.filter((_, i) => i !== index) })
    setActiveIndex(0)
  }

  return (
    <div className={`flex w-full flex-col gap-3 ${className}`}>
      <div
        className="h-20 w-full rounded-xl border border-border"
        style={{ backgroundImage: css }}
        role="img"
        aria-label={`${label} preview`}
      />

      {/* -- the track -- */}
      <div
        ref={trackRef}
        className="relative h-6 w-full rounded-full border border-border"
        style={{ backgroundImage: gradientCss({ ...value, type: 'linear', angle: 90 }) }}
      >
        {value.stops.map((stop, i) => (
          <button
            key={i}
            type="button"
            role="slider"
            aria-label={`Stop ${i + 1}, ${stop.color}`}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.round(stop.position)}
            aria-valuetext={`${Math.round(stop.position)} percent`}
            onPointerDown={(e) => {
              setActiveIndex(i)
              // Capture, so the drag survives leaving the track — and is
              // released automatically if the pointer is lost.
              e.currentTarget.setPointerCapture(e.pointerId)
            }}
            onPointerMove={(e) => {
              if (!e.currentTarget.hasPointerCapture(e.pointerId)) return
              setStop(i, { position: positionFromEvent(e.clientX) })
            }}
            onKeyDown={(e) => {
              const step = e.shiftKey ? 10 : 1
              if (e.key === 'ArrowRight' || e.key === 'ArrowUp') {
                e.preventDefault()
                setStop(i, { position: Math.min(100, stop.position + step) })
              } else if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') {
                e.preventDefault()
                setStop(i, { position: Math.max(0, stop.position - step) })
              } else if (e.key === 'Backspace' || e.key === 'Delete') {
                e.preventDefault()
                removeStop(i)
              }
            }}
            style={{
              insetInlineStart: `${stop.position}%`,
              backgroundColor: stop.color,
            }}
            className={[
              'absolute top-1/2 h-5 w-5 -translate-y-1/2 rounded-full border-2 shadow',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
              'focus-visible:ring-offset-2 focus-visible:ring-offset-background',
              // The handle is centred on its position. `-translate-x-1/2`
              // is physical on purpose: it pairs with the physical half of
              // `insetInlineStart`, and the logical rewrite of this exact
              // idiom is the classic RTL off-centre bug.
              '-translate-x-1/2 rtl:translate-x-1/2',
              i === activeIndex ? 'border-foreground' : 'border-background',
            ].join(' ')}
          />
        ))}
      </div>

      {/* -- controls -- */}
      <div className="flex flex-wrap items-center gap-2">
        <input
          type="color"
          aria-label="Colour of the selected stop"
          value={value.stops[activeIndex]?.color ?? '#ffffff'}
          onChange={(e) => setStop(activeIndex, { color: e.target.value })}
          className="h-9 w-9 cursor-pointer rounded-lg border border-border bg-background p-1"
        />

        <label className="flex h-9 items-center gap-2 rounded-lg border border-border bg-background px-2.5 text-xs text-muted-foreground">
          Angle
          <input
            type="number"
            min={0}
            max={360}
            value={Math.round(value.angle)}
            disabled={value.type === 'radial'}
            onChange={(e) => onChange({ ...value, angle: Number(e.target.value) })}
            className="w-12 bg-transparent text-sm tabular-nums text-foreground outline-none disabled:opacity-40"
          />
        </label>

        <button
          type="button"
          onClick={() => onChange({ ...value, type: value.type === 'linear' ? 'radial' : 'linear' })}
          className="h-9 rounded-lg border border-border px-3 text-xs font-medium text-foreground transition-colors hover:bg-muted/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          {value.type === 'linear' ? 'Linear' : 'Radial'}
        </button>

        <button
          type="button"
          onClick={addStop}
          className="inline-flex h-9 items-center gap-1.5 rounded-lg border border-border px-3 text-xs font-medium text-foreground transition-colors hover:bg-muted/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <Plus className="h-3.5 w-3.5" aria-hidden /> Stop
        </button>

        <button
          type="button"
          onClick={() => removeStop(activeIndex)}
          disabled={value.stops.length <= 2}
          aria-label="Remove the selected stop"
          className="inline-flex h-9 w-9 items-center justify-center rounded-lg border border-border text-muted-foreground transition-colors hover:bg-muted/60 hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-40"
        >
          <Trash2 className="h-3.5 w-3.5" aria-hidden />
        </button>
      </div>

      <code className="block overflow-x-auto rounded-lg bg-muted/60 px-3 py-2 font-mono text-xs text-muted-foreground">
        {css}
      </code>
    </div>
  )
}

image-picker.source:
'use client'

/**
 * <ImagePicker> — a drop zone that is also a button that is also a preview.
 *
 * Three things make this different from a styled `<input type="file">`:
 *
 *   1. Drag and drop needs a counter, not a boolean. `dragleave` fires when
 *      the pointer crosses into a CHILD element, so the naive version
 *      flickers the highlight off every time the cursor passes over the
 *      icon in the middle of the zone. Counting enter/leave pairs is the
 *      only reliable fix.
 *   2. The file input must stay in the DOM and stay focusable. Replacing it
 *      with a div and a click handler loses keyboard access and the
 *      platform's own file dialog affordances, so the input is visually
 *      hidden and the label is the whole zone.
 *   3. The object URL has to be revoked. A picker used a dozen times in a
 *      session leaks a dozen blobs, each holding the whole image in memory
 *      until the tab closes.
 *
 * Validation is done here rather than left to `accept`, because `accept` is
 * a filter on the file dialog and nothing at all on a drop — a dragged
 * 40 MB video lands in your state and uploads.
 */

import * as React from 'react'
import { ImagePlus, Upload, X } from 'lucide-react'

export interface ImagePickerProps {
  value?: File | null
  onChange?: (file: File | null) => void
  /** Megabytes. Rejected before it reaches state. */
  maxSizeMb?: number
  accept?: string
  label?: string
  hint?: string
  className?: string
}

export function ImagePicker({
  value = null,
  onChange,
  maxSizeMb = 5,
  accept = 'image/png,image/jpeg,image/webp,image/avif',
  label = 'Upload an image',
  hint,
  className = '',
}: ImagePickerProps) {
  const [dragDepth, setDragDepth] = React.useState(0)
  const [error, setError] = React.useState<string | null>(null)
  const [preview, setPreview] = React.useState<string | null>(null)
  const inputRef = React.useRef<HTMLInputElement>(null)

  /*
   * The preview URL, created when the file changes and revoked when it
   * changes again or the component unmounts. Without the revoke, every
   * pick holds its image in memory for the life of the document.
   */
  React.useEffect(() => {
    if (!value) {
      setPreview(null)
      return
    }
    const url = URL.createObjectURL(value)
    setPreview(url)
    return () => URL.revokeObjectURL(url)
  }, [value])

  const accepted = accept.split(',').map((t) => t.trim())

  const take = (file: File | undefined) => {
    if (!file) return
    if (accepted.length > 0 && !accepted.includes(file.type)) {
      setError('That file type is not accepted.')
      return
    }
    if (file.size > maxSizeMb * 1024 * 1024) {
      setError(`That file is ${(file.size / 1024 / 1024).toFixed(1)} MB — the limit is ${maxSizeMb} MB.`)
      return
    }
    setError(null)
    onChange?.(file)
  }

  const clear = () => {
    setError(null)
    onChange?.(null)
    // The input keeps its value after a pick, so choosing the same file
    // twice in a row fires no change event without this.
    if (inputRef.current) inputRef.current.value = ''
  }

  const dragging = dragDepth > 0

  return (
    <div className={`flex flex-col gap-2 ${className}`}>
      <label
        onDragEnter={(e) => {
          e.preventDefault()
          // Counted, not a boolean: dragleave fires on every child
          // boundary, and a boolean flickers the highlight off as the
          // pointer crosses the icon.
          setDragDepth((d) => d + 1)
        }}
        onDragLeave={() => setDragDepth((d) => Math.max(0, d - 1))}
        onDragOver={(e) => e.preventDefault()}
        onDrop={(e) => {
          e.preventDefault()
          setDragDepth(0)
          take(e.dataTransfer.files[0])
        }}
        className={[
          'relative flex cursor-pointer flex-col items-center justify-center gap-2',
          'rounded-xl border-2 border-dashed px-6 py-8 text-center transition-colors',
          'focus-within:ring-2 focus-within:ring-ring',
          dragging
            ? 'border-primary bg-primary/5'
            : error
              ? 'border-destructive/50 bg-destructive/5'
              : 'border-border bg-muted/20 hover:bg-muted/40',
        ].join(' ')}
      >
        <input
          ref={inputRef}
          type="file"
          accept={accept}
          // `sr-only` rather than `hidden`: a hidden input is not focusable,
          // which takes the whole control away from a keyboard user.
          className="sr-only"
          onChange={(e) => take(e.target.files?.[0])}
        />

        {preview ? (
          <>
            {/* A plain <img>, not next/image: a primitive has to paste
                into a project that may not have it, and the source here is
                an object URL that next/image could not optimise anyway. */}
            <img
              src={preview}
              alt={value?.name ?? ''}
              className="max-h-40 rounded-lg object-contain"
            />
            <p className="max-w-full truncate text-xs text-muted-foreground">
              {value?.name} · {((value?.size ?? 0) / 1024).toFixed(0)} KB
            </p>
          </>
        ) : (
          <>
            <span className="inline-flex h-10 w-10 items-center justify-center rounded-full bg-background text-muted-foreground">
              {dragging ? (
                <Upload className="h-5 w-5" aria-hidden />
              ) : (
                <ImagePlus className="h-5 w-5" aria-hidden />
              )}
            </span>
            <span className="text-sm font-medium text-foreground">
              {dragging ? 'Drop it here' : label}
            </span>
            <span className="text-xs text-muted-foreground">
              {hint ?? `PNG, JPG, WebP or AVIF · up to ${maxSizeMb} MB`}
            </span>
          </>
        )}
      </label>

      {value ? (
        <button
          type="button"
          onClick={clear}
          className="inline-flex items-center gap-1.5 self-start text-xs font-medium text-muted-foreground transition-colors hover:text-destructive focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <X className="h-3.5 w-3.5" aria-hidden /> Remove
        </button>
      ) : null}

      {error ? (
        <p role="alert" className="text-xs font-medium text-destructive">
          {error}
        </p>
      ) : null}
    </div>
  )
}

credit-card.source:
'use client'

/**
 * <CreditCardInput> — the four fields, and the rules they actually need.
 *
 * Payment fields are the most-abandoned form on the internet and almost all
 * of the abandonment is friction this component removes:
 *
 *   grouping     digits are grouped as the card is typed — 4-4-4-4, but
 *                4-6-5 for Amex and 4-6-4 for Diners, because those cards
 *                are printed that way and a user checking their typing
 *                against the plastic needs the same shape
 *   detection    the brand is detected from the first digits, which sets
 *                the length, the CVC length (4 on Amex) and the mark shown
 *   luhn         the checksum catches a transposed digit before the network
 *                does, and a declined card is a lost sale
 *   expiry       `MM/YY` with the slash inserted, and a month above 12
 *                rejected as it is typed rather than on submit
 *   autofill     `autoComplete="cc-number"` and friends are what make the
 *                browser and the phone offer a saved card. Getting these
 *                tokens wrong is the single biggest cause of a payment form
 *                that "doesn't autofill"
 *
 * It never stores or transmits anything. In a real integration the fields
 * are the processor's iframes; this is the layout, the formatting and the
 * validation you still have to build around them.
 */

import * as React from 'react'

export type CardBrand = 'visa' | 'mastercard' | 'amex' | 'discover' | 'diners' | 'unknown'

interface BrandSpec {
  /** How the number is grouped as it is typed. */
  groups: number[]
  cvcLength: number
  test: RegExp
  label: string
}

const BRANDS: Record<Exclude<CardBrand, 'unknown'>, BrandSpec> = {
  visa: { groups: [4, 4, 4, 4], cvcLength: 3, test: /^4/, label: 'Visa' },
  mastercard: { groups: [4, 4, 4, 4], cvcLength: 3, test: /^(5[1-5]|2[2-7])/, label: 'Mastercard' },
  amex: { groups: [4, 6, 5], cvcLength: 4, test: /^3[47]/, label: 'American Express' },
  discover: { groups: [4, 4, 4, 4], cvcLength: 3, test: /^6(?:011|5)/, label: 'Discover' },
  diners: { groups: [4, 6, 4], cvcLength: 3, test: /^3(?:0[0-5]|[68])/, label: 'Diners Club' },
}

const UNKNOWN: BrandSpec = { groups: [4, 4, 4, 4], cvcLength: 3, test: /.^/, label: 'Card' }

export function detectBrand(digits: string): CardBrand {
  for (const [brand, spec] of Object.entries(BRANDS)) {
    if (spec.test.test(digits)) return brand as CardBrand
  }
  return 'unknown'
}

function specFor(brand: CardBrand): BrandSpec {
  return brand === 'unknown' ? UNKNOWN : BRANDS[brand]
}

/** Group digits by the brand's own printed layout. */
export function formatCardNumber(digits: string, brand: CardBrand): string {
  const { groups } = specFor(brand)
  const out: string[] = []
  let i = 0
  for (const size of groups) {
    if (i >= digits.length) break
    out.push(digits.slice(i, i + size))
    i += size
  }
  // Anything past the brand's expected length still shows, rather than
  // being silently swallowed — a user who typed 17 digits needs to see 17.
  if (i < digits.length) out.push(digits.slice(i))
  return out.join(' ')
}

/**
 * The Luhn checksum.
 *
 * Catches a single transposed or mistyped digit, which is the overwhelming
 * majority of real typos. It says nothing about whether the card exists or
 * has funds — only the processor knows that — so it is used to show an
 * inline error, never to claim the card is good.
 */
export function luhnValid(digits: string): boolean {
  if (digits.length < 12) return false
  let sum = 0
  let double = false
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48
    if (double) {
      d *= 2
      if (d > 9) d -= 9
    }
    sum += d
    double = !double
  }
  return sum % 10 === 0
}

export interface CreditCardValue {
  number: string
  expiry: string
  cvc: string
  name: string
}

export interface CreditCardInputProps {
  value: CreditCardValue
  onChange: (value: CreditCardValue) => void
  /** Show the drawn card above the fields. */
  showPreview?: boolean
  className?: string
}

export function CreditCardInput({
  value,
  onChange,
  showPreview = true,
  className = '',
}: CreditCardInputProps) {
  const digits = value.number.replace(/\D/g, '')
  const brand = detectBrand(digits)
  const spec = specFor(brand)
  const maxDigits = spec.groups.reduce((a, b) => a + b, 0)

  const [touched, setTouched] = React.useState<Record<string, boolean>>({})
  const numberError =
    touched.number && digits.length >= 12 && !luhnValid(digits)
      ? 'Check the card number — one of the digits is wrong.'
      : null

  const set = (patch: Partial<CreditCardValue>) => onChange({ ...value, ...patch })

  return (
    <div className={`flex flex-col gap-4 ${className}`}>
      {showPreview ? <CardFace digits={digits} brand={brand} value={value} /> : null}

      <label className="flex flex-col gap-1.5">
        <span className="text-sm font-medium text-foreground">Card number</span>
        <div
          className={[
            'flex h-10 items-center rounded-lg border bg-background px-3',
            'focus-within:ring-2 focus-within:ring-ring',
            numberError ? 'border-destructive' : 'border-border',
          ].join(' ')}
        >
          <input
            inputMode="numeric"
            // These tokens are what make the browser and the phone offer a
            // saved card. Misspelling one is the usual cause of a payment
            // form that "doesn't autofill".
            autoComplete="cc-number"
            placeholder="4242 4242 4242 4242"
            value={formatCardNumber(digits, brand)}
            aria-invalid={numberError ? true : undefined}
            aria-describedby={numberError ? 'cc-number-error' : undefined}
            onBlur={() => setTouched((t) => ({ ...t, number: true }))}
            onChange={(e) =>
              set({ number: e.target.value.replace(/\D/g, '').slice(0, maxDigits) })
            }
            className="w-full bg-transparent font-mono text-sm tabular-nums text-foreground outline-none placeholder:text-muted-foreground"
          />
          <BrandMark brand={brand} />
        </div>
        {numberError ? (
          <span id="cc-number-error" role="alert" className="text-xs font-medium text-destructive">
            {numberError}
          </span>
        ) : null}
      </label>

      <div className="grid grid-cols-2 gap-3">
        <label className="flex flex-col gap-1.5">
          <span className="text-sm font-medium text-foreground">Expiry</span>
          <input
            inputMode="numeric"
            autoComplete="cc-exp"
            placeholder="MM/YY"
            value={value.expiry}
            onChange={(e) => set({ expiry: formatExpiry(e.target.value) })}
            className="h-10 rounded-lg border border-border bg-background px-3 font-mono text-sm tabular-nums text-foreground outline-none focus:ring-2 focus:ring-ring placeholder:text-muted-foreground"
          />
        </label>

        <label className="flex flex-col gap-1.5">
          <span className="text-sm font-medium text-foreground">
            CVC
            {/* Amex prints four digits on the front rather than three on
                the back, so the hint is per-brand and not decoration. */}
            <span className="ms-1 font-normal text-muted-foreground">
              ({spec.cvcLength} digits)
            </span>
          </span>
          <input
            inputMode="numeric"
            autoComplete="cc-csc"
            placeholder={'•'.repeat(spec.cvcLength)}
            value={value.cvc}
            onChange={(e) => set({ cvc: e.target.value.replace(/\D/g, '').slice(0, spec.cvcLength) })}
            className="h-10 rounded-lg border border-border bg-background px-3 font-mono text-sm tabular-nums text-foreground outline-none focus:ring-2 focus:ring-ring placeholder:text-muted-foreground"
          />
        </label>
      </div>

      <label className="flex flex-col gap-1.5">
        <span className="text-sm font-medium text-foreground">Name on card</span>
        <input
          autoComplete="cc-name"
          placeholder="A. Lovelace"
          value={value.name}
          onChange={(e) => set({ name: e.target.value })}
          className="h-10 rounded-lg border border-border bg-background px-3 text-sm text-foreground outline-none focus:ring-2 focus:ring-ring placeholder:text-muted-foreground"
        />
      </label>
    </div>
  )
}

/** `1225` → `12/25`, rejecting a month above 12 as it is typed. */
export function formatExpiry(raw: string): string {
  const digits = raw.replace(/\D/g, '').slice(0, 4)
  if (digits.length === 0) return ''
  // A leading digit above 1 can only be a single-digit month, so "9"
  // becomes "09/" — which is what the user meant and saves a keystroke.
  if (digits.length === 1) return Number(digits) > 1 ? `0${digits}/` : digits
  const month = Math.min(12, Math.max(1, Number(digits.slice(0, 2))))
  const mm = String(month).padStart(2, '0')
  return digits.length <= 2 ? `${mm}/` : `${mm}/${digits.slice(2)}`
}

/** The drawn card. Decorative — every value on it is also in a labelled field. */
function CardFace({
  digits,
  brand,
  value,
}: {
  digits: string
  brand: CardBrand
  value: CreditCardValue
}) {
  const groups = formatCardNumber(digits.padEnd(16, '•'), brand)
  return (
    <div
      aria-hidden
      className="relative flex aspect-[1.586/1] w-full max-w-xs flex-col justify-between overflow-hidden rounded-2xl bg-gradient-to-br from-slate-800 via-slate-900 to-black p-5 text-white shadow-lg"
    >
      <div className="flex items-start justify-between">
        <span className="h-7 w-10 rounded bg-gradient-to-br from-amber-200 to-amber-400" />
        <span className="text-xs font-semibold uppercase tracking-wide opacity-80">
          {specFor(brand).label}
        </span>
      </div>
      <p className="font-mono text-base tabular-nums tracking-[0.12em]">{groups}</p>
      <div className="flex items-end justify-between text-[10px] uppercase tracking-wide opacity-80">
        <span className="truncate">{value.name || 'Your name'}</span>
        <span className="font-mono tabular-nums">{value.expiry || 'MM/YY'}</span>
      </div>
    </div>
  )
}

/**
 * The brand mark, as a wordmark rather than a logo.
 *
 * Card network logos are trademarks with usage rules, and shipping copies
 * of them in a component catalog is not something the buyer would be
 * licensed to do. A typeset name is accurate, legal, and themes correctly.
 */
function BrandMark({ brand }: { brand: CardBrand }) {
  if (brand === 'unknown') return null
  return (
    <span className="ms-2 shrink-0 rounded border border-border px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">
      {brand === 'amex' ? 'Amex' : specFor(brand).label}
    </span>
  )
}

qr-code.source:
/**
 * <QrCode> — a real, scannable QR code, with no dependency.
 *
 * Every other catalog's QR component wraps `qrcode.react` or `qrcode`, and
 * the honest version of their card would say "installs a package". This one
 * encodes the symbol itself: bit stream, Reed-Solomon error correction over
 * GF(256), block interleaving, all eight data masks scored by the standard
 * penalty rules, and BCH-coded format and version information.
 *
 * That is about 200 lines, which is a lot for a primitive, and it is the
 * whole point of the primitive. A QR component that cannot produce a
 * scannable symbol is a picture of a QR code, and this tier's claim is that
 * what you paste has no dependencies and no runtime you did not read.
 *
 * SCOPE, stated rather than discovered:
 *   - byte mode only (UTF-8), which covers URLs, vCards and plain text
 *   - error correction level M (~15% recoverable), the usual default
 *   - versions 1 to 10, so up to 213 bytes — a long URL with room to spare
 * A longer string throws rather than silently truncating, because a QR code
 * that encodes half a URL scans perfectly and goes to the wrong place.
 *
 * Rendered as one `<path>` of SVG rectangles rather than a grid of
 * elements: a version-10 symbol is 57×57, and 3,249 `<rect>` nodes is a
 * real layout cost for something that is one shape.
 *
 * It does not theme. See the note on `color` — a dark-mode QR code with
 * light modules is out of spec, and the phones it still works on are the
 * ones that try inverting.
 */

import * as React from 'react'

/* ------------------------------------------------------------------ *
 *  GF(256) — the field Reed-Solomon works in
 * ------------------------------------------------------------------ */

const EXP = new Uint8Array(512)
const LOG = new Uint8Array(256)

{
  let x = 1
  for (let i = 0; i < 255; i++) {
    EXP[i] = x
    LOG[x] = i
    // The QR standard's primitive polynomial, x^8 + x^4 + x^3 + x^2 + 1.
    x <<= 1
    if (x & 0x100) x ^= 0x11d
  }
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255]
}

function mul(a: number, b: number): number {
  return a === 0 || b === 0 ? 0 : EXP[LOG[a] + LOG[b]]
}

/** The generator polynomial for `degree` error-correction codewords. */
function rsGenerator(degree: number): number[] {
  let poly = [1]
  for (let i = 0; i < degree; i++) {
    const next = new Array<number>(poly.length + 1).fill(0)
    for (let j = 0; j < poly.length; j++) {
      next[j] ^= poly[j]
      next[j + 1] ^= mul(poly[j], EXP[i])
    }
    poly = next
  }
  return poly
}

/** The `ecLen` error-correction codewords for one block of data. */
export function rsEncode(data: number[], ecLen: number): number[] {
  const gen = rsGenerator(ecLen)
  const res = new Array<number>(ecLen).fill(0)
  for (const byte of data) {
    const factor = byte ^ res[0]
    res.shift()
    res.push(0)
    for (let i = 0; i < ecLen; i++) res[i] ^= mul(gen[i + 1], factor)
  }
  return res
}

/* ------------------------------------------------------------------ *
 *  The version tables, for error-correction level M
 * ------------------------------------------------------------------ */

interface VersionSpec {
  /** Byte-mode capacity in characters. */
  capacity: number
  /** Error-correction codewords per block. */
  ecPerBlock: number
  /** [blockCount, dataCodewordsPerBlock] for each group. */
  groups: [number, number][]
  /** Centres of the alignment patterns, as coordinates on both axes. */
  alignment: number[]
  /** Bits of padding after the interleaved stream. */
  remainderBits: number
}

const VERSIONS: Record<number, VersionSpec> = {
  1: { capacity: 14, ecPerBlock: 10, groups: [[1, 16]], alignment: [], remainderBits: 0 },
  2: { capacity: 26, ecPerBlock: 16, groups: [[1, 28]], alignment: [6, 18], remainderBits: 7 },
  3: { capacity: 42, ecPerBlock: 26, groups: [[1, 44]], alignment: [6, 22], remainderBits: 7 },
  4: { capacity: 62, ecPerBlock: 18, groups: [[2, 32]], alignment: [6, 26], remainderBits: 7 },
  5: { capacity: 84, ecPerBlock: 24, groups: [[2, 43]], alignment: [6, 30], remainderBits: 7 },
  6: { capacity: 106, ecPerBlock: 16, groups: [[4, 27]], alignment: [6, 34], remainderBits: 7 },
  7: { capacity: 122, ecPerBlock: 18, groups: [[4, 31]], alignment: [6, 22, 38], remainderBits: 0 },
  8: { capacity: 152, ecPerBlock: 22, groups: [[2, 38], [2, 39]], alignment: [6, 24, 42], remainderBits: 0 },
  9: { capacity: 180, ecPerBlock: 22, groups: [[3, 36], [2, 37]], alignment: [6, 26, 46], remainderBits: 0 },
  10: { capacity: 213, ecPerBlock: 26, groups: [[4, 43], [1, 44]], alignment: [6, 28, 50], remainderBits: 0 },
}

/* ------------------------------------------------------------------ *
 *  Encoding
 * ------------------------------------------------------------------ */

class BitBuffer {
  bits: number[] = []
  push(value: number, length: number) {
    for (let i = length - 1; i >= 0; i--) this.bits.push((value >>> i) & 1)
  }
  get length() {
    return this.bits.length
  }
  toBytes(): number[] {
    const out: number[] = []
    for (let i = 0; i < this.bits.length; i += 8) {
      let byte = 0
      for (let j = 0; j < 8; j++) byte = (byte << 1) | (this.bits[i + j] ?? 0)
      out.push(byte)
    }
    return out
  }
}

/** The interleaved data + error-correction codewords for a value. */
export function encodeToCodewords(value: string): { version: number; codewords: number[] } {
  const bytes = Array.from(new TextEncoder().encode(value))

  const version = Number(
    Object.keys(VERSIONS).find((v) => bytes.length <= VERSIONS[Number(v)].capacity),
  )
  if (!version) {
    throw new Error(
      `QrCode: ${bytes.length} bytes is more than version 10 holds at error-correction level M (213).`,
    )
  }

  const spec = VERSIONS[version]
  const totalData = spec.groups.reduce((sum, [count, size]) => sum + count * size, 0)

  const buffer = new BitBuffer()
  buffer.push(0b0100, 4) // byte mode
  // The character-count indicator is 8 bits below version 10 and 16 from
  // version 10 up. Getting this boundary wrong produces a symbol that
  // scans as garbage rather than failing.
  buffer.push(bytes.length, version < 10 ? 8 : 16)
  for (const byte of bytes) buffer.push(byte, 8)

  // Terminator: up to four zero bits, then pad to a byte boundary.
  const capacityBits = totalData * 8
  buffer.push(0, Math.min(4, capacityBits - buffer.length))
  while (buffer.length % 8 !== 0) buffer.push(0, 1)

  const data = buffer.toBytes()
  // The two standard pad codewords, alternating, until the block is full.
  const PADS = [0xec, 0x11]
  for (let i = 0; data.length < totalData; i++) data.push(PADS[i % 2])

  /* -- Split into blocks, compute EC, interleave -- */

  const dataBlocks: number[][] = []
  const ecBlocks: number[][] = []
  let offset = 0
  for (const [count, size] of spec.groups) {
    for (let i = 0; i < count; i++) {
      const block = data.slice(offset, offset + size)
      offset += size
      dataBlocks.push(block)
      ecBlocks.push(rsEncode(block, spec.ecPerBlock))
    }
  }

  /*
   * Interleaving is column-wise across blocks: the first codeword of every
   * block, then the second of every block, and so on. It is what makes a
   * scratch across the symbol damage a few codewords in every block rather
   * than destroying one block completely — which is more than its error
   * correction could repair.
   */
  const codewords: number[] = []
  const maxData = Math.max(...dataBlocks.map((b) => b.length))
  for (let i = 0; i < maxData; i++) {
    for (const block of dataBlocks) if (i < block.length) codewords.push(block[i])
  }
  for (let i = 0; i < spec.ecPerBlock; i++) {
    for (const block of ecBlocks) codewords.push(block[i])
  }

  return { version, codewords }
}

/* ------------------------------------------------------------------ *
 *  The matrix
 * ------------------------------------------------------------------ */

type Grid = (0 | 1 | null)[][]

const MASKS: ((r: number, c: number) => boolean)[] = [
  (r, c) => (r + c) % 2 === 0,
  (r) => r % 2 === 0,
  (_, c) => c % 3 === 0,
  (r, c) => (r + c) % 3 === 0,
  (r, c) => (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0,
  (r, c) => ((r * c) % 2) + ((r * c) % 3) === 0,
  (r, c) => (((r * c) % 2) + ((r * c) % 3)) % 2 === 0,
  (r, c) => (((r + c) % 2) + ((r * c) % 3)) % 2 === 0,
]

/** BCH(15,5) format information, XOR-masked as the standard requires. */
function formatBits(mask: number): number {
  // 0b00 is error-correction level M.
  let value = (0b00 << 3) | mask
  let rem = value
  for (let i = 0; i < 10; i++) rem = (rem << 1) ^ ((rem >>> 9) * 0x537)
  value = ((value << 10) | rem) ^ 0x5412
  return value
}

/** BCH(18,6) version information. Only present from version 7. */
function versionBits(version: number): number {
  let rem = version
  for (let i = 0; i < 12; i++) rem = (rem << 1) ^ ((rem >>> 11) * 0x1f25)
  return (version << 12) | rem
}

/** The finished module grid for a value: `true` is a dark module. */
export function buildMatrix(value: string): boolean[][] {
  const { version, codewords } = encodeToCodewords(value)
  const spec = VERSIONS[version]
  const size = version * 4 + 17

  const grid: Grid = Array.from({ length: size }, () => new Array(size).fill(null))
  const reserved: boolean[][] = Array.from({ length: size }, () => new Array(size).fill(false))

  const set = (r: number, c: number, dark: boolean) => {
    grid[r][c] = dark ? 1 : 0
    reserved[r][c] = true
  }

  /* -- Finder patterns and their separators -- */
  const finder = (top: number, left: number) => {
    for (let r = -1; r <= 7; r++) {
      for (let c = -1; c <= 7; c++) {
        const rr = top + r
        const cc = left + c
        if (rr < 0 || rr >= size || cc < 0 || cc >= size) continue
        const inRing = r >= 0 && r <= 6 && c >= 0 && c <= 6
        const isDark =
          inRing &&
          ((r === 0 || r === 6 || c === 0 || c === 6) ||
            (r >= 2 && r <= 4 && c >= 2 && c <= 4))
        set(rr, cc, isDark)
      }
    }
  }
  finder(0, 0)
  finder(0, size - 7)
  finder(size - 7, 0)

  /* -- Timing patterns -- */
  for (let i = 8; i < size - 8; i++) {
    set(6, i, i % 2 === 0)
    set(i, 6, i % 2 === 0)
  }

  /* -- Alignment patterns, skipping the three that collide with finders -- */
  for (const r of spec.alignment) {
    for (const c of spec.alignment) {
      const nearFinder =
        (r <= 8 && c <= 8) || (r <= 8 && c >= size - 9) || (r >= size - 9 && c <= 8)
      if (nearFinder) continue
      for (let dr = -2; dr <= 2; dr++) {
        for (let dc = -2; dc <= 2; dc++) {
          set(r + dr, c + dc, Math.max(Math.abs(dr), Math.abs(dc)) !== 1)
        }
      }
    }
  }

  /* -- Reserve the format and version areas before laying data -- */
  for (let i = 0; i < 9; i++) {
    if (grid[8][i] === null) reserved[8][i] = true
    if (grid[i][8] === null) reserved[i][8] = true
  }
  for (let i = 0; i < 8; i++) {
    reserved[8][size - 1 - i] = true
    reserved[size - 1 - i][8] = true
  }
  // The always-dark module, which is part of the format area.
  set(size - 8, 8, true)

  if (version >= 7) {
    for (let i = 0; i < 18; i++) {
      const r = Math.floor(i / 3)
      const c = i % 3
      reserved[size - 11 + c][r] = true
      reserved[r][size - 11 + c] = true
    }
  }

  /* -- Data, in the standard two-column zigzag from the bottom right -- */
  const bits: number[] = []
  for (const codeword of codewords) {
    for (let i = 7; i >= 0; i--) bits.push((codeword >>> i) & 1)
  }
  for (let i = 0; i < spec.remainderBits; i++) bits.push(0)

  let bitIndex = 0
  let upward = true
  for (let col = size - 1; col > 0; col -= 2) {
    // Column 6 is the vertical timing pattern; the data columns step over
    // it rather than through it.
    if (col === 6) col--
    for (let i = 0; i < size; i++) {
      const row = upward ? size - 1 - i : i
      for (const c of [col, col - 1]) {
        if (reserved[row][c]) continue
        grid[row][c] = ((bits[bitIndex] ?? 0) as 0 | 1) || 0
        bitIndex++
      }
    }
    upward = !upward
  }

  /* -- Try all eight masks, keep the least penalised -- */
  let best: boolean[][] | null = null
  let bestScore = Infinity
  let bestMask = 0

  for (let mask = 0; mask < 8; mask++) {
    const candidate = grid.map((row, r) =>
      row.map((cell, c) => {
        const dark = cell === 1
        // Function modules are never masked.
        return reserved[r][c] ? dark : dark !== MASKS[mask](r, c)
      }),
    )
    applyFormat(candidate, reserved, mask, version, size)
    const score = penalty(candidate)
    if (score < bestScore) {
      bestScore = score
      best = candidate
      bestMask = mask
    }
  }
  void bestMask

  return best!
}

/** Write the format (and, from version 7, version) information. */
function applyFormat(
  grid: boolean[][],
  reserved: boolean[][],
  mask: number,
  version: number,
  size: number,
) {
  void reserved
  const format = formatBits(mask)
  for (let i = 0; i < 15; i++) {
    const bit = ((format >>> i) & 1) === 1

    // Copy one: around the top-left finder, stepping over the timing row
    // and column.
    if (i < 6) grid[i][8] = bit
    else if (i < 8) grid[i + 1][8] = bit
    else if (i === 8) grid[8][7] = bit
    else grid[8][14 - i] = bit

    // Copy two: split between the other two finders, so a symbol with one
    // corner destroyed is still readable.
    if (i < 8) grid[8][size - 1 - i] = bit
    else grid[size - 15 + i][8] = bit
  }

  if (version >= 7) {
    const bits = versionBits(version)
    for (let i = 0; i < 18; i++) {
      const bit = ((bits >>> i) & 1) === 1
      const r = Math.floor(i / 3)
      const c = i % 3
      grid[size - 11 + c][r] = bit
      grid[r][size - 11 + c] = bit
    }
  }
}

/**
 * The standard's four penalty rules.
 *
 * The mask is chosen to minimise this, and the rules exist because some
 * patterns are hard for a scanner: long runs confuse the edge detector,
 * 2×2 blocks look like alignment marks, the 1:1:3:1:1 sequence is the
 * finder pattern itself, and a symbol that is mostly one colour has no
 * contrast to threshold against.
 */
function penalty(grid: boolean[][]): number {
  const size = grid.length
  let score = 0

  // Rule 1 — runs of five or more.
  for (let i = 0; i < size; i++) {
    for (const line of [grid[i], grid.map((row) => row[i])]) {
      let run = 1
      for (let j = 1; j < size; j++) {
        if (line[j] === line[j - 1]) {
          run++
        } else {
          if (run >= 5) score += 3 + (run - 5)
          run = 1
        }
      }
      if (run >= 5) score += 3 + (run - 5)
    }
  }

  // Rule 2 — 2x2 blocks of one colour.
  for (let r = 0; r < size - 1; r++) {
    for (let c = 0; c < size - 1; c++) {
      const v = grid[r][c]
      if (v === grid[r][c + 1] && v === grid[r + 1][c] && v === grid[r + 1][c + 1]) score += 3
    }
  }

  // Rule 3 — the finder-like sequence, in either orientation.
  const PATTERN = [true, false, true, true, true, false, true]
  const matches = (line: boolean[], at: number) => {
    for (let k = 0; k < 7; k++) if (line[at + k] !== PATTERN[k]) return false
    const before = line.slice(Math.max(0, at - 4), at)
    const after = line.slice(at + 7, at + 11)
    const quiet = (part: boolean[]) => part.length === 4 && part.every((v) => !v)
    return quiet(before) || quiet(after)
  }
  for (let i = 0; i < size; i++) {
    const row = grid[i]
    const col = grid.map((r) => r[i])
    for (let j = 0; j + 7 <= size; j++) {
      if (matches(row, j)) score += 40
      if (matches(col, j)) score += 40
    }
  }

  // Rule 4 — how far the dark proportion is from half.
  const dark = grid.flat().filter(Boolean).length
  const percent = (dark * 100) / (size * size)
  score += Math.floor(Math.abs(percent - 50) / 5) * 10

  return score
}

/* ------------------------------------------------------------------ *
 *  The component
 * ------------------------------------------------------------------ */

export interface QrCodeProps {
  /** What the code encodes — a URL, a vCard, plain text. */
  value: string
  /** Rendered size in pixels. The symbol scales; the modules stay crisp. */
  size?: number
  /** Quiet zone in modules. Four is the standard minimum; below it, scanners fail. */
  quietZone?: number
  /**
   * Module and background colours.
   *
   * They default to black on white and do NOT follow the theme, which is
   * deliberate. A QR symbol is a machine-readable target, not chrome: the
   * standard specifies dark modules on a light background, and an inverted
   * one is read by phone cameras that try both polarities and refused by
   * plenty of scanners that do not. A code that themes itself is a code
   * that stops working for some of the people pointing a device at it.
   *
   * Override them if you know the scanner — but keep the dark/light
   * relationship and keep the contrast high.
   */
  color?: string
  background?: string
  /** What the code is, for a screen reader. The value itself if omitted. */
  label?: string
  className?: string
}

export function QrCode({
  value,
  size = 160,
  quietZone = 4,
  color = '#000000',
  background = '#ffffff',
  label,
  className = '',
}: QrCodeProps) {
  const matrix = React.useMemo(() => buildMatrix(value), [value])
  const modules = matrix.length
  const total = modules + quietZone * 2

  /*
   * One path for the whole symbol. A version-10 code is 57x57 — 3,249
   * elements if each module is its own <rect>, which is a real cost for
   * something that is one shape and never animates.
   */
  const path = React.useMemo(() => {
    const parts: string[] = []
    for (let r = 0; r < modules; r++) {
      for (let c = 0; c < modules; c++) {
        if (matrix[r][c]) parts.push(`M${c + quietZone} ${r + quietZone}h1v1h-1z`)
      }
    }
    return parts.join('')
  }, [matrix, modules, quietZone])

  return (
    <svg
      viewBox={`0 0 ${total} ${total}`}
      width={size}
      height={size}
      role="img"
      aria-label={label ?? `QR code for ${value}`}
      // `crispEdges` so module boundaries land on pixels at any size.
      shapeRendering="crispEdges"
      className={className}
    >
      <rect width={total} height={total} fill={background} />
      <path d={path} fill={color} />
    </svg>
  )
}

video-player.source:
'use client'

/**
 * <VideoPlayer> — custom controls over a real `<video>`.
 *
 * The default controls are fine and every brand replaces them, so the
 * question is only whether the replacement keeps what the native ones gave
 * you for free. Usually it does not. What is kept here:
 *
 *   keyboard   Space and K toggle, arrows seek five seconds, J and L seek
 *              ten, M mutes, F is fullscreen, 0–9 jump to a tenth. These
 *              are YouTube's bindings, which is what people already know.
 *   scrubbing  the progress bar is a real `<input type="range">`, so it
 *              works with a keyboard, a screen reader and a touch drag
 *              without a line of pointer-capture code. Styling one is
 *              fiddlier than building a div; being able to seek without a
 *              mouse is worth it.
 *   buffered   the loaded range is painted behind the played range. Its
 *              absence is why a custom player feels broken on a slow
 *              connection — nothing tells you it is loading rather than
 *              stuck.
 *   time       `tabular-nums`, so the countdown does not jitter the layout
 *              every second.
 *
 * The transport icons are NOT mirrored in right-to-left documents. A
 * timeline runs the same way everywhere, and every RTL platform ships play
 * pointing the same direction — a mirrored play button reads as rewind.
 */

import * as React from 'react'
import { Maximize, Pause, Play, Volume2, VolumeX } from 'lucide-react'

export interface VideoPlayerProps {
  src?: string
  poster?: string
  /** Describes the video for anyone who cannot see it. */
  label: string
  className?: string
}

function timecode(seconds: number): string {
  if (!Number.isFinite(seconds)) return '0:00'
  const m = Math.floor(seconds / 60)
  const s = Math.floor(seconds % 60)
  return `${m}:${String(s).padStart(2, '0')}`
}

export function VideoPlayer({ src, poster, label, className = '' }: VideoPlayerProps) {
  const videoRef = React.useRef<HTMLVideoElement>(null)
  const rootRef = React.useRef<HTMLDivElement>(null)

  const [playing, setPlaying] = React.useState(false)
  const [muted, setMuted] = React.useState(false)
  const [time, setTime] = React.useState(0)
  const [duration, setDuration] = React.useState(0)
  const [buffered, setBuffered] = React.useState(0)

  const seek = (to: number) => {
    const video = videoRef.current
    if (!video) return
    video.currentTime = Math.max(0, Math.min(duration || 0, to))
  }

  const toggle = () => {
    const video = videoRef.current
    if (!video) return
    if (video.paused) void video.play()
    else video.pause()
  }

  const onKeyDown = (e: React.KeyboardEvent) => {
    // Not when the range input has focus: it has its own arrow handling,
    // and doubling it makes the scrubber jump ten seconds a press.
    if ((e.target as HTMLElement).tagName === 'INPUT') return

    const keys: Record<string, () => void> = {
      ' ': toggle,
      k: toggle,
      ArrowRight: () => seek(time + 5),
      ArrowLeft: () => seek(time - 5),
      l: () => seek(time + 10),
      j: () => seek(time - 10),
      m: () => setMuted((v) => !v),
      f: () => void rootRef.current?.requestFullscreen?.(),
    }
    const handler = keys[e.key] ?? keys[e.key.toLowerCase()]
    if (handler) {
      e.preventDefault()
      handler()
      return
    }
    if (/^[0-9]$/.test(e.key) && duration) {
      e.preventDefault()
      seek((Number(e.key) / 10) * duration)
    }
  }

  React.useEffect(() => {
    const video = videoRef.current
    if (video) video.muted = muted
  }, [muted])

  const progress = duration > 0 ? (time / duration) * 100 : 0
  const loaded = duration > 0 ? (buffered / duration) * 100 : 0

  return (
    <div
      ref={rootRef}
      // The player is one keyboard target; the controls inside it are their
      // own stops. `tabIndex={0}` is what makes the shortcuts reachable
      // without first tabbing to a button.
      tabIndex={0}
      role="region"
      aria-label={label}
      onKeyDown={onKeyDown}
      className={`group relative overflow-hidden rounded-xl bg-black focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring ${className}`}
    >
      <video
        ref={videoRef}
        src={src}
        poster={poster}
        playsInline
        onClick={toggle}
        onPlay={() => setPlaying(true)}
        onPause={() => setPlaying(false)}
        onTimeUpdate={(e) => setTime(e.currentTarget.currentTime)}
        onDurationChange={(e) => setDuration(e.currentTarget.duration)}
        onProgress={(e) => {
          const ranges = e.currentTarget.buffered
          // The last range that has started, which is what is ahead of the
          // playhead — not range 0, which is wrong after any seek.
          setBuffered(ranges.length > 0 ? ranges.end(ranges.length - 1) : 0)
        }}
        className="aspect-video w-full bg-black"
      />

      {/* A large, centred play affordance while paused — the target people
          actually aim at, rather than the 32px button in the bar. */}
      {!playing ? (
        <button
          type="button"
          onClick={toggle}
          aria-label="Play"
          className="absolute inset-0 flex items-center justify-center focus-visible:outline-none"
        >
          <span className="flex h-16 w-16 items-center justify-center rounded-full bg-black/60 text-white backdrop-blur transition-transform hover:scale-105 motion-reduce:transform-none">
            <Play className="h-7 w-7 translate-x-0.5" fill="currentColor" aria-hidden />
          </span>
        </button>
      ) : null}

      {/* -- the control bar -- */}
      <div className="absolute inset-x-0 bottom-0 flex flex-col gap-1 bg-gradient-to-t from-black/80 to-transparent p-3 pt-8">
        <div className="relative flex h-4 items-center">
          {/* The buffered range, behind the scrubber. Its absence is why a
              custom player feels broken on a slow connection. */}
          <span
            aria-hidden
            className="pointer-events-none absolute inset-x-0 top-1/2 h-1 -translate-y-1/2 rounded-full bg-white/20"
          >
            <span
              className="absolute inset-y-0 start-0 rounded-full bg-white/30"
              style={{ width: `${loaded}%` }}
            />
            <span
              className="absolute inset-y-0 start-0 rounded-full bg-white"
              style={{ width: `${progress}%` }}
            />
          </span>

          <input
            type="range"
            min={0}
            max={duration || 0}
            step={0.1}
            value={time}
            onChange={(e) => seek(Number(e.target.value))}
            aria-label="Seek"
            aria-valuetext={`${timecode(time)} of ${timecode(duration)}`}
            // Transparent, over the painted track: a real range input keeps
            // keyboard, screen-reader and touch behaviour that a div cannot.
            className="relative z-10 h-4 w-full cursor-pointer appearance-none bg-transparent accent-white [&::-webkit-slider-thumb]:h-3 [&::-webkit-slider-thumb]:w-3 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:bg-white"
          />
        </div>

        <div className="flex items-center gap-2 text-white">
          <button
            type="button"
            onClick={toggle}
            aria-label={playing ? 'Pause' : 'Play'}
            className="rounded p-1 transition-colors hover:bg-white/15 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white"
          >
            {playing ? (
              <Pause className="h-4 w-4" fill="currentColor" aria-hidden />
            ) : (
              <Play className="h-4 w-4" fill="currentColor" aria-hidden />
            )}
          </button>

          <button
            type="button"
            onClick={() => setMuted((v) => !v)}
            aria-label={muted ? 'Unmute' : 'Mute'}
            aria-pressed={muted}
            className="rounded p-1 transition-colors hover:bg-white/15 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white"
          >
            {muted ? <VolumeX className="h-4 w-4" aria-hidden /> : <Volume2 className="h-4 w-4" aria-hidden />}
          </button>

          <span className="text-xs tabular-nums opacity-90">
            {timecode(time)} / {timecode(duration)}
          </span>

          <button
            type="button"
            onClick={() => void rootRef.current?.requestFullscreen?.()}
            aria-label="Full screen"
            className="ms-auto rounded p-1 transition-colors hover:bg-white/15 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white"
          >
            <Maximize className="h-4 w-4" aria-hidden />
          </button>
        </div>
      </div>
    </div>
  )
}

calendar.source:
'use client'

/**
 * <Calendar> — a month grid you can drive entirely from the keyboard.
 *
 * Almost every hand-built calendar is a `<div>` of `<button>`s, which makes
 * it 42 tab stops and tells a screen reader nothing about where a date sits.
 * This is a real `role="grid"`: rows are weeks, cells are days, and the grid
 * is ONE tab stop with a roving tabindex inside it, so a keyboard user tabs
 * in, walks the month with the arrows, and tabs out. That is the WAI-ARIA
 * grid pattern and it is the whole reason this file is longer than a loop
 * over 42 numbers.
 *
 *   Left / Right     ± one day
 *   Up / Down        ± one week
 *   Home / End       first and last day of the focused week
 *   PageUp / PageDown    ± one month
 *   Shift + PageUp / PageDown   ± one year
 *   Enter / Space    select the focused day
 *
 * Three decisions that are easy to get wrong and expensive to find later:
 *
 *   - **Six rows, always.** A month occupies five or six weeks depending on
 *     where it starts. Rendering only the rows a month needs makes the grid
 *     change height as you page through it, which shifts everything below a
 *     popover and re-lays-out the page under the cursor. The trailing row
 *     costs seven muted cells and buys a fixed height.
 *   - **Arrowing onto an outside day changes the month.** The alternative —
 *     stopping at the edge — means the keyboard cannot reach the 1st of next
 *     month, which is the date people actually want.
 *   - **Focus is only moved once the grid already has it.** Writing
 *     `element.focus()` in an effect keyed on the focused date steals focus
 *     on mount, which for a calendar inside a popover scrolls the page to it
 *     before the popover has opened. The `hasFocus` ref gates that.
 *
 * Dates are compared by local midnight, never by `getTime()` on the values
 * handed in. A `Date` is an instant, two of them on the same calendar day
 * are not equal, and `sameDay` is the only comparison this file trusts.
 */

import * as React from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'

export interface CalendarProps {
  /** The selected day. `null` for no selection. */
  value?: Date | null
  onChange?: (date: Date) => void
  /** Month on show. Pass with `onMonthChange` to control paging yourself. */
  month?: Date
  onMonthChange?: (month: Date) => void
  /** Days before `min` or after `max` cannot be focused or chosen. */
  min?: Date
  max?: Date
  /** Per-day veto, for the days a rule rather than a range rules out. */
  isDisabled?: (date: Date) => boolean
  /** 0 = Sunday, 1 = Monday. */
  weekStartsOn?: 0 | 1
  /** BCP 47 tag for the month and weekday names. */
  locale?: string
  /** Names the grid — "Departure date", "Due date". */
  label?: string
  className?: string
}

/* ---------------------------------------------------------------- *
 *  Date maths, all of it local-midnight and none of it a dependency
 * ---------------------------------------------------------------- */

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

function addDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days)
}

/**
 * Add months without the 31st silently becoming the 1st.
 *
 * `new Date(2024, 0, 31)` plus one month is 31 February, which the Date
 * constructor rolls forward to 2 March. Clamping to the last day of the
 * target month is what a person means by "the next month".
 */
function addMonths(date: Date, months: number): Date {
  const target = new Date(date.getFullYear(), date.getMonth() + months, 1)
  const lastDay = new Date(target.getFullYear(), target.getMonth() + 1, 0).getDate()
  return new Date(
    target.getFullYear(),
    target.getMonth(),
    Math.min(date.getDate(), lastDay),
  )
}

function sameDay(a: Date | null | undefined, b: Date | null | undefined): boolean {
  if (!a || !b) return false
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  )
}

function sameMonth(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth()
}

/** The grid always starts on the week containing the 1st. */
function gridStart(month: Date, weekStartsOn: 0 | 1): Date {
  const first = new Date(month.getFullYear(), month.getMonth(), 1)
  const shift = (first.getDay() - weekStartsOn + 7) % 7
  return addDays(first, -shift)
}

export function Calendar({
  value = null,
  onChange,
  month,
  onMonthChange,
  min,
  max,
  isDisabled,
  weekStartsOn = 0,
  locale,
  label = 'Calendar',
  className = '',
}: CalendarProps) {
  const today = React.useMemo(() => startOfDay(new Date()), [])

  /* Uncontrolled month, used only while `month` is absent. Seeded from the
     selection so opening on a chosen date shows that date's month. */
  const [ownMonth, setOwnMonth] = React.useState<Date>(() =>
    startOfDay(month ?? value ?? today),
  )
  const shownMonth = month ?? ownMonth

  const [focused, setFocused] = React.useState<Date>(() =>
    startOfDay(value ?? month ?? today),
  )

  const gridRef = React.useRef<HTMLDivElement>(null)
  /* See the header: without this, the effect below steals focus on mount. */
  const hasFocus = React.useRef(false)

  const outOfRange = React.useCallback(
    (date: Date) => {
      if (min && date < startOfDay(min)) return true
      if (max && date > startOfDay(max)) return true
      return isDisabled?.(date) ?? false
    },
    [min, max, isDisabled],
  )

  const setMonth = React.useCallback(
    (next: Date) => {
      if (month === undefined) setOwnMonth(next)
      onMonthChange?.(next)
    },
    [month, onMonthChange],
  )

  /* Keep the shown month and the focused day in step — arrowing off the
     edge of a month is how the keyboard reaches the next one. */
  const moveFocus = React.useCallback(
    (next: Date) => {
      setFocused(next)
      if (!sameMonth(next, shownMonth)) setMonth(next)
    },
    [shownMonth, setMonth],
  )

  React.useEffect(() => {
    if (!hasFocus.current) return
    const cell = gridRef.current?.querySelector<HTMLElement>('[data-focused="true"]')
    cell?.focus()
  }, [focused])

  const fullDate = React.useMemo(
    () =>
      new Intl.DateTimeFormat(locale, {
        weekday: 'long',
        day: 'numeric',
        month: 'long',
        year: 'numeric',
      }),
    [locale],
  )

  /*
   * The 42 cells and their spoken labels, built together.
   *
   * The labels belong in the memo rather than in the cell, because
   * `Intl.DateTimeFormat.format` is not free and the alternative re-formats
   * all 42 of them on every arrow keypress — which is most of the work this
   * component does while somebody holds Right down.
   */
  const days = React.useMemo(() => {
    const start = gridStart(shownMonth, weekStartsOn)
    return Array.from({ length: 42 }, (_, i) => {
      const date = addDays(start, i)
      return { date, label: fullDate.format(date) }
    })
  }, [shownMonth, weekStartsOn, fullDate])

  const weekdayNames = React.useMemo(() => {
    const format = new Intl.DateTimeFormat(locale, { weekday: 'short' })
    const long = new Intl.DateTimeFormat(locale, { weekday: 'long' })
    /* 2024-01-07 was a Sunday, so it is a safe origin for "day N of week". */
    return Array.from({ length: 7 }, (_, i) => {
      const day = new Date(2024, 0, 7 + ((i + weekStartsOn) % 7))
      return { short: format.format(day), long: long.format(day) }
    })
  }, [locale, weekStartsOn])

  const monthLabel = React.useMemo(
    () =>
      new Intl.DateTimeFormat(locale, { month: 'long', year: 'numeric' }).format(
        shownMonth,
      ),
    [locale, shownMonth],
  )

  const select = (date: Date) => {
    if (outOfRange(date)) return
    onChange?.(date)
    moveFocus(date)
  }

  const onKeyDown = (e: React.KeyboardEvent) => {
    const key = e.key
    let next: Date | null = null

    if (key === 'ArrowLeft') next = addDays(focused, -1)
    else if (key === 'ArrowRight') next = addDays(focused, 1)
    else if (key === 'ArrowUp') next = addDays(focused, -7)
    else if (key === 'ArrowDown') next = addDays(focused, 7)
    else if (key === 'Home') {
      next = addDays(focused, -((focused.getDay() - weekStartsOn + 7) % 7))
    } else if (key === 'End') {
      next = addDays(focused, 6 - ((focused.getDay() - weekStartsOn + 7) % 7))
    } else if (key === 'PageUp') next = addMonths(focused, e.shiftKey ? -12 : -1)
    else if (key === 'PageDown') next = addMonths(focused, e.shiftKey ? 12 : 1)
    else if (key === 'Enter' || key === ' ') {
      e.preventDefault()
      select(focused)
      return
    }

    if (!next) return
    e.preventDefault()
    moveFocus(next)
  }

  return (
    <div
      className={`w-[17.5rem] rounded-xl border border-border bg-background p-3 ${className}`}
    >
      <div className="mb-2 flex items-center justify-between gap-1">
        <button
          type="button"
          onClick={() => setMonth(addMonths(shownMonth, -1))}
          aria-label="Previous month"
          className="inline-flex h-8 w-8 items-center justify-center rounded-md text-muted-foreground outline-none hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
        >
          <ChevronLeft className="h-4 w-4 rtl:rotate-180" aria-hidden />
        </button>
        {/*
          Polite, not assertive: paging the month should be read out, and it
          should never cut off whatever the user is already being told.
        */}
        <div aria-live="polite" className="text-sm font-medium text-foreground">
          {monthLabel}
        </div>
        <button
          type="button"
          onClick={() => setMonth(addMonths(shownMonth, 1))}
          aria-label="Next month"
          className="inline-flex h-8 w-8 items-center justify-center rounded-md text-muted-foreground outline-none hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
        >
          <ChevronRight className="h-4 w-4 rtl:rotate-180" aria-hidden />
        </button>
      </div>

      <div
        ref={gridRef}
        role="grid"
        aria-label={label}
        onKeyDown={onKeyDown}
        onFocus={() => {
          hasFocus.current = true
        }}
        onBlur={(e) => {
          if (!e.currentTarget.contains(e.relatedTarget as Node)) {
            hasFocus.current = false
          }
        }}
      >
        <div role="row" className="grid grid-cols-7">
          {weekdayNames.map((day) => (
            <div
              key={day.long}
              role="columnheader"
              aria-label={day.long}
              className="py-1 text-center text-[0.6875rem] font-medium uppercase tracking-wide text-muted-foreground"
            >
              {day.short}
            </div>
          ))}
        </div>

        {Array.from({ length: 6 }, (_, week) => (
          <div role="row" key={week} className="grid grid-cols-7">
            {days.slice(week * 7, week * 7 + 7).map(({ date, label: dayLabel }) => {
              const outside = !sameMonth(date, shownMonth)
              const disabled = outOfRange(date)
              const selected = sameDay(date, value)
              const isFocused = sameDay(date, focused)

              return (
                <div role="gridcell" key={date.toISOString()} aria-selected={selected}>
                  <button
                    type="button"
                    // Roving tabindex: exactly one cell is reachable by Tab.
                    tabIndex={isFocused ? 0 : -1}
                    data-focused={isFocused}
                    disabled={disabled}
                    aria-label={dayLabel}
                    aria-current={sameDay(date, today) ? 'date' : undefined}
                    onClick={() => select(date)}
                    className={[
                      'relative mx-auto flex h-9 w-9 items-center justify-center rounded-md text-sm outline-none',
                      'focus-visible:ring-2 focus-visible:ring-ring',
                      disabled
                        ? 'cursor-not-allowed text-muted-foreground/40 line-through'
                        : 'hover:bg-muted',
                      selected
                        ? 'bg-primary font-medium text-primary-foreground hover:bg-primary'
                        : outside
                          ? 'text-muted-foreground/60'
                          : 'text-foreground',
                    ].join(' ')}
                  >
                    {date.getDate()}
                    {sameDay(date, today) && !selected ? (
                      <span
                        aria-hidden
                        className="absolute bottom-1 h-1 w-1 rounded-full bg-primary"
                      />
                    ) : null}
                  </button>
                </div>
              )
            })}
          </div>
        ))}
      </div>
    </div>
  )
}

date-picker.source:
'use client'

/**
 * <DatePicker> — a field you can type a date into, with a calendar attached.
 *
 * The typing half is the half that gets dropped, and it is the one people
 * with a keyboard and a known date actually use: entering 2024-03-11 should
 * never require eleven presses of Right. So the input stays a real text
 * input, parses on blur and on Enter, and the calendar is an alternative
 * rather than the only way in.
 *
 * The popover contract, which is where these go wrong:
 *
 *   - **Escape closes and returns focus to the input.** A popover that
 *     closes and drops focus on `<body>` sends the next Tab to the top of
 *     the page, and the user has lost their place in the form.
 *   - **The calendar is not focused when it opens.** It opens *under* the
 *     input the user is still typing in; stealing focus would swallow the
 *     next keystroke. Down arrow moves into the grid deliberately.
 *   - **Clicking a day closes and returns focus too**, because choosing a
 *     date is finishing with the field, not with the page.
 *
 * Parsing is deliberately narrow: ISO `YYYY-MM-DD`, plus `D/M/YYYY` and
 * `M/D/YYYY` resolved by the `dayFirst` prop rather than guessed. A picker
 * that guesses reads 03/04 as March in one country and April in another,
 * silently, and the user never finds out. Anything it cannot parse is left
 * in the box untouched with `aria-invalid` set — clearing what someone typed
 * is the one response worse than not understanding it.
 */

import * as React from 'react'
import { CalendarDays } from 'lucide-react'

import { Calendar } from './calendar'

export interface DatePickerProps {
  value?: Date | null
  onChange?: (date: Date | null) => void
  min?: Date
  max?: Date
  isDisabled?: (date: Date) => boolean
  /** Read `3/4/2024` as 3 April rather than 4 March. */
  dayFirst?: boolean
  weekStartsOn?: 0 | 1
  locale?: string
  placeholder?: string
  disabled?: boolean
  /** Names the field — every instance needs one. */
  label: string
  className?: string
}

function pad(n: number): string {
  return String(n).padStart(2, '0')
}

/** `Date` → `YYYY-MM-DD`, in local time. `toISOString()` would shift the day. */
function toISODate(date: Date): string {
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`
}

/**
 * Parse what a person is likely to have typed, and nothing else.
 *
 * Returns `null` for anything unrecognised, which the caller shows as
 * invalid rather than correcting. Note the explicit round-trip check: the
 * `Date` constructor rolls 31 February forward to 2 March without
 * complaining, so a date that comes back as a different day was not a date.
 */
function parseDate(text: string, dayFirst: boolean): Date | null {
  const trimmed = text.trim()
  if (!trimmed) return null

  const iso = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(trimmed)
  const slashed = /^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/.exec(trimmed)

  let year: number
  let month: number
  let day: number

  if (iso) {
    year = Number(iso[1])
    month = Number(iso[2])
    day = Number(iso[3])
  } else if (slashed) {
    year = Number(slashed[3])
    month = Number(dayFirst ? slashed[2] : slashed[1])
    day = Number(dayFirst ? slashed[1] : slashed[2])
  } else {
    return null
  }

  const date = new Date(year, month - 1, day)
  if (
    date.getFullYear() !== year ||
    date.getMonth() !== month - 1 ||
    date.getDate() !== day
  ) {
    return null
  }
  return date
}

export function DatePicker({
  value = null,
  onChange,
  min,
  max,
  isDisabled,
  dayFirst = false,
  weekStartsOn = 0,
  locale,
  placeholder = 'YYYY-MM-DD',
  disabled = false,
  label,
  className = '',
}: DatePickerProps) {
  const id = React.useId()
  const [open, setOpen] = React.useState(false)
  const [text, setText] = React.useState(() => (value ? toISODate(value) : ''))
  const [invalid, setInvalid] = React.useState(false)

  const rootRef = React.useRef<HTMLDivElement>(null)
  const inputRef = React.useRef<HTMLInputElement>(null)
  const popoverRef = React.useRef<HTMLDivElement>(null)

  /* Track the value we last wrote, so a parent changing `value` refreshes
     the box while the user's own half-typed text survives a re-render. */
  const lastValue = React.useRef(value)
  React.useEffect(() => {
    if (lastValue.current === value) return
    lastValue.current = value
    setText(value ? toISODate(value) : '')
    setInvalid(false)
  }, [value])

  React.useEffect(() => {
    if (!open) return
    const onPointerDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false)
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  }, [open])

  const commitText = () => {
    if (!text.trim()) {
      setInvalid(false)
      onChange?.(null)
      return
    }
    const parsed = parseDate(text, dayFirst)
    if (!parsed) {
      setInvalid(true)
      return
    }
    setInvalid(false)
    setText(toISODate(parsed))
    lastValue.current = parsed
    onChange?.(parsed)
  }

  const close = (restoreFocus: boolean) => {
    setOpen(false)
    if (restoreFocus) inputRef.current?.focus()
  }

  const onInputKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault()
      commitText()
      setOpen(false)
    } else if (e.key === 'Escape' && open) {
      e.preventDefault()
      close(true)
    } else if (e.key === 'ArrowDown' && open) {
      // Deliberate hand-off into the grid — see the header.
      e.preventDefault()
      popoverRef.current?.querySelector<HTMLElement>('[data-focused="true"]')?.focus()
    }
  }

  return (
    <div ref={rootRef} className={`relative ${className}`}>
      <div
        className={[
          'flex items-center gap-2 rounded-lg border bg-background px-3',
          'focus-within:ring-2 focus-within:ring-ring',
          invalid ? 'border-destructive' : 'border-border',
          disabled ? 'opacity-60' : '',
        ]
          .filter(Boolean)
          .join(' ')}
      >
        <input
          ref={inputRef}
          id={id}
          type="text"
          inputMode="numeric"
          autoComplete="off"
          aria-label={label}
          aria-invalid={invalid || undefined}
          aria-describedby={invalid ? `${id}-error` : undefined}
          disabled={disabled}
          value={text}
          placeholder={placeholder}
          onChange={(e) => {
            setText(e.target.value)
            if (invalid) setInvalid(false)
          }}
          onBlur={commitText}
          onKeyDown={onInputKeyDown}
          className="h-9 w-full min-w-0 bg-transparent text-sm text-foreground outline-none placeholder:text-muted-foreground"
        />
        <button
          type="button"
          disabled={disabled}
          aria-label={open ? 'Close calendar' : 'Open calendar'}
          aria-expanded={open}
          aria-haspopup="dialog"
          aria-controls={open ? `${id}-popover` : undefined}
          onClick={() => setOpen((o) => !o)}
          className="-me-1 inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-md text-muted-foreground outline-none hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
        >
          <CalendarDays className="h-4 w-4" aria-hidden />
        </button>
      </div>

      {invalid ? (
        <p id={`${id}-error`} className="mt-1 text-xs text-destructive">
          Enter a date as {placeholder}.
        </p>
      ) : null}

      {open ? (
        <div
          ref={popoverRef}
          id={`${id}-popover`}
          role="dialog"
          aria-label={label}
          onKeyDown={(e) => {
            if (e.key === 'Escape') {
              e.preventDefault()
              close(true)
            }
          }}
          className="absolute z-50 mt-1 shadow-lg"
        >
          <Calendar
            value={value}
            min={min}
            max={max}
            isDisabled={isDisabled}
            weekStartsOn={weekStartsOn}
            locale={locale}
            label={label}
            onChange={(date) => {
              setText(toISODate(date))
              setInvalid(false)
              lastValue.current = date
              onChange?.(date)
              close(true)
            }}
          />
        </div>
      ) : null}
    </div>
  )
}

'use client'

/**
 * <Calendar> — a month grid you can drive entirely from the keyboard.
 *
 * Almost every hand-built calendar is a `<div>` of `<button>`s, which makes
 * it 42 tab stops and tells a screen reader nothing about where a date sits.
 * This is a real `role="grid"`: rows are weeks, cells are days, and the grid
 * is ONE tab stop with a roving tabindex inside it, so a keyboard user tabs
 * in, walks the month with the arrows, and tabs out. That is the WAI-ARIA
 * grid pattern and it is the whole reason this file is longer than a loop
 * over 42 numbers.
 *
 *   Left / Right     ± one day
 *   Up / Down        ± one week
 *   Home / End       first and last day of the focused week
 *   PageUp / PageDown    ± one month
 *   Shift + PageUp / PageDown   ± one year
 *   Enter / Space    select the focused day
 *
 * Three decisions that are easy to get wrong and expensive to find later:
 *
 *   - **Six rows, always.** A month occupies five or six weeks depending on
 *     where it starts. Rendering only the rows a month needs makes the grid
 *     change height as you page through it, which shifts everything below a
 *     popover and re-lays-out the page under the cursor. The trailing row
 *     costs seven muted cells and buys a fixed height.
 *   - **Arrowing onto an outside day changes the month.** The alternative —
 *     stopping at the edge — means the keyboard cannot reach the 1st of next
 *     month, which is the date people actually want.
 *   - **Focus is only moved once the grid already has it.** Writing
 *     `element.focus()` in an effect keyed on the focused date steals focus
 *     on mount, which for a calendar inside a popover scrolls the page to it
 *     before the popover has opened. The `hasFocus` ref gates that.
 *
 * Dates are compared by local midnight, never by `getTime()` on the values
 * handed in. A `Date` is an instant, two of them on the same calendar day
 * are not equal, and `sameDay` is the only comparison this file trusts.
 */

import * as React from 'react'
import { ChevronLeft, ChevronRight } from 'lucide-react'

export interface CalendarProps {
  /** The selected day. `null` for no selection. */
  value?: Date | null
  onChange?: (date: Date) => void
  /** Month on show. Pass with `onMonthChange` to control paging yourself. */
  month?: Date
  onMonthChange?: (month: Date) => void
  /** Days before `min` or after `max` cannot be focused or chosen. */
  min?: Date
  max?: Date
  /** Per-day veto, for the days a rule rather than a range rules out. */
  isDisabled?: (date: Date) => boolean
  /** 0 = Sunday, 1 = Monday. */
  weekStartsOn?: 0 | 1
  /** BCP 47 tag for the month and weekday names. */
  locale?: string
  /** Names the grid — "Departure date", "Due date". */
  label?: string
  className?: string
}

/* ---------------------------------------------------------------- *
 *  Date maths, all of it local-midnight and none of it a dependency
 * ---------------------------------------------------------------- */

function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

function addDays(date: Date, days: number): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days)
}

/**
 * Add months without the 31st silently becoming the 1st.
 *
 * `new Date(2024, 0, 31)` plus one month is 31 February, which the Date
 * constructor rolls forward to 2 March. Clamping to the last day of the
 * target month is what a person means by "the next month".
 */
function addMonths(date: Date, months: number): Date {
  const target = new Date(date.getFullYear(), date.getMonth() + months, 1)
  const lastDay = new Date(target.getFullYear(), target.getMonth() + 1, 0).getDate()
  return new Date(
    target.getFullYear(),
    target.getMonth(),
    Math.min(date.getDate(), lastDay),
  )
}

function sameDay(a: Date | null | undefined, b: Date | null | undefined): boolean {
  if (!a || !b) return false
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  )
}

function sameMonth(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth()
}

/** The grid always starts on the week containing the 1st. */
function gridStart(month: Date, weekStartsOn: 0 | 1): Date {
  const first = new Date(month.getFullYear(), month.getMonth(), 1)
  const shift = (first.getDay() - weekStartsOn + 7) % 7
  return addDays(first, -shift)
}

export function Calendar({
  value = null,
  onChange,
  month,
  onMonthChange,
  min,
  max,
  isDisabled,
  weekStartsOn = 0,
  locale,
  label = 'Calendar',
  className = '',
}: CalendarProps) {
  const today = React.useMemo(() => startOfDay(new Date()), [])

  /* Uncontrolled month, used only while `month` is absent. Seeded from the
     selection so opening on a chosen date shows that date's month. */
  const [ownMonth, setOwnMonth] = React.useState<Date>(() =>
    startOfDay(month ?? value ?? today),
  )
  const shownMonth = month ?? ownMonth

  const [focused, setFocused] = React.useState<Date>(() =>
    startOfDay(value ?? month ?? today),
  )

  const gridRef = React.useRef<HTMLDivElement>(null)
  /* See the header: without this, the effect below steals focus on mount. */
  const hasFocus = React.useRef(false)

  const outOfRange = React.useCallback(
    (date: Date) => {
      if (min && date < startOfDay(min)) return true
      if (max && date > startOfDay(max)) return true
      return isDisabled?.(date) ?? false
    },
    [min, max, isDisabled],
  )

  const setMonth = React.useCallback(
    (next: Date) => {
      if (month === undefined) setOwnMonth(next)
      onMonthChange?.(next)
    },
    [month, onMonthChange],
  )

  /* Keep the shown month and the focused day in step — arrowing off the
     edge of a month is how the keyboard reaches the next one. */
  const moveFocus = React.useCallback(
    (next: Date) => {
      setFocused(next)
      if (!sameMonth(next, shownMonth)) setMonth(next)
    },
    [shownMonth, setMonth],
  )

  React.useEffect(() => {
    if (!hasFocus.current) return
    const cell = gridRef.current?.querySelector<HTMLElement>('[data-focused="true"]')
    cell?.focus()
  }, [focused])

  const fullDate = React.useMemo(
    () =>
      new Intl.DateTimeFormat(locale, {
        weekday: 'long',
        day: 'numeric',
        month: 'long',
        year: 'numeric',
      }),
    [locale],
  )

  /*
   * The 42 cells and their spoken labels, built together.
   *
   * The labels belong in the memo rather than in the cell, because
   * `Intl.DateTimeFormat.format` is not free and the alternative re-formats
   * all 42 of them on every arrow keypress — which is most of the work this
   * component does while somebody holds Right down.
   */
  const days = React.useMemo(() => {
    const start = gridStart(shownMonth, weekStartsOn)
    return Array.from({ length: 42 }, (_, i) => {
      const date = addDays(start, i)
      return { date, label: fullDate.format(date) }
    })
  }, [shownMonth, weekStartsOn, fullDate])

  const weekdayNames = React.useMemo(() => {
    const format = new Intl.DateTimeFormat(locale, { weekday: 'short' })
    const long = new Intl.DateTimeFormat(locale, { weekday: 'long' })
    /* 2024-01-07 was a Sunday, so it is a safe origin for "day N of week". */
    return Array.from({ length: 7 }, (_, i) => {
      const day = new Date(2024, 0, 7 + ((i + weekStartsOn) % 7))
      return { short: format.format(day), long: long.format(day) }
    })
  }, [locale, weekStartsOn])

  const monthLabel = React.useMemo(
    () =>
      new Intl.DateTimeFormat(locale, { month: 'long', year: 'numeric' }).format(
        shownMonth,
      ),
    [locale, shownMonth],
  )

  const select = (date: Date) => {
    if (outOfRange(date)) return
    onChange?.(date)
    moveFocus(date)
  }

  const onKeyDown = (e: React.KeyboardEvent) => {
    const key = e.key
    let next: Date | null = null

    if (key === 'ArrowLeft') next = addDays(focused, -1)
    else if (key === 'ArrowRight') next = addDays(focused, 1)
    else if (key === 'ArrowUp') next = addDays(focused, -7)
    else if (key === 'ArrowDown') next = addDays(focused, 7)
    else if (key === 'Home') {
      next = addDays(focused, -((focused.getDay() - weekStartsOn + 7) % 7))
    } else if (key === 'End') {
      next = addDays(focused, 6 - ((focused.getDay() - weekStartsOn + 7) % 7))
    } else if (key === 'PageUp') next = addMonths(focused, e.shiftKey ? -12 : -1)
    else if (key === 'PageDown') next = addMonths(focused, e.shiftKey ? 12 : 1)
    else if (key === 'Enter' || key === ' ') {
      e.preventDefault()
      select(focused)
      return
    }

    if (!next) return
    e.preventDefault()
    moveFocus(next)
  }

  return (
    <div
      className={`w-[17.5rem] rounded-xl border border-border bg-background p-3 ${className}`}
    >
      <div className="mb-2 flex items-center justify-between gap-1">
        <button
          type="button"
          onClick={() => setMonth(addMonths(shownMonth, -1))}
          aria-label="Previous month"
          className="inline-flex h-8 w-8 items-center justify-center rounded-md text-muted-foreground outline-none hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
        >
          <ChevronLeft className="h-4 w-4 rtl:rotate-180" aria-hidden />
        </button>
        {/*
          Polite, not assertive: paging the month should be read out, and it
          should never cut off whatever the user is already being told.
        */}
        <div aria-live="polite" className="text-sm font-medium text-foreground">
          {monthLabel}
        </div>
        <button
          type="button"
          onClick={() => setMonth(addMonths(shownMonth, 1))}
          aria-label="Next month"
          className="inline-flex h-8 w-8 items-center justify-center rounded-md text-muted-foreground outline-none hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
        >
          <ChevronRight className="h-4 w-4 rtl:rotate-180" aria-hidden />
        </button>
      </div>

      <div
        ref={gridRef}
        role="grid"
        aria-label={label}
        onKeyDown={onKeyDown}
        onFocus={() => {
          hasFocus.current = true
        }}
        onBlur={(e) => {
          if (!e.currentTarget.contains(e.relatedTarget as Node)) {
            hasFocus.current = false
          }
        }}
      >
        <div role="row" className="grid grid-cols-7">
          {weekdayNames.map((day) => (
            <div
              key={day.long}
              role="columnheader"
              aria-label={day.long}
              className="py-1 text-center text-[0.6875rem] font-medium uppercase tracking-wide text-muted-foreground"
            >
              {day.short}
            </div>
          ))}
        </div>

        {Array.from({ length: 6 }, (_, week) => (
          <div role="row" key={week} className="grid grid-cols-7">
            {days.slice(week * 7, week * 7 + 7).map(({ date, label: dayLabel }) => {
              const outside = !sameMonth(date, shownMonth)
              const disabled = outOfRange(date)
              const selected = sameDay(date, value)
              const isFocused = sameDay(date, focused)

              return (
                <div role="gridcell" key={date.toISOString()} aria-selected={selected}>
                  <button
                    type="button"
                    // Roving tabindex: exactly one cell is reachable by Tab.
                    tabIndex={isFocused ? 0 : -1}
                    data-focused={isFocused}
                    disabled={disabled}
                    aria-label={dayLabel}
                    aria-current={sameDay(date, today) ? 'date' : undefined}
                    onClick={() => select(date)}
                    className={[
                      'relative mx-auto flex h-9 w-9 items-center justify-center rounded-md text-sm outline-none',
                      'focus-visible:ring-2 focus-visible:ring-ring',
                      disabled
                        ? 'cursor-not-allowed text-muted-foreground/40 line-through'
                        : 'hover:bg-muted',
                      selected
                        ? 'bg-primary font-medium text-primary-foreground hover:bg-primary'
                        : outside
                          ? 'text-muted-foreground/60'
                          : 'text-foreground',
                    ].join(' ')}
                  >
                    {date.getDate()}
                    {sameDay(date, today) && !selected ? (
                      <span
                        aria-hidden
                        className="absolute bottom-1 h-1 w-1 rounded-full bg-primary"
                      />
                    ) : null}
                  </button>
                </div>
              )
            })}
          </div>
        ))}
      </div>
    </div>
  )
}

