'use client'

/**
 * <TimePicker> — pick a time from the slots that are actually bookable.
 *
 * A `<input type="time">` is the right control when any minute will do. It
 * is the wrong one for a booking: every real scheduling UI offers a fixed
 * step, has slots that are already taken, and must say which time zone it
 * is quoting — and a native time input can express none of those three.
 *
 * The zone is the part worth insisting on. A list of times with no zone on
 * it is how this pattern wastes an hour of everyone involved, so `timeZone`
 * is rendered next to the value rather than being an option nobody passes.
 * It is a label, not a conversion: the slots are the ones the caller handed
 * over, and pretending otherwise would silently move somebody's meeting.
 *
 * It is a listbox, not a combobox — there is nothing to type into, so the
 * trigger is a button and the focus moves into the list when it opens, which
 * is the opposite of what `<Combobox>` does and correct for the same reason.
 *
 *   Down / Up      move the highlight, skipping taken slots
 *   Home / End     first and last selectable slot
 *   Enter / Space  choose the highlighted slot
 *   Escape         close, focus back on the trigger
 *
 * Times are minutes-from-midnight throughout, never `Date`s. A slot list is
 * a shape of the day, not a set of instants, and holding it as `Date`s makes
 * every comparison a DST bug waiting for the clocks to change.
 */

import * as React from 'react'
import { Check, Clock } from 'lucide-react'

export interface TimePickerProps {
  /** Minutes from midnight — `570` is 09:30. `null` for no selection. */
  value?: number | null
  onChange?: (minutes: number) => void
  /** Gap between slots, in minutes. */
  step?: number
  /** Window of the day to offer, in minutes from midnight. */
  min?: number
  max?: number
  /** Slots that exist but cannot be taken. */
  unavailable?: number[]
  hour12?: boolean
  /** Shown beside the value. A label, not a conversion — see the header. */
  timeZone?: string
  placeholder?: string
  disabled?: boolean
  label: string
  className?: string
}

function formatMinutes(minutes: number, hour12: boolean): string {
  const hour = Math.floor(minutes / 60)
  const minute = minutes % 60
  if (!hour12) {
    return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`
  }
  const suffix = hour < 12 ? 'AM' : 'PM'
  const shown = hour % 12 === 0 ? 12 : hour % 12
  return `${shown}:${String(minute).padStart(2, '0')} ${suffix}`
}

export function TimePicker({
  value = null,
  onChange,
  step = 30,
  min = 0,
  max = 24 * 60 - 1,
  unavailable = [],
  hour12 = false,
  timeZone,
  placeholder = 'Select a time',
  disabled = false,
  label,
  className = '',
}: TimePickerProps) {
  const id = React.useId()
  const [open, setOpen] = React.useState(false)
  const rootRef = React.useRef<HTMLDivElement>(null)
  const triggerRef = React.useRef<HTMLButtonElement>(null)
  const listRef = React.useRef<HTMLUListElement>(null)

  const taken = React.useMemo(() => new Set(unavailable), [unavailable])

  const slots = React.useMemo(() => {
    const out: number[] = []
    for (let m = min; m <= max; m += step) out.push(m)
    return out
  }, [min, max, step])

  const [active, setActive] = React.useState(0)

  /* Open on the current selection, or on the first slot anyone can take —
     landing the highlight on a struck-through 9am helps nobody. */
  const openList = () => {
    const selectedIndex = slots.findIndex((m) => m === value)
    const firstFree = slots.findIndex((m) => !taken.has(m))
    setActive(selectedIndex >= 0 ? selectedIndex : Math.max(0, firstFree))
    setOpen(true)
  }

  React.useEffect(() => {
    if (!open) return
    const list = listRef.current
    list?.focus()
    list?.querySelector(`[data-index="${active}"]`)?.scrollIntoView({ block: 'center' })
    // Deliberately keyed on `open` alone: scrolling to centre on every arrow
    // press would yank the list under the user. The effect below handles the
    // moving highlight, scrolling only to 'nearest'.
  }, [open])

  React.useEffect(() => {
    if (!open) return
    listRef.current
      ?.querySelector(`[data-index="${active}"]`)
      ?.scrollIntoView({ block: 'nearest' })
  }, [active, open])

  React.useEffect(() => {
    if (!open) return
    const onPointerDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false)
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  }, [open])

  const close = () => {
    setOpen(false)
    triggerRef.current?.focus()
  }

  const move = (delta: number) => {
    setActive((current) => {
      let next = current
      for (let i = 0; i < slots.length; i++) {
        next = (next + delta + slots.length) % slots.length
        if (!taken.has(slots[next])) break
      }
      return next
    })
  }

  const commit = (minutes: number) => {
    if (taken.has(minutes)) return
    onChange?.(minutes)
    close()
  }

  const onListKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault()
      move(1)
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      move(-1)
    } else if (e.key === 'Home') {
      e.preventDefault()
      setActive(Math.max(0, slots.findIndex((m) => !taken.has(m))))
    } else if (e.key === 'End') {
      e.preventDefault()
      for (let i = slots.length - 1; i >= 0; i--) {
        if (!taken.has(slots[i])) {
          setActive(i)
          break
        }
      }
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      commit(slots[active])
    } else if (e.key === 'Escape' || e.key === 'Tab') {
      e.preventDefault()
      close()
    }
  }

  return (
    <div ref={rootRef} className={`relative ${className}`}>
      <button
        ref={triggerRef}
        type="button"
        disabled={disabled}
        aria-label={label}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={open ? `${id}-list` : undefined}
        onClick={() => (open ? close() : openList())}
        onKeyDown={(e) => {
          if (e.key === 'ArrowDown' && !open) {
            e.preventDefault()
            openList()
          }
        }}
        className={[
          'flex h-9 w-full items-center gap-2 rounded-lg border border-border bg-background px-3 text-sm outline-none',
          'focus-visible:ring-2 focus-visible:ring-ring',
          disabled ? 'opacity-60' : 'hover:bg-muted/50',
        ].join(' ')}
      >
        <Clock className="h-4 w-4 shrink-0 text-muted-foreground" aria-hidden />
        <span
          className={`flex-1 text-left ${value === null ? 'text-muted-foreground' : 'text-foreground'}`}
        >
          {value === null ? placeholder : formatMinutes(value, hour12)}
        </span>
        {timeZone ? (
          <span className="shrink-0 text-xs text-muted-foreground">{timeZone}</span>
        ) : null}
      </button>

      {open ? (
        <ul
          ref={listRef}
          id={`${id}-list`}
          role="listbox"
          aria-label={label}
          aria-activedescendant={`${id}-slot-${active}`}
          tabIndex={-1}
          onKeyDown={onListKeyDown}
          className="absolute z-50 mt-1 max-h-60 w-full overflow-auto rounded-lg border border-border bg-popover p-1 shadow-lg outline-none"
        >
          {slots.map((minutes, i) => {
            const isTaken = taken.has(minutes)
            const selected = minutes === value
            return (
              <li
                key={minutes}
                id={`${id}-slot-${i}`}
                data-index={i}
                role="option"
                aria-selected={selected}
                aria-disabled={isTaken || undefined}
                onPointerDown={(e) => {
                  e.preventDefault()
                  commit(minutes)
                }}
                onPointerEnter={() => !isTaken && setActive(i)}
                className={[
                  'flex cursor-pointer items-center gap-2 rounded-md px-2.5 py-2 text-sm',
                  isTaken
                    ? 'pointer-events-none text-muted-foreground/50 line-through'
                    : 'text-foreground',
                  i === active && !isTaken ? 'bg-muted' : '',
                ]
                  .filter(Boolean)
                  .join(' ')}
              >
                <Check
                  className={`h-4 w-4 shrink-0 ${selected ? 'opacity-100' : 'opacity-0'}`}
                  aria-hidden
                />
                <span className="flex-1">{formatMinutes(minutes, hour12)}</span>
                {isTaken ? (
                  <span className="text-xs text-muted-foreground">Booked</span>
                ) : null}
              </li>
            )
          })}
        </ul>
      ) : null}
    </div>
  )
}

relative-time.source:
'use client'

/**
 * <RelativeTime> — "3 hours ago", without the hydration bug.
 *
 * Every app writes this and most write it twice, because the obvious version
 * is wrong in a way that only shows up in production:
 *
 *   **It cannot be rendered on the server.** The server formats "2 minutes
 *   ago" at one instant and the browser re-renders it at another, React
 *   compares the two strings, and you get a hydration mismatch on a page
 *   that looked fine in dev. The fix here is that the first client render is
 *   *identical to the server's by construction*: `now` starts as `null` and
 *   both sides render the absolute date. The relative string only appears in
 *   an effect, which never runs on the server and always runs after
 *   hydration has matched.
 *
 *   **It goes stale.** A timestamp that says "1 minute ago" for the twenty
 *   minutes somebody left the tab open is worse than a fixed date. The tick
 *   interval scales with the magnitude — every 10s under a minute, every
 *   minute under an hour, hourly after that — so a feed of a hundred of
 *   these is not a hundred one-second timers.
 *
 *   **Its ABSOLUTE half has the same bug, one layer down.** The fix above
 *   makes both sides render the absolute date — which only helps if the two
 *   sides format it the same way, and by default they do not.
 *   `Intl.DateTimeFormat(undefined, …)` resolves the *runtime's* locale and
 *   zone: Node's on the server (24-hour, UTC on a typical host) and the
 *   reader's in the browser. "14 Sept 2026, 20:12" against "14 Sept 2026,
 *   8:12 pm", on the exact render this component exists to get right. So
 *   the pre-mount format is pinned to a fixed locale and UTC and the
 *   reader's own formatting takes over in the effect, where nothing can
 *   disagree with it. See `absolute` below.
 *
 * The rendered element is a real `<time dateTime={...}>` carrying the
 * machine-readable instant, with the full absolute date in `title`. That is
 * what makes it copyable, translatable and meaningful to a crawler, and it
 * is why this is not a `<span>`.
 *
 * `Intl.RelativeTimeFormat` does the wording, so "hace 3 horas" costs a
 * locale prop rather than a translation table.
 */

import * as React from 'react'

export interface RelativeTimeProps {
  /** The instant being described. */
  date: Date | string | number
  /** BCP 47 tag. Defaults to the browser's. */
  locale?: string
  /** `'long'` → "3 hours ago", `'narrow'` → "3h ago". */
  style?: 'long' | 'short' | 'narrow'
  /**
   * Past this many seconds, show the absolute date instead. Nobody reads
   * "14 months ago" as a date; default is 30 days.
   */
  absoluteAfter?: number
  className?: string
}

const MINUTE = 60
const HOUR = 60 * MINUTE
const DAY = 24 * HOUR
const WEEK = 7 * DAY
const MONTH = 30 * DAY
const YEAR = 365 * DAY

/**
 * What the absolute date is formatted in before mount, when the caller
 * named no locale. Any fixed tag would do — this one only has to be the
 * same on the server and in the browser.
 */
const SSR_LOCALE = 'en-GB'

/** Largest unit that divides the gap, so 90 minutes reads "1 hour" not "90 minutes". */
const UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ['year', YEAR],
  ['month', MONTH],
  ['week', WEEK],
  ['day', DAY],
  ['hour', HOUR],
  ['minute', MINUTE],
  ['second', 1],
]

/** How often this instant's wording could change. See the header. */
function tickInterval(seconds: number): number {
  const gap = Math.abs(seconds)
  if (gap < MINUTE) return 10_000
  if (gap < HOUR) return 60_000
  return 3_600_000
}

export function RelativeTime({
  date,
  locale,
  style = 'long',
  absoluteAfter = 30 * DAY,
  className = '',
}: RelativeTimeProps) {
  const instant = React.useMemo(() => new Date(date), [date])

  /* null until mounted — this is the whole hydration story, see the header. */
  const [now, setNow] = React.useState<number | null>(null)

  React.useEffect(() => {
    const tick = () => setNow(Date.now())
    tick()
    let timer: ReturnType<typeof setTimeout>
    const schedule = () => {
      const seconds = (Date.now() - instant.getTime()) / 1000
      timer = setTimeout(() => {
        tick()
        schedule()
      }, tickInterval(seconds))
    }
    schedule()
    return () => clearTimeout(timer)
  }, [instant])

  /*
   * Mount is the only thing `absolute` needs from the clock, so it depends
   * on the flag rather than on `now` — otherwise every tick would rebuild
   * a formatter whose output cannot have changed.
   */
  const mounted = now !== null

  const absolute = React.useMemo(() => {
    // Pinned only while both of these hold: the caller named no locale (an
    // explicit one already agrees on both sides), and we have not mounted
    // yet (after that, the reader's own format is the right answer and the
    // server is no longer in the conversation). Same bargain, and the same
    // reason, as `formatAdded` in `lib/recency`.
    const pinned = locale === undefined && !mounted
    return new Intl.DateTimeFormat(pinned ? SSR_LOCALE : locale, {
      dateStyle: 'medium',
      timeStyle: 'short',
      timeZone: pinned ? 'UTC' : undefined,
    }).format(instant)
  }, [locale, instant, mounted])

  const text = React.useMemo(() => {
    if (now === null) return absolute

    const seconds = Math.round((instant.getTime() - now) / 1000)
    if (Math.abs(seconds) > absoluteAfter) return absolute

    const format = new Intl.RelativeTimeFormat(locale, { numeric: 'auto', style })
    for (const [unit, size] of UNITS) {
      if (Math.abs(seconds) >= size || unit === 'second') {
        /* Truncate toward zero: 59 minutes is "59 minutes ago", not "1 hour
           ago", and rounding away from zero would put it in the future. */
        return format.format(Math.trunc(seconds / size), unit)
      }
    }
    return absolute
  }, [now, instant, locale, style, absoluteAfter, absolute])

  return (
    <time dateTime={instant.toISOString()} title={absolute} className={className}>
      {text}
    </time>
  )
}

duration-input.source:
'use client'

/**
 * <DurationInput> — three boxes that behave like one field.
 *
 * A duration typed into a single text box has to be parsed, and every parser
 * argues with its users about whether `1:30` is an hour and a half or ninety
 * seconds. Three labelled segments never have that argument. The cost is
 * that three inputs are three tab stops and feel like a form rather than a
 * field, so most of this file is spent making them feel like one:
 *
 *   - **Typing past a segment advances to the next.** Two digits in the
 *     hours box moves to minutes, the way a card-number field does.
 *   - **Backspace in an empty segment goes back** and puts the caret at the
 *     end of the previous one, so a wrong entry is fixed by holding
 *     Backspace rather than by aiming with the mouse.
 *   - **Up/Down step the segment under the caret** and carry properly: 59
 *     minutes + 1 is one more hour and zero minutes, not `60`.
 *   - **Pasting `1:30:00` fills all three**, because that is what people
 *     have on their clipboard. The paste handler is on the group, so it
 *     works whichever segment is focused.
 *
 * `role="group"` with an `aria-labelledby` is what ties the three together
 * for a screen reader, and each segment keeps its own `aria-label` so the
 * announcement is "Duration, Minutes, 30" rather than three loose numbers.
 *
 * The value is a plain number of seconds. Everything else — clamping, the
 * carry, the zero padding — happens on the way in and out, so a consumer
 * never has to hold three pieces of state to hold one duration.
 */

import * as React from 'react'

export interface DurationInputProps {
  /** Total seconds. */
  value?: number
  onChange?: (seconds: number) => void
  /** Drop the seconds box for durations nobody measures that finely. */
  showSeconds?: boolean
  /** Upper bound in seconds. Entry is clamped, not rejected. */
  max?: number
  disabled?: boolean
  /** Names the group — "Session length", "Time spent". */
  label: string
  className?: string
}

interface Segment {
  key: 'hours' | 'minutes' | 'seconds'
  label: string
  /** Exclusive ceiling for the segment, and how many of them make the next. */
  size: number
  width: string
}

const ALL_SEGMENTS: Segment[] = [
  { key: 'hours', label: 'Hours', size: Infinity, width: 'w-12' },
  { key: 'minutes', label: 'Minutes', size: 60, width: 'w-10' },
  { key: 'seconds', label: 'Seconds', size: 60, width: 'w-10' },
]

function split(total: number, showSeconds: boolean) {
  const safe = Math.max(0, Math.floor(total))
  if (!showSeconds) {
    return { hours: Math.floor(safe / 3600), minutes: Math.floor((safe % 3600) / 60), seconds: 0 }
  }
  return {
    hours: Math.floor(safe / 3600),
    minutes: Math.floor((safe % 3600) / 60),
    seconds: safe % 60,
  }
}

export function DurationInput({
  value = 0,
  onChange,
  showSeconds = true,
  max,
  disabled = false,
  label,
  className = '',
}: DurationInputProps) {
  const id = React.useId()
  const segments = React.useMemo(
    () => (showSeconds ? ALL_SEGMENTS : ALL_SEGMENTS.slice(0, 2)),
    [showSeconds],
  )
  const refs = React.useRef<(HTMLInputElement | null)[]>([])
  const parts = split(value, showSeconds)

  /* Which segment is mid-edit, and what is in it. A segment holding "" or
     "0" while someone types the second digit of "05" cannot be derived from
     the number, so it lives here until it commits. */
  const [draft, setDraft] = React.useState<{ index: number; text: string } | null>(null)

  const emit = (next: { hours: number; minutes: number; seconds: number }) => {
    let total = next.hours * 3600 + next.minutes * 60 + next.seconds
    if (max !== undefined) total = Math.min(total, max)
    onChange?.(Math.max(0, total))
  }

  const commit = (index: number, raw: string) => {
    const segment = segments[index]
    const typed = Number(raw || '0')
    /* Clamp the minute and second boxes rather than carrying: someone typing
       "75" into minutes meant 75 minutes, but the box cannot show it, and
       silently becoming 1:15 while they are still typing is worse than
       stopping at 59. The Up/Down handler carries; typing does not. */
    const bounded = Number.isFinite(segment.size)
      ? Math.min(typed, segment.size - 1)
      : typed
    emit({ ...parts, [segment.key]: bounded })
  }

  const step = (index: number, delta: number) => {
    const segment = segments[index]
    const unit = segment.key === 'hours' ? 3600 : segment.key === 'minutes' ? 60 : 1
    emit(split(Math.max(0, value + delta * unit), showSeconds))
  }

  const focusSegment = (index: number, caretAtEnd = false) => {
    const input = refs.current[index]
    if (!input) return
    input.focus()
    if (caretAtEnd) {
      const end = input.value.length
      requestAnimationFrame(() => input.setSelectionRange(end, end))
    } else {
      input.select()
    }
  }

  const onSegmentKeyDown = (e: React.KeyboardEvent<HTMLInputElement>, index: number) => {
    if (e.key === 'ArrowUp') {
      e.preventDefault()
      step(index, 1)
    } else if (e.key === 'ArrowDown') {
      e.preventDefault()
      step(index, -1)
    } else if (e.key === 'ArrowLeft' && e.currentTarget.selectionStart === 0 && index > 0) {
      e.preventDefault()
      focusSegment(index - 1, true)
    } else if (
      e.key === 'ArrowRight' &&
      e.currentTarget.selectionStart === e.currentTarget.value.length &&
      index < segments.length - 1
    ) {
      e.preventDefault()
      focusSegment(index + 1)
    } else if (e.key === 'Backspace' && e.currentTarget.value === '' && index > 0) {
      e.preventDefault()
      focusSegment(index - 1, true)
    } else if (e.key === ':' || e.key === '.') {
      // The separator people type between segments is a request to move on.
      e.preventDefault()
      if (index < segments.length - 1) focusSegment(index + 1)
    }
  }

  const onPaste = (e: React.ClipboardEvent) => {
    const text = e.clipboardData.getData('text').trim()
    if (!/^\d{1,3}(:\d{1,2}){1,2}$/.test(text)) return
    e.preventDefault()
    const chunks = text.split(':').map(Number)
    /* `1:30` is minutes:seconds when seconds are shown and hours:minutes
       when they are not — the shorter form means the units on screen. */
    const [hours, minutes, seconds] =
      chunks.length === 3
        ? chunks
        : showSeconds
          ? [0, chunks[0], chunks[1]]
          : [chunks[0], chunks[1], 0]
    setDraft(null)
    emit({ hours, minutes, seconds })
  }

  return (
    <div className={className}>
      <span id={`${id}-label`} className="sr-only">
        {label}
      </span>
      <div
        role="group"
        aria-labelledby={`${id}-label`}
        onPaste={onPaste}
        className={[
          'inline-flex items-center gap-0.5 rounded-lg border border-border bg-background px-2 py-1',
          'focus-within:ring-2 focus-within:ring-ring',
          disabled ? 'opacity-60' : '',
        ]
          .filter(Boolean)
          .join(' ')}
      >
        {segments.map((segment, index) => (
          <React.Fragment key={segment.key}>
            {index > 0 ? (
              <span aria-hidden className="text-sm text-muted-foreground">
                :
              </span>
            ) : null}
            <span className="flex flex-col items-center">
              <input
                ref={(el) => {
                  refs.current[index] = el
                }}
                type="text"
                inputMode="numeric"
                autoComplete="off"
                disabled={disabled}
                aria-label={segment.label}
                value={
                  draft?.index === index
                    ? draft.text
                    : String(parts[segment.key]).padStart(2, '0')
                }
                onChange={(e) => {
                  const digits = e.target.value.replace(/\D/g, '').slice(-2)
                  setDraft({ index, text: digits })
                  commit(index, digits)
                  // Two digits fills the box — move on, as a card field does.
                  if (digits.length === 2 && index < segments.length - 1) {
                    setDraft(null)
                    focusSegment(index + 1)
                  }
                }}
                onFocus={(e) => e.currentTarget.select()}
                onBlur={() => setDraft(null)}
                onKeyDown={(e) => onSegmentKeyDown(e, index)}
                className={`${segment.width} bg-transparent text-center font-mono text-sm tabular-nums text-foreground outline-none`}
              />
              <span aria-hidden className="text-[0.625rem] uppercase text-muted-foreground">
                {segment.label.slice(0, 3)}
              </span>
            </span>
          </React.Fragment>
        ))}
      </div>
    </div>
  )
}

message-bubble.source:
'use client'

/**
 * <MessageBubble> — one turn in a conversation.
 *
 * The catalog already ships `<ChatThreadPanel>`, which is a whole thread
 * with a composer pinned under it. This is the piece that thread is made
 * of, for the far more common case: you have your own list, your own
 * scroll behaviour and your own streaming hook, and what you actually want
 * is for one turn to be drawn and announced correctly.
 *
 * Three decisions carry it.
 *
 * **Alignment and colour are not an accessible name.** Every chat UI tells
 * you who is speaking by putting the user on the right in a coloured
 * bubble and the assistant on the left in a grey one. Read aloud, both are
 * an unattributed paragraph, and a thread of them is one long monologue by
 * nobody. So the speaker is always in the text — visibly where there is a
 * header, `sr-only` where the design has none.
 *
 * **It is an `<article>`.** Screen readers expose articles as a navigable
 * unit, which is what turns a log into something you can move through turn
 * by turn rather than line by line. `aria-labelledby` points at the
 * speaker, so moving between them announces who said what.
 *
 * **The timestamp is formatted twice, on purpose.** `toLocaleTimeString`
 * reads the server's locale and timezone during SSR and the browser's
 * during hydration, which is a mismatch React resolves by throwing the
 * subtree away — silently, and only for users whose timezone differs from
 * the build machine's. The fix is to render an explicit UTC string first
 * and swap in the local one from an effect: one extra paint, always right.
 */

import * as React from 'react'

export type MessageRole = 'user' | 'assistant' | 'system'

export interface MessageBubbleProps {
  role: MessageRole
  /** Overrides the default name for the role. */
  name?: string
  /** Rendered beside the bubble. Any node — an image, initials, an icon. */
  avatar?: React.ReactNode
  /** ISO string or Date. Rendered as a real `<time>`. */
  timestamp?: string | Date
  /**
   * Copy, retry, feedback. Revealed on hover *and* focus-within, because a
   * row that appears only on hover does not exist for a keyboard or a
   * touchscreen — pass `alwaysShowActions` where that matters more than
   * the quiet default.
   */
  actions?: React.ReactNode
  alwaysShowActions?: boolean
  /** Draws the bubble as unsent, and announces it. */
  pending?: boolean
  className?: string
  children: React.ReactNode
}

const DEFAULT_NAME: Record<MessageRole, string> = {
  user: 'You',
  assistant: 'Assistant',
  system: 'System',
}

const BUBBLE: Record<MessageRole, string> = {
  user: 'bg-primary text-primary-foreground',
  assistant: 'bg-muted text-foreground',
  system: 'border border-border bg-card text-muted-foreground',
}

function isoOf(value: string | Date): string {
  return typeof value === 'string' ? value : value.toISOString()
}

export function MessageBubble({
  role,
  name,
  avatar,
  timestamp,
  actions,
  alwaysShowActions = false,
  pending = false,
  className = '',
  children,
}: MessageBubbleProps) {
  const uid = React.useId()
  const speaker = name ?? DEFAULT_NAME[role]
  const iso = timestamp ? isoOf(timestamp) : undefined

  // Server and first client render agree on UTC; the effect replaces it
  // with the reader's own clock once there is a reader. See the header.
  const [clock, setClock] = React.useState(() =>
    iso
      ? new Date(iso).toLocaleTimeString('en-GB', {
          hour: '2-digit',
          minute: '2-digit',
          timeZone: 'UTC',
        })
      : '',
  )

  React.useEffect(() => {
    if (!iso) return
    setClock(
      new Date(iso).toLocaleTimeString(undefined, {
        hour: '2-digit',
        minute: '2-digit',
      }),
    )
  }, [iso])

  const mine = role === 'user'

  return (
    <article
      aria-labelledby={`${uid}-speaker`}
      className={[
        'group flex w-full gap-3',
        mine ? 'flex-row-reverse' : 'flex-row',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
    >
      {avatar ? (
        <span
          aria-hidden="true"
          className="mt-0.5 grid size-8 shrink-0 place-items-center overflow-hidden rounded-full bg-muted text-xs font-medium text-muted-foreground"
        >
          {avatar}
        </span>
      ) : null}

      <div className={['flex min-w-0 max-w-[85%] flex-col gap-1', mine ? 'items-end' : 'items-start'].join(' ')}>
        <p className="flex items-baseline gap-2 text-xs text-muted-foreground">
          <span id={`${uid}-speaker`} className="font-medium text-foreground">
            {speaker}
          </span>
          {iso ? (
            <time dateTime={iso} className="tabular-nums">
              {clock}
            </time>
          ) : null}
        </p>

        <div
          className={[
            'rounded-2xl px-3.5 py-2.5 text-sm leading-relaxed',
            mine ? 'rounded-se-sm' : 'rounded-ss-sm',
            BUBBLE[role],
            pending ? 'opacity-60' : '',
          ]
            .filter(Boolean)
            .join(' ')}
        >
          {children}
        </div>

        {pending ? <span className="sr-only">Sending</span> : null}

        {actions ? (
          <div
            className={[
              'flex items-center gap-1 transition-opacity',
              alwaysShowActions
                ? 'opacity-100'
                : 'opacity-0 group-hover:opacity-100 group-focus-within:opacity-100',
            ].join(' ')}
          >
            {actions}
          </div>
        ) : null}
      </div>
    </article>
  )
}

prompt-input.source:
'use client'

/**
 * <PromptInput> — the composer, reduced to the part that is actually hard.
 *
 * A textarea with a send button takes five minutes. These four things take
 * the rest of the day, and this is all of them:
 *
 * **Enter must not send during IME composition.** Typing Japanese, Chinese
 * or Korean means typing romaji, seeing candidates, and pressing Enter to
 * commit the one you want. A composer that sends on Enter sends a
 * half-converted fragment and clears the box, and the bug is invisible to
 * anyone testing in English — which is everyone who ships it. The guard is
 * `event.nativeEvent.isComposing`, and it is one line that nothing will
 * ever remind you to write.
 *
 * **Submission goes through a real `<form>`.** The keydown handler calls
 * `requestSubmit()` rather than invoking the submit logic directly, so
 * there is exactly one submit path: the button, the Enter key, and the
 * mobile keyboard's own "go" all run the same code and the same validation.
 * Two paths is how a composer ends up sending empty strings from one of
 * them.
 *
 * **Stop is a different button from send.** The obvious implementation
 * relabels one button while streaming. To a screen reader user whose focus
 * is on it, the control they are sitting on silently becomes a different
 * control — and the one they meant to press has moved. Rendering them as
 * two buttons makes the swap a focus change, which is what it actually is.
 *
 * **Auto-grow is capped in rows, not pixels.** The cap has to survive the
 * user's font size, so it is measured from the element's own line-height
 * rather than assumed to be 24px.
 */

import * as React from 'react'
import { ArrowUp, Square } from 'lucide-react'

export interface PromptInputProps {
  /** Controlled value. Omit both this and `onValueChange` to run uncontrolled. */
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  /** Called with the trimmed value. Never called with an empty string. */
  onSubmit?: (value: string) => void
  /** Swaps send for stop and blocks submission. */
  streaming?: boolean
  onStop?: () => void
  placeholder?: string
  disabled?: boolean
  minRows?: number
  maxRows?: number
  /** Attachment and model controls, rendered along the bottom edge. */
  toolbar?: React.ReactNode
  /** Shown under the field — a hint, a counter, an error. */
  footer?: React.ReactNode
  className?: string
}

export function PromptInput({
  value,
  defaultValue = '',
  onValueChange,
  onSubmit,
  streaming = false,
  onStop,
  placeholder = 'Ask anything…',
  disabled = false,
  minRows = 1,
  maxRows = 8,
  toolbar,
  footer,
  className = '',
}: PromptInputProps) {
  const uid = React.useId()
  const areaRef = React.useRef<HTMLTextAreaElement>(null)
  const formRef = React.useRef<HTMLFormElement>(null)
  const [internal, setInternal] = React.useState(defaultValue)

  const controlled = value !== undefined
  const text = controlled ? value : internal

  const setText = (next: string) => {
    if (!controlled) setInternal(next)
    onValueChange?.(next)
  }

  // Grow to fit, then stop. Resetting to `auto` first is what lets the box
  // shrink again when text is deleted; without it scrollHeight only ever
  // reports the tallest it has been.
  React.useEffect(() => {
    const el = areaRef.current
    if (!el) return
    el.style.height = 'auto'
    const lineHeight = parseFloat(getComputedStyle(el).lineHeight) || 20
    const padding = el.offsetHeight - el.clientHeight
    el.style.height = `${Math.min(el.scrollHeight, lineHeight * maxRows + padding)}px`
  }, [text, maxRows])

  const canSend = text.trim().length > 0 && !disabled && !streaming

  const handleSubmit = (event: React.FormEvent) => {
    event.preventDefault()
    if (!canSend) return
    onSubmit?.(text.trim())
    setText('')
  }

  const handleKeyDown = (event: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key !== 'Enter' || event.shiftKey) return
    // The line this component exists for. See the header.
    if (event.nativeEvent.isComposing) return
    event.preventDefault()
    formRef.current?.requestSubmit()
  }

  return (
    <form
      ref={formRef}
      onSubmit={handleSubmit}
      className={[
        'rounded-2xl border border-border bg-card p-2 shadow-sm',
        'focus-within:border-primary/50 focus-within:ring-2 focus-within:ring-primary/20',
        disabled ? 'opacity-60' : '',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
    >
      <label htmlFor={`${uid}-field`} className="sr-only">
        {placeholder}
      </label>
      <textarea
        id={`${uid}-field`}
        ref={areaRef}
        rows={minRows}
        value={text}
        disabled={disabled}
        placeholder={placeholder}
        onChange={(event) => setText(event.target.value)}
        onKeyDown={handleKeyDown}
        aria-describedby={footer ? `${uid}-footer` : undefined}
        className="block w-full resize-none bg-transparent px-2 py-1.5 text-sm leading-relaxed text-foreground outline-none placeholder:text-muted-foreground"
      />

      <div className="flex items-end justify-between gap-2 pt-1">
        <div className="flex min-w-0 items-center gap-1">{toolbar}</div>

        {streaming ? (
          <button
            type="button"
            onClick={onStop}
            className="grid size-8 shrink-0 place-items-center rounded-full bg-foreground text-background transition-opacity hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
          >
            <Square className="size-3.5 fill-current" aria-hidden="true" />
            <span className="sr-only">Stop generating</span>
          </button>
        ) : (
          <button
            type="submit"
            disabled={!canSend}
            className="grid size-8 shrink-0 place-items-center rounded-full bg-primary text-primary-foreground transition-opacity hover:opacity-90 disabled:opacity-40 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
          >
            <ArrowUp className="size-4" aria-hidden="true" />
            <span className="sr-only">Send message</span>
          </button>
        )}
      </div>

      {footer ? (
        <p id={`${uid}-footer`} className="px-2 pb-1 pt-1.5 text-xs text-muted-foreground">
          {footer}
        </p>
      ) : null}
    </form>
  )
}

tool-call.source:
'use client'

/**
 * <ToolCall> — one tool invocation: what was called, how it went, and the
 * arguments and result one click away.
 *
 * The catalog's `<AgentToolCalls>` block is a *list* of these with the
 * grouping and density decisions already made. This is the single row, for
 * when the list is yours and the shape of a call is what you needed.
 *
 * **The status is never colour alone.** Every chip carries a glyph and an
 * `sr-only` word alongside the tint. "Which of these failed", answered only
 * in red, is not answered at all for roughly one man in twelve — and not
 * for anyone reading the thread in a transcript.
 *
 * **It is a button, not `<details>`.** Its sibling `<ReasoningPanel>` uses
 * the native element and is the better default; this one cannot, because
 * the open state is frequently driven from outside — auto-expanding the
 * call that errored, collapsing every call when a new run starts — and a
 * controlled `<details>` fights its own `toggle` event. So: `aria-expanded`,
 * `aria-controls`, and a real controlled/uncontrolled pair.
 *
 * **Arguments are a `<dl>`, not a table.** The shape is genuinely a list of
 * name/value pairs. A two-column table makes a screen reader user navigate
 * by row and column through something that has neither.
 *
 * **The duration is formatted arithmetically**, never through
 * `toLocaleString`. A number formatted against the server's locale and then
 * re-formatted against the browser's is a hydration mismatch that only
 * appears for users outside the build machine's locale.
 */

import * as React from 'react'
import { Check, ChevronDown, Clock, Loader2, TriangleAlert } from 'lucide-react'

export type ToolCallStatus = 'pending' | 'running' | 'success' | 'error'

export interface ToolCallProps {
  /** The tool's name, as the model called it. */
  name: string
  status: ToolCallStatus
  /** One line of context for the collapsed row — usually the key argument. */
  summary?: string
  /** Rendered as a definition list when given an object. */
  args?: Record<string, React.ReactNode> | React.ReactNode
  result?: React.ReactNode
  durationMs?: number
  /** Controlled disclosure. Omit for uncontrolled. */
  open?: boolean
  onOpenChange?: (open: boolean) => void
  defaultOpen?: boolean
  className?: string
}

const STATUS: Record<ToolCallStatus, { label: string; tint: string; Icon: typeof Check }> = {
  pending: { label: 'Queued', tint: 'text-muted-foreground', Icon: Clock },
  running: { label: 'Running', tint: 'text-sky-600 dark:text-sky-400', Icon: Loader2 },
  success: { label: 'Succeeded', tint: 'text-emerald-600 dark:text-emerald-400', Icon: Check },
  error: { label: 'Failed', tint: 'text-destructive', Icon: TriangleAlert },
}

/** `1420` → `1.4s`. No locale involved, so it cannot drift at hydration. */
function formatDuration(ms: number): string {
  if (ms < 1000) return `${Math.round(ms)}ms`
  const seconds = ms / 1000
  return seconds < 10 ? `${seconds.toFixed(1)}s` : `${Math.round(seconds)}s`
}

function isPairs(value: unknown): value is Record<string, React.ReactNode> {
  return (
    typeof value === 'object' &&
    value !== null &&
    !React.isValidElement(value) &&
    !Array.isArray(value)
  )
}

export function ToolCall({
  name,
  status,
  summary,
  args,
  result,
  durationMs,
  open,
  onOpenChange,
  defaultOpen = false,
  className = '',
}: ToolCallProps) {
  const uid = React.useId()
  const [internal, setInternal] = React.useState(defaultOpen)
  const isOpen = open ?? internal
  const expandable = args !== undefined || result !== undefined

  const toggle = () => {
    const next = !isOpen
    if (open === undefined) setInternal(next)
    onOpenChange?.(next)
  }

  const { label, tint, Icon } = STATUS[status]

  return (
    <div
      className={['overflow-hidden rounded-lg border border-border bg-card', className]
        .filter(Boolean)
        .join(' ')}
    >
      <button
        type="button"
        onClick={toggle}
        disabled={!expandable}
        aria-expanded={expandable ? isOpen : undefined}
        aria-controls={expandable ? `${uid}-panel` : undefined}
        className="flex w-full items-center gap-2.5 px-3 py-2 text-start text-sm hover:bg-muted/60 disabled:cursor-default disabled:hover:bg-transparent focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-primary"
      >
        <Icon
          aria-hidden="true"
          className={[
            'size-4 shrink-0',
            tint,
            status === 'running' ? 'motion-safe:animate-spin' : '',
          ]
            .filter(Boolean)
            .join(' ')}
        />
        <span className="sr-only">{label}: </span>

        <code className="min-w-0 shrink-0 font-mono text-[13px] font-medium text-foreground">
          {name}
        </code>

        {summary ? (
          <span className="min-w-0 flex-1 truncate text-xs text-muted-foreground">{summary}</span>
        ) : (
          <span className="flex-1" />
        )}

        {durationMs !== undefined ? (
          <span className="shrink-0 text-xs tabular-nums text-muted-foreground">
            {formatDuration(durationMs)}
          </span>
        ) : null}

        {expandable ? (
          <ChevronDown
            aria-hidden="true"
            className={[
              'size-4 shrink-0 text-muted-foreground transition-transform',
              isOpen ? 'rotate-180' : '',
            ]
              .filter(Boolean)
              .join(' ')}
          />
        ) : null}
      </button>

      {expandable && isOpen ? (
        <div id={`${uid}-panel`} className="space-y-3 border-t border-border px-3 py-2.5">
          {args !== undefined ? (
            <div>
              <p className="mb-1 text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
                Arguments
              </p>
              {isPairs(args) ? (
                <dl className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-1 text-xs">
                  {Object.entries(args).map(([key, value]) => (
                    <React.Fragment key={key}>
                      <dt className="font-mono text-muted-foreground">{key}</dt>
                      <dd className="min-w-0 break-words font-mono text-foreground">{value}</dd>
                    </React.Fragment>
                  ))}
                </dl>
              ) : (
                <div className="text-xs text-foreground">{args}</div>
              )}
            </div>
          ) : null}

          {result !== undefined ? (
            <div>
              <p className="mb-1 text-[11px] font-medium uppercase tracking-wide text-muted-foreground">
                Result
              </p>
              <div
                className={[
                  'rounded-md px-2.5 py-2 text-xs',
                  status === 'error'
                    ? 'bg-destructive/10 text-destructive'
                    : 'bg-muted text-foreground',
                ].join(' ')}
              >
                {result}
              </div>
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  )
}

citation-chip.source:
/**
 * <CitationChip> — one numbered source reference, inline in the prose or as
 * a card under it.
 *
 * **The numeral is not the accessible name.** A citation rendered as
 * `<sup><a href="…">1</a></sup>` is announced as "link, one". In a list of
 * links — which is how many people navigate a page — it is one of eight
 * entries all called a digit, and choosing between them is impossible. So
 * the visible text stays the numeral the prose refers to, and the
 * `aria-label` carries what the link actually goes to.
 *
 * **`<cite>` is the element for the title of a referenced work.** It is one
 * of the few HTML elements that means precisely the thing being marked up
 * here, and it costs nothing to use correctly.
 *
 * **There is no hover card.** The obvious design puts the snippet in a
 * tooltip, which is unreachable by touch, needs a focus and dismissal
 * contract to satisfy 1.4.13, and hides the one piece of text that would
 * let a reader judge the source without leaving the page. The `card`
 * variant puts the snippet on the page instead. If you want the popover,
 * build it around this — but the default should not be the version that
 * only works with a mouse.
 *
 * **New tabs announce themselves.** `target="_blank"` without a warning is
 * a 3.2.5 failure: the back button stops working and nobody said why.
 */

import * as React from 'react'

export interface CitationChipProps {
  /** The number the prose refers to. Rendered visibly; never the whole name. */
  index: number
  title: string
  href?: string
  /** The publication or domain — "arxiv.org", "Internal wiki". */
  source?: string
  /** Shown in the `card` variant, ignored inline. */
  snippet?: string
  variant?: 'inline' | 'card'
  /** Opens in a new tab, with the warning that obliges. */
  newTab?: boolean
  className?: string
}

export function CitationChip({
  index,
  title,
  href,
  source,
  snippet,
  variant = 'inline',
  newTab = false,
  className = '',
}: CitationChipProps) {
  const accessibleName = source ? `Source ${index}: ${title}, ${source}` : `Source ${index}: ${title}`
  const external = newTab && href ? { target: '_blank', rel: 'noreferrer' } : {}

  if (variant === 'inline') {
    const chip = (
      <>
        {index}
        <span className="sr-only">
          {` ${accessibleName}`}
          {newTab && href ? ' (opens in a new tab)' : ''}
        </span>
      </>
    )

    return (
      <sup className={['mx-0.5 align-super', className].filter(Boolean).join(' ')}>
        {href ? (
          <a
            href={href}
            aria-label={accessibleName + (newTab ? ' (opens in a new tab)' : '')}
            {...external}
            className="inline-grid size-[1.15em] place-items-center rounded-[0.25em] bg-muted text-[0.7em] font-medium leading-none tabular-nums text-muted-foreground no-underline transition-colors hover:bg-primary hover:text-primary-foreground focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-primary"
          >
            {index}
          </a>
        ) : (
          <span className="inline-grid size-[1.15em] place-items-center rounded-[0.25em] bg-muted text-[0.7em] font-medium leading-none tabular-nums text-muted-foreground">
            {chip}
          </span>
        )}
      </sup>
    )
  }

  return (
    <div
      className={[
        // `relative` is load-bearing: the title link stretches over the whole
        // card with `after:inset-0`, and an absolute child with no positioned
        // ancestor anchors to the page instead.
        'relative flex gap-2.5 rounded-lg border border-border bg-card p-2.5',
        href ? 'transition-colors hover:border-primary/40' : '',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
    >
      <span
        aria-hidden="true"
        className="mt-0.5 grid size-5 shrink-0 place-items-center rounded bg-muted text-[11px] font-medium tabular-nums text-muted-foreground"
      >
        {index}
      </span>

      <div className="min-w-0 flex-1">
        <cite className="block truncate text-sm font-medium not-italic text-foreground">
          {href ? (
            <a
              href={href}
              aria-label={accessibleName + (newTab ? ' (opens in a new tab)' : '')}
              {...external}
              className="no-underline outline-none after:absolute after:inset-0 hover:underline focus-visible:underline"
            >
              {title}
            </a>
          ) : (
            title
          )}
        </cite>
        {source ? <p className="mt-0.5 truncate text-xs text-muted-foreground">{source}</p> : null}
        {snippet ? (
          <p className="mt-1.5 line-clamp-2 text-xs leading-relaxed text-muted-foreground">
            {snippet}
          </p>
        ) : null}
      </div>
    </div>
  )
}

prompt-suggestions.source:
'use client'

/**
 * <PromptSuggestions> — the starters that fill an empty thread.
 *
 * The blank conversation is the highest-leverage screen in an assistant and
 * usually ships as a centred logo. A visitor who does not know what the
 * thing can be asked asks nothing, so this is the control that answers
 * "what do I type" — and it is the reusable half of the catalog's
 * `<ChatEmptyState>` block, which is the whole screen with headings and a
 * capability strip around it.
 *
 * **A real `<ul>` of real `<button>`s.** The overwhelmingly common shape is
 * a grid of `<div>`s with click handlers, which cannot be reached by
 * keyboard at all and gives a screen reader no indication that there are
 * four of anything. A list announces "list, 4 items" and can be skipped in
 * one keystroke by someone who does not want them.
 *
 * **The heading owns the list.** `aria-labelledby` ties the two together,
 * because "list, 4 items" with no subject is barely better than silence.
 *
 * **The accessible name is the prompt, not the label.** A tile reading
 * "Summarise this…" is a truncation; what gets sent is a full sentence.
 * Where they differ, the button is named for what it will actually do — the
 * visible text stays short, and nobody clicks a thing whose name was cut
 * off mid-word.
 *
 * **`type="button"`, explicitly.** These sit next to a composer, and a
 * bare `<button>` inside a `<form>` defaults to `submit` — which would send
 * the empty prompt instead of filling it.
 */

import * as React from 'react'

export interface PromptSuggestion {
  /** Falls back to `label` when absent. */
  id?: string
  /** The short text on the tile. */
  label: string
  /** A second line of context. Optional. */
  description?: string
  /** Any node — an emoji, an icon, an avatar. Decorative, so it is hidden. */
  icon?: React.ReactNode
  /** What actually gets sent, when it differs from the label. */
  prompt?: string
}

export interface PromptSuggestionsProps {
  suggestions: PromptSuggestion[]
  /** Rendered above the list and used as its accessible name. */
  heading?: string
  /** Receives the full prompt — `prompt ?? label`. */
  onSelect?: (prompt: string, suggestion: PromptSuggestion) => void
  columns?: 1 | 2
  className?: string
}

export function PromptSuggestions({
  suggestions,
  heading = 'Try one of these',
  onSelect,
  columns = 2,
  className = '',
}: PromptSuggestionsProps) {
  const uid = React.useId()

  return (
    <div className={['w-full', className].filter(Boolean).join(' ')}>
      {heading ? (
        <h3
          id={`${uid}-heading`}
          className="mb-2 text-xs font-medium uppercase tracking-wide text-muted-foreground"
        >
          {heading}
        </h3>
      ) : null}

      <ul
        aria-labelledby={heading ? `${uid}-heading` : undefined}
        className={[
          'grid gap-2',
          columns === 2 ? 'sm:grid-cols-2' : 'grid-cols-1',
        ].join(' ')}
      >
        {suggestions.map((suggestion) => {
          const prompt = suggestion.prompt ?? suggestion.label
          const named = prompt !== suggestion.label

          return (
            <li key={suggestion.id ?? suggestion.label}>
              <button
                type="button"
                onClick={() => onSelect?.(prompt, suggestion)}
                aria-label={named ? prompt : undefined}
                className="flex h-full w-full items-start gap-2.5 rounded-xl border border-border bg-card p-3 text-start transition-colors hover:border-primary/40 hover:bg-muted/60 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary"
              >
                {suggestion.icon ? (
                  <span aria-hidden="true" className="mt-0.5 shrink-0 text-muted-foreground">
                    {suggestion.icon}
                  </span>
                ) : null}
                <span className="min-w-0">
                  <span className="block text-sm font-medium text-foreground">
                    {suggestion.label}
                  </span>
                  {suggestion.description ? (
                    <span className="mt-0.5 block text-xs leading-relaxed text-muted-foreground">
                      {suggestion.description}
                    </span>
                  ) : null}
                </span>
              </button>
            </li>
          )
        })}
      </ul>
    </div>
  )
}

content-divider.source:
/**
 * <ContentDivider> — a rule with something in the middle of it.
 *
 * The "or" between a social sign-in row and an email form, the date
 * separator in a message thread, the "3 unread" marker in an inbox. It is
 * two rules and a label, and the hard part is that the label must sit ON
 * the line without a background colour matching the page — the trick of
 * putting `bg-background` behind the text breaks the moment the divider is
 * used on a card, a modal, or a tinted section.
 *
 * So the rules are flex children that grow, and the label sits between
 * them. No background, no negative margins, no assumption about what is
 * behind it.
 *
 * `role="separator"` with a label is the semantic that matches what a
 * sighted user sees. Without the label a divider is decorative and should
 * be `aria-hidden`; with one, the text is meaningful — "or", "Today",
 * "Unread from here" — and it is the only place that information appears.
 */

import * as React from 'react'

export interface ContentDividerProps {
  /** The text or node in the middle. Omit for a plain rule. */
  children?: React.ReactNode
  /** Where the label sits along the rule. */
  align?: 'center' | 'start' | 'end'
  orientation?: 'horizontal' | 'vertical'
  tone?: 'default' | 'strong' | 'accent'
  /** Dashed rule — for drop targets and "add here" affordances. */
  dashed?: boolean
  className?: string
}

export function ContentDivider({
  children,
  align = 'center',
  orientation = 'horizontal',
  tone = 'default',
  dashed = false,
  className = '',
}: ContentDividerProps) {
  const line = [
    'shrink-0',
    dashed ? 'border-dashed' : 'border-solid',
    tone === 'strong'
      ? 'border-foreground/25'
      : tone === 'accent'
        ? 'border-primary/40'
        : 'border-border',
  ].join(' ')

  if (orientation === 'vertical') {
    return (
      <div
        role="separator"
        aria-orientation="vertical"
        className={`inline-flex h-full flex-col items-center ${className}`}
      >
        <span aria-hidden className={`${line} w-0 flex-1 border-s`} />
        {children ? (
          <span className="py-2 text-xs font-medium text-muted-foreground">{children}</span>
        ) : null}
        <span aria-hidden className={`${line} w-0 flex-1 border-s`} />
      </div>
    )
  }

  if (!children) {
    return (
      <hr
        // A bare rule carries no information a screen reader needs; the
        // heading structure around it is what conveys the break.
        aria-hidden
        className={`${line} border-0 border-t ${className}`}
      />
    )
  }

  return (
    <div
      role="separator"
      className={`flex w-full items-center gap-3 ${className}`}
    >
      {/*
        The rules are flex children, so the label needs no background to
        stand on. `flex-1` on both for centre; on one side only for a
        start- or end-aligned label — which is why this is logical
        (`start`/`end`) rather than left and right.
      */}
      <span
        aria-hidden
        className={`${line} border-0 border-t ${align === 'start' ? 'w-4' : 'flex-1'}`}
      />
      <span className="shrink-0 text-xs font-medium uppercase tracking-wide text-muted-foreground">
        {children}
      </span>
      <span
        aria-hidden
        className={`${line} border-0 border-t ${align === 'end' ? 'w-4' : 'flex-1'}`}
      />
    </div>
  )
}

laptop-frame.source:
/**
 * <LaptopFrame> — a lid, a hinge and a base around your own content.
 *
 * The one frame people reach for in a hero, and the one that is almost
 * always a PNG. As markup it costs three divs, inherits dark mode, and lets
 * the screen hold a live interface rather than a picture of one.
 *
 * The base is the part worth getting right and the part every CSS version
 * gets wrong. A real laptop's base is wider than its lid and tapers — so it
 * is drawn as a trapezoid, with the taper done by `clip-path` rather than by
 * the old border trick. Borders cannot be rounded independently and cannot
 * carry a background, which is why the border version always ends up as a
 * flat grey wedge with a hard edge.
 *
 * `clip-path` degrades safely: with no support the base renders as a plain
 * rectangle, which is a slightly boxier laptop and nothing worse.
 */

import * as React from 'react'

export interface LaptopFrameProps {
  children?: React.ReactNode
  /** Rendered width of the lid. The base extends past it on both sides. */
  width?: number
  /** Aspect ratio of the screen, as a Tailwind class. */
  aspect?: string
  /** Draw the base and hinge. Off gives a bare monitor. */
  base?: boolean
  className?: string
}

export function LaptopFrame({
  children,
  width = 420,
  aspect = 'aspect-[16/10]',
  base = true,
  className = '',
}: LaptopFrameProps) {
  return (
    <div className={`shrink-0 ${className}`} style={{ width }}>
      <div className="overflow-hidden rounded-xl border-[10px] border-b-[14px] border-foreground/85 bg-foreground/85 shadow-xl">
        <div className={`${aspect} relative w-full overflow-hidden bg-background`}>
          <span
            aria-hidden
            className="absolute left-1/2 top-1 z-10 size-1 -translate-x-1/2 rounded-full bg-foreground/30"
          />
          {children}
        </div>
      </div>

      {base ? (
        <div aria-hidden className="relative mx-auto" style={{ width: '112%' }}>
          <div
            className="h-3 rounded-b-lg bg-foreground/85"
            // 2.6% on each side is the taper. Expressed as a percentage so it
            // holds at any `width`, which a pixel value would not.
            style={{ clipPath: 'polygon(2.6% 0, 97.4% 0, 94% 100%, 6% 100%)' }}
          />
          {/* The notch a thumb goes into. Drawn as a light bar on the base
              rather than as a cut-out, because a cut-out needs a second
              clip-path and shows the page through the laptop. */}
          <div className="absolute left-1/2 top-0 h-1 w-16 -translate-x-1/2 rounded-b-md bg-background/25" />
        </div>
      ) : null}
    </div>
  )
}

device-showcase.source:
/**
 * <DeviceShowcase> — a laptop with a handset overlapping it.
 *
 * The arrangement every product hero uses, and the one that is fiddly enough
 * that people paste a screenshot of it instead. Two things make it fiddly and
 * both are handled here:
 *
 * 1. **The overlap is a negative margin, not absolute positioning.** Absolute
 *    positioning takes the phone out of flow, so the container collapses to
 *    the laptop's height and the phone hangs over whatever is below it. A
 *    negative inline-start margin keeps both in flow and keeps the group's
 *    height honest.
 *
 * 2. **It stacks rather than shrinking.** Below `sm` the two frames sit one
 *    above the other with the overlap removed, because a laptop scaled to fit
 *    a 360px viewport has a screen 200px wide and shows nothing. Every
 *    image-based version of this arrangement simply gets smaller.
 *
 * The negative margin is `-ms-` and not `-ml-`, so the phone sits on the
 * correct side of the laptop in an RTL layout rather than off the far edge.
 */

import * as React from 'react'

import { LaptopFrame } from './laptop-frame'
import { PhoneFrame } from './phone-frame'

export interface DeviceShowcaseProps {
  /** What the laptop shows. */
  desktop?: React.ReactNode
  /** What the handset shows. */
  mobile?: React.ReactNode
  /** Which side the handset sits on. */
  phoneSide?: 'start' | 'end'
  /** Laptop width in px; the handset is sized from it. */
  width?: number
  className?: string
}

export function DeviceShowcase({
  desktop,
  mobile,
  phoneSide = 'end',
  width = 460,
  className = '',
}: DeviceShowcaseProps) {
  const phone = (
    <PhoneFrame
      width={Math.round(width * 0.3)}
      buttons={false}
      className={
        phoneSide === 'end'
          ? 'z-10 -ms-10 mt-10 hidden sm:block'
          : 'z-10 -me-10 mt-10 hidden sm:block'
      }
    >
      {mobile}
    </PhoneFrame>
  )

  return (
    <div className={`flex flex-col items-center gap-6 sm:flex-row sm:items-end sm:gap-0 ${className}`}>
      {phoneSide === 'start' ? phone : null}
      <LaptopFrame width={width}>{desktop}</LaptopFrame>
      {phoneSide === 'end' ? phone : null}

      {/* The stacked fallback. Rendered only below `sm`, where the overlapped
          copy above is hidden — two elements rather than one so neither
          layout has to fight the other's margins. */}
      <div className="sm:hidden">
        <PhoneFrame width={Math.round(width * 0.42)} buttons={false}>
          {mobile}
        </PhoneFrame>
      </div>
    </div>
  )
}

/**
 * <LaptopFrame> — a lid, a hinge and a base around your own content.
 *
 * The one frame people reach for in a hero, and the one that is almost
 * always a PNG. As markup it costs three divs, inherits dark mode, and lets
 * the screen hold a live interface rather than a picture of one.
 *
 * The base is the part worth getting right and the part every CSS version
 * gets wrong. A real laptop's base is wider than its lid and tapers — so it
 * is drawn as a trapezoid, with the taper done by `clip-path` rather than by
 * the old border trick. Borders cannot be rounded independently and cannot
 * carry a background, which is why the border version always ends up as a
 * flat grey wedge with a hard edge.
 *
 * `clip-path` degrades safely: with no support the base renders as a plain
 * rectangle, which is a slightly boxier laptop and nothing worse.
 */

import * as React from 'react'

export interface LaptopFrameProps {
  children?: React.ReactNode
  /** Rendered width of the lid. The base extends past it on both sides. */
  width?: number
  /** Aspect ratio of the screen, as a Tailwind class. */
  aspect?: string
  /** Draw the base and hinge. Off gives a bare monitor. */
  base?: boolean
  className?: string
}

export function LaptopFrame({
  children,
  width = 420,
  aspect = 'aspect-[16/10]',
  base = true,
  className = '',
}: LaptopFrameProps) {
  return (
    <div className={`shrink-0 ${className}`} style={{ width }}>
      <div className="overflow-hidden rounded-xl border-[10px] border-b-[14px] border-foreground/85 bg-foreground/85 shadow-xl">
        <div className={`${aspect} relative w-full overflow-hidden bg-background`}>
          <span
            aria-hidden
            className="absolute left-1/2 top-1 z-10 size-1 -translate-x-1/2 rounded-full bg-foreground/30"
          />
          {children}
        </div>
      </div>

      {base ? (
        <div aria-hidden className="relative mx-auto" style={{ width: '112%' }}>
          <div
            className="h-3 rounded-b-lg bg-foreground/85"
            // 2.6% on each side is the taper. Expressed as a percentage so it
            // holds at any `width`, which a pixel value would not.
            style={{ clipPath: 'polygon(2.6% 0, 97.4% 0, 94% 100%, 6% 100%)' }}
          />
          {/* The notch a thumb goes into. Drawn as a light bar on the base
              rather than as a cut-out, because a cut-out needs a second
              clip-path and shows the page through the laptop. */}
          <div className="absolute left-1/2 top-0 h-1 w-16 -translate-x-1/2 rounded-b-md bg-background/25" />
        </div>
      ) : null}
    </div>
  )
}
